-- Schema for Domain: finance | Business: Power and Utilities | Version: v1_ecm
-- Generated on: 2026-05-05 03:11:16

-- ========= DATABASE =========
CREATE DATABASE IF NOT EXISTS `power_and_utilities_v2`.`finance` COMMENT 'Corporate financial management serving as the SSOT for general ledger, cost centers, capital project accounting, budgeting, financial planning, CAPEX/OPEX tracking, depreciation, and financial reporting. Manages chart of accounts, RAB valuation, ROE calculations, EBITDA reporting, and FASB ASC 980 regulatory asset/liability accounting. Supports rate case cost-of-service studies and FERC Form 1 reporting. Integrates with SAP FI/CO.';

-- ========= TABLES =========
CREATE OR REPLACE TABLE `power_and_utilities_v2`.`finance`.`chart_of_accounts` (
    `chart_of_accounts_id` BIGINT COMMENT 'Unique surrogate identifier for each general ledger account record in the chart of accounts. Serves as the primary key for all downstream joins and references across the finance domain.',
    `account_class` STRING COMMENT 'High-level financial statement classification of the account indicating its role in the balance sheet or income statement. Values: asset, liability, equity, revenue, expense, other. Drives financial statement presentation and FERC Form 1 schedule mapping.. Valid values are `asset|liability|equity|revenue|expense|other`',
    `account_group` STRING COMMENT 'SAP FI/CO account group (field KTOKS) that controls the number range and field status for this GL account. Account groups organize accounts into logical segments (e.g., utility plant, O&M expenses, revenue accounts) for master data governance.',
    `account_status` STRING COMMENT 'Current lifecycle status of the GL account within the chart of accounts. Active accounts accept financial postings; blocked accounts are temporarily restricted; marked_for_deletion accounts are pending archival. Controls posting eligibility in SAP FI/CO.. Valid values are `active|inactive|blocked|marked_for_deletion`',
    `account_type` STRING COMMENT 'SAP FI/CO account type indicator (field KTOKS) classifying the account as balance sheet, profit and loss, non-operating, or statistical. Controls how balances are carried forward at year-end and how the account behaves in financial close processes.. Valid values are `balance_sheet|profit_loss|nonoperating|statistical`',
    `alternative_account_number` STRING COMMENT 'Country-specific or local statutory account number (SAP field ALTKT) used for local GAAP or statutory reporting requirements in jurisdictions where the utility operates. Supports mapping between FERC USoA accounts and state-specific chart of accounts requirements.',
    `chart_of_accounts_code` STRING COMMENT 'SAP FI/CO chart-of-accounts key (field KTOPL) identifying the specific chart of accounts plan to which this account belongs (e.g., UTIL for the utility operating chart, CONS for consolidated). Supports multi-company-code deployments.. Valid values are `^[A-Z0-9]{4}$`',
    `company_code` STRING COMMENT 'SAP FI/CO company code (field BUKRS) to which this account is assigned, representing the legal entity or subsidiary within the utility holding company structure. Enables multi-entity financial consolidation and separate regulatory reporting per legal entity.. Valid values are `^[A-Z0-9]{4}$`',
    `consolidation_account_number` STRING COMMENT 'The group-level or holding company consolidation account number to which this operating entity GL account maps for intercompany elimination and consolidated financial statement preparation. Supports multi-entity utility holding company structures.',
    `controlling_area` STRING COMMENT 'SAP CO controlling area code (field KOKRS) to which this account is relevant for management accounting, cost center accounting, and internal order settlement. Links GL accounts to the CO module for CAPEX/OPEX tracking and EBITDA reporting.. Valid values are `^[A-Z0-9]{4}$`',
    `cost_category` STRING COMMENT 'Classifies the account as capital expenditure (CAPEX), operating expenditure (OPEX), regulatory asset, regulatory liability, or other. Critical for rate case cost-of-service studies, RAB valuation, and FASB ASC 980 regulatory accounting treatment.. Valid values are `capex|opex|regulatory_asset|regulatory_liability|other`',
    `cost_element_category` STRING COMMENT 'SAP CO cost element category indicating whether the account is a primary cost element (originating from FI postings), secondary cost element (internal allocations only), or not applicable. Governs cost flow in SAP CO for rate case cost-of-service studies.. Valid values are `primary|secondary|not_applicable`',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when this chart of accounts record was first created in the source system (SAP FI/CO). Provides audit trail for master data governance, SOX compliance, and data lineage tracking in the Databricks Silver layer.',
    `currency_code` STRING COMMENT 'ISO 4217 three-letter currency code for the accounts operating currency (e.g., USD). Supports multi-currency reporting for utilities with cross-border operations or foreign-denominated PPAs and energy trading contracts.. Valid values are `^[A-Z]{3}$`',
    `deactivation_date` DATE COMMENT 'Date on which this GL account was deactivated or blocked from further postings. Null for currently active accounts. Supports chart of accounts lifecycle management and historical financial reporting for prior periods.',
    `depreciation_method` STRING COMMENT 'Depreciation method applied to plant accounts associated with this GL account for regulatory and book depreciation purposes. Straight-line is the standard method for regulated utility plant per FERC USoA and PUC-approved depreciation studies.. Valid values are `straight_line|declining_balance|units_of_production|not_applicable`',
    `depreciation_relevant` BOOLEAN COMMENT 'Indicates whether this account is subject to depreciation calculations in SAP Asset Accounting (AA). Relevant for utility plant accounts included in the Regulatory Asset Base (RAB) and depreciation studies filed with the PUC.',
    `ebitda_category` STRING COMMENT 'Maps this account to its EBITDA component for management reporting and investor relations disclosures. Enables automated EBITDA bridge calculations from the general ledger without manual reclassification.. Valid values are `earnings|interest|tax|depreciation|amortization|not_applicable`',
    `effective_date` DATE COMMENT 'Date on which this GL account became effective and available for financial postings. Supports historical chart of accounts versioning for rate case cost-of-service studies referencing prior test year periods.',
    `ferc_account_description` STRING COMMENT 'Official FERC USoA account title and description corresponding to the mapped FERC account number. Provides regulatory context for auditors, rate case analysts, and FERC Form 1 preparers.',
    `ferc_account_number` STRING COMMENT 'The FERC Uniform System of Accounts (USoA) account number to which this GL account maps for regulatory reporting purposes. Used in FERC Form 1 annual report filings and rate case cost-of-service studies. Format follows FERC USoA three-digit primary account with optional sub-account suffix (e.g., 101, 303.1).. Valid values are `^[0-9]{3}(.([0-9]{1,3}))?$`',
    `ferc_schedule_reference` STRING COMMENT 'Reference to the specific FERC Form 1 schedule and line number where balances in this account are reported (e.g., Schedule F1-200 Line 10). Enables automated mapping of GL balances to FERC regulatory filings.',
    `field_status_group` STRING COMMENT 'SAP FI/CO field status group (field FSTAG) assigned to this account, controlling which fields are required, optional, or suppressed during journal entry posting. Ensures data completeness for cost center, profit center, and project assignments on regulated utility accounts.. Valid values are `^G[0-9]{3}$`',
    `functional_area_relevant` BOOLEAN COMMENT 'Indicates whether postings to this account require a functional area assignment in SAP FI/CO for cost-of-function reporting. Supports FERC Form 1 functional classification between production, transmission, distribution, and customer service.',
    `functional_class` STRING COMMENT 'FERC USoA functional classification indicating the utility service function to which the account relates. Drives cost-of-service allocation between electric and gas operations for rate case filings and FERC Form 1 reporting. [ENUM-REF-CANDIDATE: electric_plant|gas_plant|common_plant|general_plant|other — promote to reference product]. Valid values are `electric_plant|gas_plant|common_plant|general_plant|other`',
    `gl_account_long_description` STRING COMMENT 'Extended narrative description of the general ledger account purpose, scope, and allowable posting types. Supports regulatory filings, auditor inquiries, and rate case cost-of-service documentation.',
    `gl_account_name` STRING COMMENT 'Short descriptive name of the general ledger account as maintained in SAP FI/CO (field TXTKS/TXT50). Used as the human-readable identity label displayed in financial reports, trial balances, and rate case filings.',
    `gl_account_number` STRING COMMENT 'The externally-known alphanumeric code uniquely identifying the general ledger account within the SAP FI/CO chart of accounts. Used as the primary business identifier for financial postings, rate case cost-of-service studies, and FERC Form 1 reporting. Typically a 6- to 10-digit numeric string aligned with the FERC Uniform System of Accounts numbering convention.. Valid values are `^[0-9]{6,10}$`',
    `house_bank_relevant` BOOLEAN COMMENT 'Indicates whether this GL account is a bank account managed through SAP FI house bank configuration. When True, the account is linked to a physical bank account for cash management, treasury operations, and bank reconciliation.',
    `intercompany_flag` BOOLEAN COMMENT 'Indicates whether this account is used for intercompany transactions between affiliated entities within the utility holding company structure. Intercompany accounts are subject to elimination in consolidated financial statements and FERC affiliate transaction rules.',
    `last_changed_timestamp` TIMESTAMP COMMENT 'Timestamp of the most recent modification to this chart of accounts master record in SAP FI/CO (fields LAEDA/LAEDT). Supports change management auditing, SOX compliance, and incremental data loading in the Databricks Silver layer.',
    `line_item_display` BOOLEAN COMMENT 'SAP FI/CO indicator (field XKRES) specifying whether individual line items are stored and displayed for this account. When True, individual journal entry line items are retained for audit trail and detailed account analysis. Required for reconciliation accounts and high-value utility plant accounts.',
    `normal_balance` STRING COMMENT 'Indicates whether the account normally carries a debit or credit balance per double-entry bookkeeping conventions. Used by SAP FI/CO to validate postings and by financial reporting to detect sign anomalies.. Valid values are `debit|credit`',
    `om_category` STRING COMMENT 'Sub-classification of expense accounts into Operations, Maintenance, or Administrative and General (A&G) per FERC USoA conventions. Used in O&M cost tracking, rate case testimony, and EBITDA reporting.. Valid values are `operation|maintenance|administrative_general|other`',
    `open_item_management` BOOLEAN COMMENT 'SAP FI/CO indicator (field XOPVW) specifying whether open item management is active for this account. When True, individual postings remain open until cleared by a matching offsetting entry. Used for clearing accounts, suspense accounts, and intercompany accounts.',
    `plant_function` STRING COMMENT 'FERC USoA plant function sub-classification for utility plant accounts (e.g., Steam Production, Nuclear Production, Transmission, Distribution, General). Used in rate base (RAB) calculations and depreciation studies. [ENUM-REF-CANDIDATE: steam_production|nuclear_production|hydraulic_production|other_production|transmission|distribution|general — promote to reference product]',
    `posting_blocked` BOOLEAN COMMENT 'Flag indicating whether direct financial postings to this account are currently blocked in SAP FI/CO (field XSPEB). When True, the account cannot receive new journal entries until unblocked by an authorized finance administrator.',
    `profit_center_relevant` BOOLEAN COMMENT 'Indicates whether postings to this account require a profit center assignment in SAP CO. When True, all journal entries must carry a profit center, enabling segment-level P&L reporting for electric vs. gas operations and regulatory ring-fencing.',
    `rab_inclusion_flag` BOOLEAN COMMENT 'Indicates whether this account contributes to the Regulatory Asset Base (RAB) used in rate-of-return calculations and ROE determination. RAB-included accounts form the basis for allowed revenue requirement in rate case filings.',
    `rate_case_inclusion_flag` BOOLEAN COMMENT 'Indicates whether balances in this account are included in the cost-of-service study for General Rate Case (GRC) or FERC rate case filings. Accounts flagged True are subject to regulatory scrutiny and must be supported by workpapers.',
    `reconciliation_account_flag` BOOLEAN COMMENT 'Indicates whether this GL account is a reconciliation account (subledger control account) in SAP FI/CO. Reconciliation accounts aggregate balances from subledgers (AP, AR, asset accounting) and cannot receive direct manual postings.',
    `reconciliation_account_type` STRING COMMENT 'Specifies the subledger type for reconciliation accounts in SAP FI/CO (field MITKZ): accounts receivable, accounts payable, fixed assets, or not applicable for non-reconciliation accounts. Governs which subledger module posts to this control account.. Valid values are `accounts_receivable|accounts_payable|fixed_assets|not_applicable`',
    `regulatory_asset_flag` BOOLEAN COMMENT 'Indicates whether this account records a regulatory asset as defined under FASB ASC 980 Regulated Operations. Regulatory assets represent costs deferred for future recovery in rates approved by the PUC or FERC. Critical for RAB valuation and rate case filings.',
    `regulatory_liability_flag` BOOLEAN COMMENT 'Indicates whether this account records a regulatory liability as defined under FASB ASC 980 Regulated Operations. Regulatory liabilities represent obligations to return over-collected revenues or costs to customers through future rate reductions.',
    `sort_key` STRING COMMENT 'SAP FI/CO sort key (field ZUAWA) that determines the assignment field populated in line items for this account, controlling how line items are sorted and displayed in account statements. Common values include 001 (posting date), 012 (document number).. Valid values are `^[0-9]{3}$`',
    `tax_category` STRING COMMENT 'SAP FI/CO tax category indicator (field MWSKZ) specifying whether the account is relevant for input tax, output tax, or is tax-exempt. Drives automatic tax determination during financial postings for utility sales tax and use tax compliance. [ENUM-REF-CANDIDATE: input_tax|output_tax|tax_exempt|not_relevant — promote to reference product]',
    `useful_life_years` DECIMAL(18,2) COMMENT 'PUC-approved or FERC-approved estimated useful life in years for plant accounts subject to depreciation. Used in straight-line depreciation rate calculations for rate base recovery and FERC Form 1 depreciation schedules.',
    CONSTRAINT pk_chart_of_accounts PRIMARY KEY(`chart_of_accounts_id`)
) COMMENT 'Master repository of all general ledger account codes used by the utility, organized by account class (assets, liabilities, equity, revenues, expenses, O&M). Aligned with FERC Uniform System of Accounts (USoA) and FASB ASC 980 regulated operations classifications. Serves as the foundational reference for all financial postings across SAP FI/CO, rate case cost-of-service studies, and FERC Form 1 reporting.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`finance`.`cost_center` (
    `cost_center_id` BIGINT COMMENT 'Unique surrogate identifier for the cost center or internal order record in the Databricks Silver Layer. Primary key for this entity.',
    `facility_id` BIGINT COMMENT 'Foreign key linking to property.facility. Business justification: Cost centers are assigned to facilities to allocate operating expenses per building or plant.',
    `parcel_id` BIGINT COMMENT 'Foreign key linking to property.parcel. Business justification: Cost centers are organized by geographic parcels for OPEX reporting and internal cost allocation.',
    `profit_center_id` BIGINT COMMENT 'FK to finance.profit_center',
    `activity_type_code` STRING COMMENT 'SAP CO activity type code associated with this cost center, defining the type of work or service output (e.g., labor hours, machine hours, kWh produced). Activity types are used to calculate activity prices and allocate costs to cost objects such as maintenance orders and capital projects.. Valid values are `^[A-Z0-9_-]{1,6}$`',
    `allocation_basis` STRING COMMENT 'The statistical or activity-based basis used to allocate costs from this cost center (e.g., headcount, floor area, kWh consumed, labor hours). Used in overhead cost allocation cycles and cost-of-service studies to distribute shared costs equitably across cost objects and customer classes.',
    `allocation_method` STRING COMMENT 'SAP CO allocation method used to distribute costs from this cost center to other cost objects. direct posts costs directly; assessment uses assessment cycles to allocate overhead; distribution reallocates primary costs; periodic_reposting corrects mispostings. Drives month-end cost closing procedures.. Valid values are `direct|assessment|distribution|periodic_reposting|template`',
    `annual_opex_budget` DECIMAL(18,2) COMMENT 'Approved annual OPEX budget amount for this cost center in the controlling currency. Represents the authorized spending limit for operations and maintenance activities. Used in budget variance analysis, rate case cost-of-service studies, and EBITDA reporting.',
    `budget_fiscal_year` STRING COMMENT 'The fiscal year (four-digit integer, e.g., 2025) to which the annual OPEX budget applies. Aligns with the utilitys regulatory fiscal year for rate case filings and FERC Form 1 annual reporting.',
    `business_area_code` STRING COMMENT 'SAP Business Area code representing a distinct area of operations for internal balance sheet and P&L reporting. For utilities, commonly used to separate electric, gas, and corporate segments for regulatory reporting and FERC jurisdictional cost separation.. Valid values are `^[A-Z0-9]{1,4}$`',
    `company_code` STRING COMMENT 'SAP company code representing the legal entity or regulated subsidiary to which this cost center is assigned. Used for statutory financial reporting, FERC Form 1 filing, and separation of electric vs. gas utility accounts per regulatory requirements.. Valid values are `^[A-Z0-9]{1,4}$`',
    `controlling_area_code` STRING COMMENT 'SAP Controlling Area code to which this cost center belongs. The controlling area defines the organizational unit within which cost accounting is performed. For a utility, typically maps to the legal entity or regulated operating company (e.g., electric vs. gas utility segment).. Valid values are `^[A-Z0-9]{1,4}$`',
    `cost_center_category` STRING COMMENT 'SAP CO cost center category code that controls which activity types and statistical key figures can be posted. Common utility categories include E (Energy/Production), F (Field Operations), G (General Administration), V (Service/Overhead). Drives cost allocation rules and activity rate calculations. [ENUM-REF-CANDIDATE: E|F|G|V|P|I|H|D — promote to reference product]',
    `cost_center_code` STRING COMMENT 'The externally-known alphanumeric code assigned to the cost center in SAP CO, used across all financial transactions, journal entries, and cost allocations. Serves as the business identifier referenced in FERC Form 1 reporting and rate case cost-of-service studies.. Valid values are `^[A-Z0-9_-]{1,20}$`',
    `cost_center_description` STRING COMMENT 'Long-form textual description of the cost centers purpose, scope, and organizational context. Provides additional detail beyond the short name for use in financial reports, rate case documentation, and audit support.',
    `cost_center_name` STRING COMMENT 'Human-readable descriptive name of the cost center (e.g., Transmission District 3 Operations, Nuclear Generation Plant A, Storm Restoration Pool). Used in financial reports, budget presentations, and rate case filings.',
    `cost_center_status` STRING COMMENT 'Current lifecycle status of the cost center. active indicates the cost center is open for postings; locked prevents new postings while retaining history; closed indicates the cost center has been decommissioned. Controls whether financial transactions can be posted against this cost center in SAP CO.. Valid values are `active|inactive|locked|pending_activation|closed`',
    `cost_center_type` STRING COMMENT 'Classifies whether this record represents a permanent cost center (e.g., generation plant, T&D district, corporate function) or a temporary cost collector such as an internal order for maintenance jobs, storm restoration events, or overhead pools. Drives allocation logic and reporting treatment. [ENUM-REF-CANDIDATE: permanent|internal_order|overhead_pool|storm_restoration|project_collector — promote to reference product]. Valid values are `permanent|internal_order|overhead_pool|storm_restoration|project_collector`',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when this cost center master record was first created in the source system (SAP CO). Supports audit trail requirements, data lineage tracking, and compliance with NERC CIP and FASB record retention requirements.',
    `currency_code` STRING COMMENT 'ISO 4217 three-letter currency code for the cost centers controlling currency (e.g., USD). Defines the currency in which budgets, actual costs, and variances are recorded and reported for this cost center.. Valid values are `^[A-Z]{3}$`',
    `department_code` STRING COMMENT 'Organizational department code to which this cost center is assigned. Supports departmental budgeting, OPEX tracking, and organizational reporting. Aligns with the utilitys organizational chart and workforce management structure.. Valid values are `^[A-Z0-9_-]{1,10}$`',
    `ferc_account_code` STRING COMMENT 'FERC Uniform System of Accounts (USofA) account code associated with this cost center for regulatory financial reporting. Maps cost center expenditures to the prescribed FERC account structure required for Form 1 filing (e.g., Account 580 for Operation Supervision and Engineering - Transmission).. Valid values are `^[0-9]{3,6}$`',
    `functional_area_code` STRING COMMENT 'SAP Functional Area code used to classify costs by business function (e.g., Generation, Transmission, Distribution, Customer Service, Administration) for cost-of-service studies and FERC Form 1 functional reporting requirements.',
    `group_code` STRING COMMENT 'Code identifying the cost center group (hierarchy node) to which this cost center belongs in the SAP CO standard hierarchy. Supports hierarchical OPEX reporting, departmental budgeting roll-ups, and organizational cost aggregation for rate case filings.',
    `hierarchy_level` STRING COMMENT 'Numeric level of this cost center within the SAP CO standard hierarchy (e.g., 1=Corporate, 2=Division, 3=Department, 4=Work Group). Supports hierarchical roll-up reporting for OPEX budgeting and rate case cost-of-service studies.',
    `is_capital_project` BOOLEAN COMMENT 'Indicates whether this cost center (or internal order) is used as a capital project cost collector for CAPEX tracking. When True, costs are subject to capitalization rules under FASB ASC 360 and are tracked for inclusion in the Regulatory Asset Base (RAB) for rate case filings.',
    `is_regulatory_asset` BOOLEAN COMMENT 'Indicates whether costs accumulated in this cost center qualify as a regulatory asset under FASB ASC 980 (Regulated Operations). When True, deferred costs are expected to be recovered through future rate cases and are tracked for RAB valuation and ROE calculations.',
    `is_storm_restoration` BOOLEAN COMMENT 'Indicates whether this cost center is designated for storm restoration cost capture. When True, costs posted here are tracked separately for regulatory recovery filings with state PUCs, FEMA reimbursement claims, and storm cost deferral accounting under FASB ASC 980.',
    `last_modified_timestamp` TIMESTAMP COMMENT 'Timestamp of the most recent modification to this cost center master record in the source system. Used for change detection in ETL pipelines, audit trail maintenance, and compliance reporting.',
    `location_code` STRING COMMENT 'Physical location or facility code associated with this cost center (e.g., generation plant site code, substation identifier, district office code). Links cost center to a geographic or facility location for asset management integration and GIS-based cost reporting.. Valid values are `^[A-Z0-9_-]{1,20}$`',
    `lock_indicator` STRING COMMENT 'SAP CO lock indicator controlling which types of postings are permitted. locked_actual prevents actual cost postings; locked_plan prevents planning entries; locked_all blocks all postings. Used during period-end close, audits, and cost center decommissioning.. Valid values are `unlocked|locked_actual|locked_plan|locked_all`',
    `overhead_rate` DECIMAL(18,2) COMMENT 'Overhead allocation rate applied to this cost center, expressed as a percentage or fixed amount per activity unit. Used in SAP CO overhead costing sheets to allocate indirect costs (e.g., administrative overhead, facilities costs) to production orders, maintenance orders, and capital projects.',
    `overhead_rate_type` STRING COMMENT 'Specifies whether the overhead rate is applied as a percentage of direct costs, a fixed monetary amount, or an activity-based rate per unit of activity (e.g., per labor hour, per kWh generated). Determines the overhead calculation method in SAP CO.. Valid values are `percentage|fixed_amount|activity_based`',
    `parent_cost_center_code` STRING COMMENT 'Code of the parent cost center in the organizational hierarchy, enabling hierarchical cost roll-up reporting. Supports the construction of cost center trees for budget consolidation, OPEX allocation, and management reporting.. Valid values are `^[A-Z0-9_-]{1,20}$`',
    `rate_case_classification` STRING COMMENT 'Functional classification of this cost center for rate case cost-of-service studies filed with state PUCs or FERC. Determines how costs are allocated across customer classes and rate schedules. Aligns with FERC Uniform System of Accounts functional categories. [ENUM-REF-CANDIDATE: generation|transmission|distribution|gas_distribution|customer_service|administrative|common — promote to reference product]',
    `short_name` STRING COMMENT 'Abbreviated name of the cost center used in SAP CO reports, budget line items, and dashboard displays where space is constrained. Typically up to 20 characters per SAP standard.. Valid values are `^.{1,20}$`',
    `source_system_code` STRING COMMENT 'Identifier of the operational source system from which this cost center record was ingested (e.g., SAP_CO_PROD, SAP_CO_QA). Supports data lineage, multi-system reconciliation, and Silver Layer provenance tracking in the Databricks Lakehouse.. Valid values are `^[A-Z0-9_-]{1,20}$`',
    `utility_segment` STRING COMMENT 'Identifies whether this cost center belongs to the electric utility segment, gas utility segment, common/shared services, or other. Critical for regulatory cost separation, rate case cost-of-service studies, and FERC jurisdictional reporting. Drives allocation of shared costs between electric and gas rate bases.. Valid values are `electric|gas|common|other`',
    `work_center_code` STRING COMMENT 'SAP Work Center code linked to this cost center for activity-based costing. Work centers define the capacity and activity rates used to allocate labor and equipment costs to maintenance orders, production orders, and internal orders. Critical for O&M cost tracking.. Valid values are `^[A-Z0-9_-]{1,10}$`',
    `valid_from` DATE COMMENT 'The date from which this cost center is valid and open for financial postings in SAP CO. Defines the start of the cost centers active period. Used to enforce time-dependent master data validity and support historical cost reporting.',
    `valid_to` DATE COMMENT 'The date until which this cost center is valid for financial postings in SAP CO. A far-future date (e.g., 9999-12-31) indicates an open-ended cost center. When set to a past date, the cost center is effectively closed for new postings.',
    CONSTRAINT pk_cost_center PRIMARY KEY(`cost_center_id`)
) COMMENT 'Organizational cost collection master representing both permanent cost centers (generation plants, T&D districts, corporate functions) and temporary cost collectors (internal orders for maintenance jobs, storm restoration, overhead pools). Supports OPEX allocation, departmental budgeting, overhead cost pooling, storm restoration cost capture, activity-based cost tracking, and cost-of-service studies for rate case filings. Hierarchically organized by cost center group aligned with the utilitys organizational structure. Internal orders provide short-term cost collection for activities that do not warrant a full project structure.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`finance`.`gl_account` (
    `gl_account_id` BIGINT COMMENT 'Unique surrogate identifier for each general ledger account record in the Power and Utilities chart of accounts. Serves as the primary key for all financial posting references across SAP FI/CO, rate case studies, and FERC Form 1 reporting.',
    `chart_of_accounts_id` BIGINT COMMENT 'Foreign key linking to finance.chart_of_accounts. Business justification: GL Account must reference its Chart of Accounts for proper hierarchy and reporting; replace code with FK.',
    `account_class` STRING COMMENT 'Utility-specific classification grouping accounts into functional categories aligned with FERC USoA and FASB ASC 980 regulated operations. Supports rate case cost-of-service studies, RAB valuation, and FERC Form 1 schedule mapping. [ENUM-REF-CANDIDATE: utility_plant|accumulated_depreciation|regulatory_asset|regulatory_liability|current_asset|current_liability|long_term_debt|equity|operating_revenue|om_expense|depreciation_expense|tax_expense — promote to reference product]',
    `account_group` STRING COMMENT 'The SAP account group (SKA1-KTOKS) that controls the number range and field selection for the GL account master. Groups accounts by functional area (e.g., electric plant, gas plant, O&M, regulatory assets) to enforce consistent master data governance and number range assignments.',
    `account_hierarchy_level` STRING COMMENT 'The numeric level of this GL account within the financial statement hierarchy (e.g., 1=total, 2=major class, 3=subclass, 4=individual account). Supports hierarchical financial reporting, drill-down analysis in management dashboards, and structured presentation in FERC Form 1 schedules and rate case exhibits.',
    `account_long_name` STRING COMMENT 'The full descriptive name of the GL account (SAP SKB1-TXT50). Provides extended context for the account purpose, used in detailed financial reporting, audit documentation, and regulatory filings where full account descriptions are required.',
    `account_name` STRING COMMENT 'The short descriptive name of the GL account as maintained in SAP (SKB1-TXT20). Used in financial statements, trial balance reports, and rate case cost-of-service studies. Provides the human-readable label for the account number.',
    `account_number` STRING COMMENT 'The externally-known alphanumeric account number as defined in the SAP chart of accounts (SKB1-SAKNR). This is the primary business identifier used in all financial postings, journal entries, trial balances, and FERC Form 1 schedules. Typically a 6–10 digit numeric code aligned with the FERC Uniform System of Accounts (USoA).. Valid values are `^[0-9]{6,10}$`',
    `account_status` STRING COMMENT 'Current lifecycle status of the GL account master record (SAP SKB1 posting block indicators). Determines whether the account is available for financial postings. active permits normal posting; blocked prevents new postings; marked_for_deletion flags the account for archival pending period-end processing.. Valid values are `active|inactive|blocked|marked_for_deletion`',
    `account_type` STRING COMMENT 'The fundamental financial classification of the GL account (SAP SKA1-KTOKS mapped to balance sheet vs. P&L). Determines whether the account represents an asset, liability, equity, revenue, or expense. Drives financial statement presentation, normal balance (debit/credit), and period-end closing behavior. [ENUM-REF-CANDIDATE: asset|liability|equity|revenue|expense|other — promote to reference product]. Valid values are `asset|liability|equity|revenue|expense`',
    `afudc_eligible_flag` BOOLEAN COMMENT 'Indicates whether this GL account is eligible for AFUDC (Allowance for Funds Used During Construction) capitalization. AFUDC represents the cost of debt and equity funds used to finance construction of utility plant. Eligible accounts are typically construction work in progress (CWIP) accounts under FERC Account 107. AFUDC rates are set by FERC and state PUCs.',
    `balance_sheet_indicator` STRING COMMENT 'Indicates whether the GL account is a balance sheet account (carries forward period-end balance) or a profit and loss account (closed to retained earnings at fiscal year-end). Drives SAP period-end closing, financial statement version assignment, and FERC Form 1 balance sheet vs. income statement classification.. Valid values are `balance_sheet|profit_and_loss`',
    `capex_opex_indicator` STRING COMMENT 'Classifies the GL account as a capital expenditure (CAPEX) account for asset additions and infrastructure investment, or an operating expenditure (OPEX) account for period costs. Drives rate case cost-of-service classification, RAB inclusion/exclusion, depreciation treatment, and FERC Form 1 plant vs. expense reporting. Critical for IRP financial modeling and regulatory rate base determination.. Valid values are `capex|opex|not_applicable`',
    `commodity_type` STRING COMMENT 'Identifies whether the GL account pertains to electric operations, natural gas operations, both commodities, or is not commodity-specific. Supports jurisdictional separation of electric and gas operations for separate rate case filings, FERC Form 1 vs. FERC Form 2 reporting, and state PUC jurisdictional cost allocation.. Valid values are `electric|gas|both|not_applicable`',
    `company_code` STRING COMMENT 'The SAP company code (SKB1-BUKRS) representing the legal entity or reporting unit for which this GL account master record is maintained. Supports multi-entity financial reporting, consolidated FERC Form 1 filings, and separate regulatory jurisdictional reporting (electric vs. gas).. Valid values are `^[A-Z0-9]{4}$`',
    `cost_element_category` STRING COMMENT 'Indicates whether this GL account is also defined as a SAP CO cost element and its category (primary cost element for external costs, secondary for internal allocations). Primary cost elements link P&L accounts to CO for cost center accounting, internal orders, and project systems. Critical for O&M cost tracking and CAPEX/OPEX classification in rate cases.. Valid values are `primary|secondary|not_applicable`',
    `created_timestamp` TIMESTAMP COMMENT 'The timestamp when this GL account master record was first created in the system of record (SAP FI/CO). Provides audit trail for chart of accounts governance, SOX Section 404 internal control documentation, and regulatory examination support.',
    `currency_code` STRING COMMENT 'The ISO 4217 three-letter currency code for the account currency (SAP SKB1-WAERS). Specifies the currency in which account balances are maintained. For US utility operations, typically USD. Foreign currency accounts may be maintained for international power purchase agreements or cross-border energy trading.. Valid values are `^[A-Z]{3}$`',
    `depreciation_account_flag` BOOLEAN COMMENT 'Indicates whether this GL account is used to record depreciation expense or accumulated depreciation for utility plant assets. Depreciation accounts are subject to FERC-prescribed depreciation rates, state PUC depreciation studies, and FASB ASC 980 regulatory accounting treatment. Supports depreciation expense tracking for rate case cost-of-service studies.',
    `ebitda_component` STRING COMMENT 'Classifies the GL accounts contribution to EBITDA calculation by identifying which EBITDA component the account feeds (earnings/operating income, interest expense, income taxes, depreciation, or amortization). Supports management reporting, investor relations disclosures, and credit rating agency financial analysis for the utility.. Valid values are `earnings|interest|taxes|depreciation|amortization|not_applicable`',
    `effective_from_date` DATE COMMENT 'The date from which this GL account became effective and available for financial postings. Supports temporal validity tracking for chart of accounts changes, regulatory account restructuring, and historical financial analysis. Accounts created during FERC USoA updates or rate case restructuring carry the date of regulatory approval.',
    `effective_to_date` DATE COMMENT 'The date on which this GL account ceases to be effective for new financial postings. Null for currently active accounts. Populated when an account is retired, merged, or replaced as part of chart of accounts restructuring, FERC USoA updates, or regulatory account reclassification.',
    `ferc_account_description` STRING COMMENT 'The official FERC USoA account description corresponding to the mapped FERC account number. Provides regulatory context for the account classification and supports FERC Form 1 schedule preparation and rate case documentation.',
    `ferc_account_number` STRING COMMENT 'The FERC Uniform System of Accounts account number to which this GL account maps. Required for FERC Form 1 annual reporting, rate case cost-of-service studies, and regulatory compliance. Enables direct mapping between internal SAP account numbers and FERC-prescribed account classifications (e.g., Account 101 Steam Production Plant, Account 303 Transmission Plant).. Valid values are `^[0-9]{3}([.][0-9]{1,3})?$`',
    `field_status_group` STRING COMMENT 'The SAP field status group (SKB1-FSTAG) assigned to this GL account, controlling which fields are required, optional, or suppressed during document entry. Enforces data quality and completeness rules for financial postings, ensuring cost center, profit center, and project assignments are captured where required.. Valid values are `^G[0-9]{3}$`',
    `financial_statement_item` STRING COMMENT 'The SAP financial statement version item code (FSV item) that maps this GL account to a specific line in the published financial statements (balance sheet, income statement, statement of cash flows). Drives automated financial statement generation, SEC filing preparation, and FERC Form 1 schedule population.',
    `functional_area` STRING COMMENT 'The SAP functional area (SKB1-FUNC_AREA) assigned to this GL account for segment reporting and cost-of-service studies. Classifies accounts by business function (e.g., generation, transmission, distribution, customer service, administration) to support FERC Form 1 functional cost allocation and rate case cost-of-service analysis. [ENUM-REF-CANDIDATE: generation|transmission|distribution|customer_service|administration|gas_operations|corporate — promote to reference product]',
    `house_bank_account` STRING COMMENT 'The SAP house bank account identifier (SKB1-HBKID/HKTID) linked to this GL account for bank reconciliation purposes. Populated only for bank GL accounts to enable automatic bank statement processing, electronic bank reconciliation, and cash management reporting.',
    `interest_calculation_flag` BOOLEAN COMMENT 'Indicates whether automatic interest calculation is activated for this GL account (SAP SKB1-XINTB). Relevant for regulatory asset/liability accounts where carrying costs or AFUDC (Allowance for Funds Used During Construction) interest accruals are computed under FASB ASC 980 and FERC accounting rules.',
    `last_modified_timestamp` TIMESTAMP COMMENT 'The timestamp when this GL account master record was most recently modified in the system of record (SAP FI/CO). Supports change management tracking, audit trail maintenance, and data lineage for financial reporting integrity under SOX and FERC audit requirements.',
    `line_item_display_flag` BOOLEAN COMMENT 'Indicates whether individual line item display is activated for this GL account (SAP SKB1-XKRES). When enabled, all individual posting line items are stored and retrievable for detailed audit trail and drill-down analysis. Required for accounts subject to regulatory audit, SOX compliance, and FERC examination.',
    `normal_balance` STRING COMMENT 'The expected normal balance side (debit or credit) for this GL account based on its account type. Assets and expenses carry a normal debit balance; liabilities, equity, and revenues carry a normal credit balance. Used for variance analysis, trial balance validation, and automated anomaly detection in financial postings.. Valid values are `debit|credit`',
    `only_balances_in_local_currency_flag` BOOLEAN COMMENT 'Indicates whether this GL account maintains balances only in local (company code) currency (SAP SKB1-XSALH). When true, foreign currency line items are translated to local currency and only the local currency balance is tracked. Relevant for accounts where foreign currency detail is not required for regulatory reporting.',
    `open_item_management_flag` BOOLEAN COMMENT 'Indicates whether open item management is activated for this GL account (SAP SKB1-XOPVW). When enabled, individual line items remain open until cleared by an offsetting posting (e.g., payment clearing, goods receipt/invoice receipt clearing). Essential for clearing accounts, suspense accounts, and intercompany accounts.',
    `parent_account_number` STRING COMMENT 'The account number of the parent GL account in the chart of accounts hierarchy. Enables hierarchical rollup of account balances for financial statement preparation, management reporting subtotals, and FERC Form 1 schedule aggregations. Null for top-level summary accounts.',
    `planning_block_flag` BOOLEAN COMMENT 'Indicates whether cost planning postings to this GL account are blocked (SAP SKB1-XSPEP). When true, the account is excluded from CO planning activities such as cost center planning, internal order budgeting, and capital project planning. Supports budget governance and CAPEX/OPEX planning controls.',
    `plant_function_code` STRING COMMENT 'The FERC-defined utility plant function code classifying plant accounts by operational function (e.g., steam production, nuclear production, hydraulic production, transmission, distribution, general plant). Used for FERC Form 1 plant-in-service schedules, depreciation studies, and rate case plant allocation. [ENUM-REF-CANDIDATE: steam_production|nuclear_production|hydraulic_production|other_production|transmission|distribution|general_plant|gas_production|gas_storage|gas_distribution — promote to reference product]',
    `posting_block_flag` BOOLEAN COMMENT 'Indicates whether direct financial postings to this GL account are blocked at the company code level (SAP SKB1-XSPEB). When true, no journal entries or document postings can be made to this account, typically applied during period-end close, account restructuring, or regulatory review periods.',
    `profit_center` STRING COMMENT 'The default SAP profit center (SKB1-PRCTR) assigned to this GL account for segment profitability reporting. Enables automatic profit center derivation during financial postings, supporting electric vs. gas segment reporting, regulatory jurisdictional separation, and management reporting by business unit.',
    `reconciliation_account_flag` BOOLEAN COMMENT 'Indicates whether this GL account is a reconciliation account (SAP SKA1-XBILK) that is automatically updated by postings to subsidiary ledger accounts (accounts receivable, accounts payable, fixed assets). Reconciliation accounts cannot be posted to directly; they are updated via subledger transactions. Critical for AR/AP and asset accounting integrity.',
    `reconciliation_account_type` STRING COMMENT 'Specifies the subledger type for reconciliation accounts (SAP SKA1-MITKZ). Identifies whether the reconciliation account is linked to accounts receivable (customers), accounts payable (vendors), or fixed assets. Only populated when reconciliation_account_flag is true.. Valid values are `accounts_receivable|accounts_payable|fixed_assets|not_applicable`',
    `regulatory_asset_liability_type` STRING COMMENT 'Classifies the GL account as a regulatory asset, regulatory liability, or not applicable under FASB ASC 980 regulated operations accounting. Regulatory assets represent costs deferred for future recovery in rates (e.g., storm restoration costs, deferred fuel costs). Regulatory liabilities represent obligations to return amounts to customers through future rates (e.g., excess deferred income taxes, over-collected fuel costs). Critical for RAB valuation and rate case filings.. Valid values are `regulatory_asset|regulatory_liability|not_applicable`',
    `roe_component_flag` BOOLEAN COMMENT 'Indicates whether this GL account is included in the Return on Equity (ROE) calculation used in rate case proceedings. ROE-relevant accounts include equity components of the capital structure, net income accounts, and rate base accounts. Supports FERC and state PUC rate of return analysis and allowed ROE determination.',
    `sort_key` STRING COMMENT 'The SAP sort key (SKB1-ZUAWA) that determines the assignment field populated in line items posted to this account. Controls how line items are sorted and displayed in account balance reports. Common sort keys include document date (001), posting date (002), and external document number (012).. Valid values are `^[0-9]{3}$`',
    `tax_category` STRING COMMENT 'The SAP tax category (SKB1-MWSKZ) assigned to the GL account, controlling whether tax codes are required, optional, or not allowed on postings to this account. Relevant for sales tax, use tax, and excise tax compliance on utility revenues and purchases. [ENUM-REF-CANDIDATE: input_tax_required|output_tax_required|tax_optional|no_tax|not_applicable — promote to reference product]',
    CONSTRAINT pk_gl_account PRIMARY KEY(`gl_account_id`)
) COMMENT 'Master repository and control record for all general ledger accounts, encompassing the chart of accounts structure (account classes, groups, FERC USoA alignment), individual account properties (account type, balance sheet/P&L indicator, tax category, reconciliation account flag, posting controls), and period-end account balances by reporting entity. Serves as the foundational reference for all financial postings across SAP FI/CO, financial statement preparation, rate case cost-of-service studies, and FERC Form 1 reporting. Organized by account class (assets, liabilities, equity, revenues, expenses, O&M) aligned with FASB ASC 980 regulated operations classifications.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`finance`.`journal_entry` (
    `journal_entry_id` BIGINT COMMENT 'Unique surrogate identifier for each journal entry record in the general ledger. Serves as the primary key for the journal_entry data product in the Databricks Silver Layer.',
    `cost_center_id` BIGINT COMMENT 'Foreign key linking to finance.cost_center. Business justification: Journal Entry records belong to a single GL Account, Cost Center, Profit Center, WBS Element and Internal Order. Converting string codes to proper FK enforces referential integrity and eliminates redu',
    `gl_account_id` BIGINT COMMENT 'The chart of accounts GL account number to which this journal entry line item is posted. Aligned with the FERC Uniform System of Accounts (e.g., Account 101 for Electric Plant in Service, Account 403 for Depreciation Expense). Corresponds to BSEG-HKONT in SAP.',
    `internal_order_id` BIGINT COMMENT 'Foreign key linking to finance.internal_order. Business justification: Journal Entry records belong to a single GL Account, Cost Center, Profit Center, WBS Element and Internal Order. Converting string codes to proper FK enforces referential integrity and eliminates redu',
    `profit_center_id` BIGINT COMMENT 'Foreign key linking to finance.profit_center. Business justification: Journal Entry records belong to a single GL Account, Cost Center, Profit Center, WBS Element and Internal Order. Converting string codes to proper FK enforces referential integrity and eliminates redu',
    `wbs_element_id` BIGINT COMMENT 'Foreign key linking to finance.wbs_element. Business justification: Journal Entry records belong to a single GL Account, Cost Center, Profit Center, WBS Element and Internal Order. Converting string codes to proper FK enforces referential integrity and eliminates redu',
    `account_type` STRING COMMENT 'SAP account type indicator for the line item: A=Asset, D=Customer (Debtor), K=Vendor (Creditor), M=Material, S=General Ledger. Determines which sub-ledger the posting affects and is used for balance sheet classification in FERC Form 1 reporting. Corresponds to BSEG-KOART in SAP.. Valid values are `A|D|K|M|S`',
    `accrual_indicator` BOOLEAN COMMENT 'Flag indicating whether the journal entry is an accrual posting (estimated expense or revenue recognized before cash settlement). True for period-end accruals such as unbilled revenue, fuel cost accruals, and O&M expense accruals. Supports accrual reversal tracking.',
    `approval_timestamp` TIMESTAMP COMMENT 'The date and time when the journal entry was approved through the SAP workflow process. Provides the approval audit trail required for SOX Section 404 internal controls and external audit documentation.',
    `approved_by_user` STRING COMMENT 'SAP user ID of the approver who authorized the journal entry through the workflow approval process. Required for SOX Section 404 segregation of duties controls, particularly for manual journal entries above materiality thresholds.',
    `asset_number` STRING COMMENT 'SAP Asset Accounting (FI-AA) asset number for journal entries related to fixed asset acquisitions, retirements, depreciation, or transfers. Links GL postings to the RAB (Regulatory Asset Base) for rate case and FERC Form 1 plant-in-service reporting. Corresponds to BSEG-ANLN1 in SAP.',
    `assignment_field` STRING COMMENT 'Free-form assignment field used to carry cross-reference information such as billing document number, meter reading order, payment reference, or asset number. Enables drill-through from GL postings to originating operational transactions. Corresponds to BSEG-ZUONR in SAP.',
    `capex_opex_indicator` STRING COMMENT 'Classifies the journal entry as a capital expenditure (CAPEX) or operating expenditure (OPEX). CAPEX entries are capitalized to plant accounts and included in the RAB; OPEX entries flow through the income statement. Critical for rate case cost-of-service studies and IRP financial modeling.. Valid values are `CAPEX|OPEX`',
    `company_code` STRING COMMENT 'SAP company code representing the legal entity or organizational unit for which the journal entry is posted. Used to segregate financial postings by regulated entity for FERC Form 1 and state PUC rate case filings. Corresponds to BKPF-BUKRS in SAP.',
    `debit_credit_indicator` STRING COMMENT 'Indicates whether the journal entry line item is a debit (D) or credit (C) posting. Fundamental to double-entry bookkeeping and GL balance verification. Corresponds to BSEG-SHKZG in SAP.. Valid values are `D|C`',
    `depreciation_area` STRING COMMENT 'SAP FI-AA depreciation area code indicating the valuation basis for asset-related journal entries (e.g., 01=Book Depreciation, 15=Tax Depreciation, 20=FERC Regulatory Depreciation). Supports parallel valuation for GAAP, tax, and regulatory reporting. Corresponds to BSEG-BZDAT area in SAP.',
    `document_date` DATE COMMENT 'The date of the originating source document (invoice date, contract date, payroll date, etc.) that triggered the journal entry. May differ from posting_date for accruals and late postings. Corresponds to BKPF-BLDAT in SAP.',
    `document_number` STRING COMMENT 'The externally-known SAP FI document number assigned to the journal entry at posting time. Serves as the primary business identifier for the posting document, used in audit trails, FERC Form 1 reconciliation, and regulatory cost-of-service studies. Corresponds to BKPF-BELNR in SAP.',
    `document_type` STRING COMMENT 'SAP FI document type code that classifies the nature of the journal entry (e.g., SA=General Ledger, KR=Vendor Invoice, DR=Customer Invoice, AB=Accounting Document, ZP=Payment Posting, AA=Asset Posting). Drives number range assignment and account type determination. Corresponds to BKPF-BLART in SAP. [ENUM-REF-CANDIDATE: SA|KR|DR|AB|ZP|AA|RE|RV|WA|WE — promote to reference product]',
    `entered_by_user` STRING COMMENT 'SAP user ID of the person or system process that created the journal entry. Required for SOX Section 404 internal controls, segregation of duties monitoring, and audit trail documentation. Corresponds to BKPF-USNAM in SAP.',
    `entry_status` STRING COMMENT 'Current lifecycle status of the journal entry in the general ledger workflow. posted = fully committed to GL; parked = saved but not yet posted (BKPF-XBLNR workflow); held = incomplete entry; reversed = offset entry created; simulated = test posting not committed.. Valid values are `posted|parked|held|reversed|simulated`',
    `entry_timestamp` TIMESTAMP COMMENT 'The exact date and time when the journal entry record was created in the SAP FI system. Provides the audit trail creation timestamp for SOX compliance and internal controls. Corresponds to BKPF-CPUDT and BKPF-CPUTM in SAP.',
    `ferc_account_code` STRING COMMENT 'FERC Uniform System of Accounts account code mapped to the GL account for this journal entry line item. Required for FERC Form 1 annual report filing and regulatory cost-of-service studies. Examples: 101 (Electric Plant in Service), 403 (Depreciation Expense), 500 (Operation Expense). Distinct from the internal GL account.',
    `fiscal_period` STRING COMMENT 'The accounting period (1–16) within the fiscal year in which the journal entry is posted. Periods 1–12 represent calendar months; periods 13–16 are special closing periods used for year-end adjustments and audit corrections. Corresponds to BKPF-MONAT in SAP.',
    `fiscal_year` STRING COMMENT 'The fiscal year in which the journal entry is recorded. Used for annual financial close, FERC Form 1 annual reporting, and regulatory rate case cost-of-service period alignment. Corresponds to BKPF-GJAHR in SAP.',
    `functional_area` STRING COMMENT 'SAP CO functional area classifying the expense by business function (e.g., Generation, Transmission, Distribution, Customer Service, Administration) for FERC Form 1 functional cost reporting and regulatory cost-of-service studies. Corresponds to BSEG-FKBER in SAP.',
    `header_text` STRING COMMENT 'Free-text description at the journal entry header level explaining the business purpose of the posting (e.g., Q3 Fuel Cost Accrual, Storm Restoration Capitalization, FERC Account 403 Depreciation Run). Supports audit review and regulatory cost-of-service documentation. Corresponds to BKPF-BKTXT in SAP.',
    `intercompany_indicator` BOOLEAN COMMENT 'Flag indicating whether the journal entry involves a transaction between affiliated entities within the utility holding company. True triggers intercompany elimination processing in consolidated reporting and FERC affiliate transaction disclosure requirements.',
    `last_changed_timestamp` TIMESTAMP COMMENT 'The date and time when the journal entry record was last modified in the source SAP FI system. Used for change tracking, audit compliance, and incremental data pipeline processing in the Databricks Silver Layer.',
    `line_item_number` STRING COMMENT 'Sequential line item number within the journal entry document, starting at 1. Uniquely identifies each debit or credit posting line within a multi-line journal entry. Corresponds to BSEG-BUZEI in SAP.',
    `line_item_text` STRING COMMENT 'Free-text description at the journal entry line item level providing additional detail about the specific debit or credit posting (e.g., Transmission line maintenance labor, Nuclear fuel amortization). Supports granular audit trail and FERC cost-of-service line item documentation. Corresponds to BSEG-SGTXT in SAP.',
    `local_currency_amount` DECIMAL(18,2) COMMENT 'The journal entry line item amount converted to the company code local currency (typically USD). Used for consolidated financial reporting, EBITDA calculation, and FERC Form 1 reporting where all amounts must be in USD. Corresponds to BSEG-DMBTR in SAP.',
    `local_currency_code` STRING COMMENT 'ISO 4217 three-letter currency code of the company code local currency (typically USD for US utilities). Used when transaction currency differs from local currency to support multi-currency financial reporting. Corresponds to BKPF-HWAER in SAP.. Valid values are `^[A-Z]{3}$`',
    `posting_date` DATE COMMENT 'The date on which the journal entry is posted to the general ledger. Determines the fiscal period assignment and is the principal real-world event date for the financial transaction. Used for period-end close, accrual cutoff, and regulatory reporting. Corresponds to BKPF-BUDAT in SAP.',
    `posting_key` STRING COMMENT 'SAP two-digit posting key that determines the account type, debit/credit indicator, and field selection for the line item (e.g., 40=GL Debit, 50=GL Credit, 01=Customer Invoice, 31=Vendor Invoice). Drives the accounting logic for each line. Corresponds to BSEG-BSCHL in SAP. [ENUM-REF-CANDIDATE: 01|31|40|50|70|75|80|90 — promote to reference product]',
    `recurring_entry_indicator` BOOLEAN COMMENT 'Flag indicating whether the journal entry was generated from a SAP recurring entry template (FBD1). True for fixed monthly postings such as lease payments, depreciation runs, and regulatory amortization entries. Supports automated posting audit trails.',
    `reference_document_number` STRING COMMENT 'External reference number from the originating source system (e.g., Oracle CC&B billing document number, Maximo work order number, Allegro trade confirmation number, SAP MM purchase order number). Provides the cross-system audit trail for the journal entry. Corresponds to BKPF-XBLNR in SAP.',
    `regulatory_asset_indicator` BOOLEAN COMMENT 'Flag indicating whether the journal entry relates to a FASB ASC 980 regulatory asset or regulatory liability. True for deferred costs or revenues that are recoverable through future rate cases (e.g., storm restoration costs, deferred fuel costs, pension regulatory assets). Critical for RAB valuation.',
    `reversal_indicator` BOOLEAN COMMENT 'Flag indicating whether this journal entry is a reversal of a previously posted document. True when the entry was created via the SAP reversal transaction (FB08/FBR2). Used to identify offsetting entries in audit trails and period-end reconciliation.',
    `reversal_reason_code` STRING COMMENT 'SAP-defined reason code explaining why the journal entry was reversed (e.g., 01=Reversal in current period, 02=Reversal in prior period, 03=Accrual reversal). Required for audit documentation and SOX internal controls. Corresponds to BKPF-STGRD in SAP.',
    `reversed_document_number` STRING COMMENT 'The original SAP FI document number that this entry reverses, if reversal_indicator is True. Enables traceability between reversal entries and their originating documents for audit and regulatory cost-of-service studies. Corresponds to BKPF-STBLG in SAP.',
    `source_transaction_type` STRING COMMENT 'Classification of the originating business process that generated the journal entry. Enables segregation of manual entries from system-generated postings for SOX controls, and supports FERC Form 1 functional cost analysis by transaction origin. [ENUM-REF-CANDIDATE: manual|billing|procurement|payroll|asset|accrual|reversal|period_close|intercompany|energy_trading — 10 candidates stripped; promote to reference product]',
    `special_gl_indicator` STRING COMMENT 'SAP special GL indicator for down payments, guarantees, bills of exchange, or regulatory asset/liability postings (e.g., A=Down Payment, E=Security Deposit, F=Regulatory Asset). Critical for FASB ASC 980 regulatory asset and liability accounting. Corresponds to BSEG-UMSKZ in SAP.',
    `tax_amount` DECIMAL(18,2) COMMENT 'The tax amount in local currency associated with the journal entry line item. Supports tax liability reporting, regulatory tax normalization adjustments in rate cases, and FERC Form 1 tax expense schedules. Corresponds to BSEG-WMWST in SAP.',
    `tax_code` STRING COMMENT 'SAP tax code identifying the applicable tax condition (e.g., sales tax, use tax, excise tax) for the journal entry line item. Used for tax reporting, regulatory surcharge tracking, and state PUC tax normalization in rate cases. Corresponds to BSEG-MWSKZ in SAP.',
    `trading_partner` STRING COMMENT 'SAP trading partner company code for intercompany journal entries between affiliated entities within the utility holding company structure. Used for intercompany elimination in consolidated financial statements and FERC affiliate transaction reporting. Corresponds to BSEG-VBUND in SAP.',
    `transaction_amount` DECIMAL(18,2) COMMENT 'The gross monetary amount of the journal entry line item in the transaction currency. Represents the raw financial value before any local currency conversion. Positive for debits, negative for credits per SAP sign convention. Corresponds to BSEG-WRBTR in SAP.',
    `transaction_currency_code` STRING COMMENT 'ISO 4217 three-letter currency code of the original transaction currency in which the journal entry amount was recorded (e.g., USD for US Dollar). Used for multi-currency postings involving PPAs, energy trading, or international vendor transactions. Corresponds to BKPF-WAERS in SAP.. Valid values are `^[A-Z]{3}$`',
    CONSTRAINT pk_journal_entry PRIMARY KEY(`journal_entry_id`)
) COMMENT 'Complete general ledger journal entry record including header and line-item detail for all financial postings — manual journal entries, system-generated postings from billing/procurement/payroll, accruals, reversals, and period-end closing entries. Header captures posting date, fiscal period, document type, company code, and originating transaction reference. Each line item specifies the GL account, cost center, profit center, WBS element, debit/credit amount in transaction and local currency, tax code, and assignment field. Provides the atomic-level audit trail for all financial postings required for FERC Form 1 and regulatory cost-of-service studies.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`finance`.`journal_entry_line` (
    `journal_entry_line_id` BIGINT COMMENT 'Unique surrogate identifier for each individual debit or credit line item within a SAP FI journal entry. Serves as the primary key for this atomic-level financial posting record in the Databricks Silver Layer.',
    `cost_center_id` BIGINT COMMENT 'Surrogate identifier referencing the SAP CO cost center responsible for this financial posting. Used for departmental cost allocation, Operations and Maintenance (O&M) tracking, and rate case cost-of-service studies.',
    `gl_account_id` BIGINT COMMENT 'Surrogate identifier referencing the General Ledger account (chart of accounts entry) to which this line item is posted. Drives FERC Form 1 account mapping and regulatory cost-of-service classification.',
    `internal_order_id` BIGINT COMMENT 'Surrogate identifier referencing the SAP CO internal order used for collecting costs on specific jobs, maintenance activities, or short-term projects not managed via WBS. Supports Operations and Maintenance (O&M) cost tracking and Maximo work order integration.',
    `journal_entry_id` BIGINT COMMENT 'Surrogate identifier referencing the parent journal entry header (TRANSACTION_HEADER) to which this line item belongs. Establishes the header-detail relationship for all debit/credit line items within a single SAP FI posting document.',
    `trade_id` BIGINT COMMENT 'Foreign key linking to trading.trade. Business justification: Required for Trade Accounting Reconciliation Report linking each journal entry line to its originating trade for audit and financial reporting.',
    `wbs_element_id` BIGINT COMMENT 'Surrogate identifier referencing the SAP PS Work Breakdown Structure element for capital project cost tracking. Supports Capital Expenditure (CAPEX) project accounting, asset capitalization, and Regulatory Asset Base (RAB) valuation.',
    `account_type` STRING COMMENT 'SAP FI account type (KOART) indicating the subledger category: A=Asset, D=Customer (Debtor), K=Vendor (Creditor), M=Material, S=General Ledger. Drives subledger reconciliation and FERC account classification.. Valid values are `A|D|K|M|S`',
    `asset_number` STRING COMMENT 'SAP Asset Accounting asset number (ANLN1) for line items related to fixed asset transactions such as acquisitions, retirements, depreciation, and transfers. Supports Regulatory Asset Base (RAB) valuation and FERC Form 1 utility plant account reconciliation.',
    `asset_subnumber` STRING COMMENT 'SAP Asset Accounting asset sub-number (ANLN2) identifying a specific component or sub-asset within the main asset record. Used for component-level depreciation tracking and capital project asset capitalization under FASB ASC 360.',
    `assignment` STRING COMMENT 'SAP FI assignment field (ZUONR) used for sorting and grouping line items in account statements and open item management. Typically populated with a reference number such as a meter number, work order number, or billing document number for cross-system traceability.',
    `baseline_date` DATE COMMENT 'The baseline date (ZFBDT) used for payment terms calculation on vendor and customer line items. Determines due dates for accounts payable and accounts receivable aging analysis and cash flow forecasting.',
    `business_area` STRING COMMENT 'SAP FI business area (GSBER) representing an organizational unit for which balance sheets and P&L statements can be drawn up independently. Used for segment reporting across Electric, Gas, and other utility business lines per FASB ASC 280.',
    `capex_opex_indicator` STRING COMMENT 'Classifies this line item as a Capital Expenditure (CAPEX) or Operating Expenditure (OPEX) posting. Critical for rate case cost-of-service studies, Regulatory Asset Base (RAB) valuation, FERC Form 1 plant account reporting, and EBITDA calculation.. Valid values are `CAPEX|OPEX`',
    `changed_timestamp` TIMESTAMP COMMENT 'The timestamp of the most recent modification to this journal entry line item in SAP FI. Supports change data capture (CDC) for the Databricks Silver Layer ingestion pipeline and SOX Section 404 change audit trail requirements.',
    `clearing_date` DATE COMMENT 'The date (AUGDT) on which this open line item was cleared (matched against a payment or offsetting entry) in SAP FI. Null for uncleared items. Used for accounts payable/receivable reconciliation and cash application tracking.',
    `clearing_document_number` STRING COMMENT 'The SAP FI document number (AUGBL) of the clearing transaction that offset this open item. Links payment documents to original invoices or debit memos for accounts payable/receivable reconciliation and audit trail.',
    `created_timestamp` TIMESTAMP COMMENT 'The timestamp when this journal entry line item record was first created in the SAP FI system. Provides the audit trail creation timestamp required for SOX Section 404 internal controls and FERC audit documentation.',
    `debit_credit_indicator` STRING COMMENT 'SAP FI debit/credit indicator (SHKZG) specifying whether this line item is a debit (D) or credit (C) posting. Fundamental to double-entry bookkeeping and ensures balanced journal entries for FERC Form 1 and FASB compliance.. Valid values are `D|C`',
    `document_date` DATE COMMENT 'The original document date (BLDAT) of the source business transaction, such as the invoice date or contract date. May differ from the posting date and is used for aging analysis, payment terms, and audit trail documentation.',
    `dunning_block` STRING COMMENT 'SAP FI dunning block indicator (MANSP) that prevents automated dunning (payment reminder) notices for this line item. Used for disputed invoices, regulatory-ordered payment holds, or items under PUC complaint review.',
    `ferc_account_code` STRING COMMENT 'The FERC Uniform System of Accounts code mapped to this GL line item, used for FERC Form 1 annual report filing. Classifies utility plant, operating revenues, operating expenses, and other accounts per FERC regulatory requirements.',
    `fiscal_period` STRING COMMENT 'The SAP fiscal period (MONAT) within the fiscal year, typically 1–12 for monthly periods plus special periods 13–16 for year-end adjustments. Drives monthly financial close and period-over-period variance reporting.',
    `fiscal_year` STRING COMMENT 'The SAP fiscal year (GJAHR) in which this journal entry line is posted. Used for annual financial close, FERC Form 1 annual reporting, and year-over-year budget variance analysis.',
    `functional_area` STRING COMMENT 'SAP CO functional area (FKBER) classifying the business function of this posting, such as Generation, Transmission, Distribution, Customer Service, or Administration. Supports cost-of-service studies and FERC Form 1 functional classification of expenses.',
    `intercompany_indicator` BOOLEAN COMMENT 'Flag indicating whether this line item represents an intercompany transaction between affiliated entities within the utility holding company structure (True). Required for intercompany elimination in consolidated financial statements and FERC Form 1 affiliated transaction disclosure.',
    `line_item_number` STRING COMMENT 'Sequential line item number (BUZEI) within the parent journal entry document, ordering debit and credit postings. Ensures the complete audit trail of all line items within a single SAP FI posting document.',
    `line_item_status` STRING COMMENT 'Current processing status of this journal entry line item in the financial workflow. open indicates an uncleared item; cleared indicates matched/settled; parked indicates a provisional posting pending approval; reversed indicates a correcting reversal; in_dispute indicates a contested amount under review.. Valid values are `open|cleared|parked|reversed|in_dispute`',
    `line_item_text` STRING COMMENT 'Free-text description (SGTXT) entered at the line item level in SAP FI, providing narrative context for the posting such as Monthly depreciation - Transmission Lines or PPA settlement - Wind Farm Q1. Supports audit trail and FERC Form 1 explanatory notes.',
    `local_amount` DECIMAL(18,2) COMMENT 'The monetary amount of this line item translated into the company code local currency (DMBTR), typically USD for US utility operations. Used for consolidated financial reporting, FERC Form 1, and FASB ASC 980 regulatory accounting.',
    `local_currency` STRING COMMENT 'ISO 4217 three-letter currency code for the company code local currency (HWAER), typically USD. Distinguishes local currency amounts from transaction currency amounts in multi-currency SAP environments.. Valid values are `^[A-Z]{3}$`',
    `payment_block` STRING COMMENT 'SAP FI payment block indicator (ZLSPR) that prevents automated payment processing for this line item. Used for invoice verification holds, disputed vendor payments, or regulatory compliance holds pending PUC or FERC review.',
    `payment_terms` STRING COMMENT 'SAP FI payment terms key (ZTERM) applicable to this line item for vendor or customer accounts, defining due dates and early payment discount conditions. Used for cash flow forecasting and accounts payable/receivable management.',
    `plant` STRING COMMENT 'SAP logistics plant code (WERKS) associated with this line item, representing a generation facility, service center, or operational location. Links financial postings to physical utility infrastructure for asset accounting and FERC plant account reporting.',
    `posting_date` DATE COMMENT 'The SAP FI posting date (BUDAT) on which this line item is recorded in the General Ledger. Determines the fiscal period assignment and is the primary date for period-end close, FERC Form 1 reporting, and FASB ASC 980 regulatory accounting.',
    `posting_key` STRING COMMENT 'SAP FI posting key (BSCHL) that determines the debit/credit indicator, account type, and field selection for this line item. Standard values include 40 (GL debit), 50 (GL credit), 01 (customer invoice), 31 (vendor invoice), etc. [ENUM-REF-CANDIDATE: 01|11|21|31|40|50|70|75|80|90 — promote to reference product]',
    `profit_center_code` BIGINT COMMENT 'Surrogate identifier referencing the SAP CO profit center associated with this line item. Enables segment-level profitability reporting across business units such as Electric Distribution, Gas Distribution, and Generation.',
    `quantity` DECIMAL(18,2) COMMENT 'The quantity (MENGE) associated with this line item, representing physical units such as kWh, MWh, MCF, or Therms for energy commodity postings. Supports energy volume reconciliation between financial postings and operational metering data.',
    `reference_document_number` STRING COMMENT 'External reference document number (XBLNR) from the source transaction, such as a vendor invoice number, purchase order number, or billing document number. Enables cross-system traceability between SAP FI and source systems like Oracle CC&B, Maximo, or Allegro ETRM.',
    `regulatory_asset_indicator` BOOLEAN COMMENT 'Flag indicating whether this line item relates to a FASB ASC 980 regulatory asset or regulatory liability (True) as approved by a state PUC or FERC rate order. Regulatory assets represent costs deferred for future recovery in customer rates; regulatory liabilities represent obligations to refund customers.',
    `reversal_indicator` BOOLEAN COMMENT 'Flag indicating whether this line item is part of a reversal posting (True) or an original posting (False). Reversal postings are used to correct erroneous entries and are required to be disclosed in FERC Form 1 audit trails and SOX Section 404 internal controls documentation.',
    `second_local_amount` DECIMAL(18,2) COMMENT 'Amount in the SAP company code second local currency (parallel currency), used for group reporting or regulatory reporting in a secondary currency. Supports consolidated EBITDA and Return on Equity (ROE) calculations at the enterprise level.',
    `special_gl_indicator` STRING COMMENT 'SAP FI special GL indicator (UMSKZ) for down payments, guarantees, bills of exchange, or other special transactions that post to alternative reconciliation accounts. Used for regulatory asset/liability tracking under FASB ASC 980.. Valid values are `^[A-Z0-9]?$`',
    `tax_amount` DECIMAL(18,2) COMMENT 'The tax amount (WMWST) associated with this journal entry line item in transaction currency. Captures sales/use tax, excise tax, or other tax components posted to the GL for regulatory and tax compliance reporting.',
    `tax_code` STRING COMMENT 'SAP FI tax code (MWSKZ) assigned to this line item, determining the applicable tax rate and tax account determination. Used for sales/use tax compliance, state PUC tax filings, and IRS reporting.. Valid values are `^[A-Z0-9]{1,2}$`',
    `trading_partner` STRING COMMENT 'SAP FI trading partner company code (VBUND) identifying the affiliated entity in intercompany transactions. Required for intercompany elimination in consolidated financial statements and FERC Form 1 intercompany transaction disclosure.',
    `transaction_amount` DECIMAL(18,2) COMMENT 'The monetary amount of this line item in the transaction currency (WRBTR) as posted in SAP FI. Represents the raw debit or credit value before currency translation. Positive value; sign determined by debit_credit_indicator.',
    `transaction_currency` STRING COMMENT 'ISO 4217 three-letter currency code for the transaction currency (WAERS) of this line item, e.g., USD. Required for multi-currency postings such as Power Purchase Agreement (PPA) settlements or international energy trading transactions.. Valid values are `^[A-Z]{3}$`',
    `unit_of_measure` STRING COMMENT 'The unit of measure (MEINS) for the quantity field, using SAP internal unit codes. Energy-specific values include KWH (Kilowatt-Hour), MWH (Megawatt-Hour), MCF (Thousand Cubic Feet), and THERM for gas and electric commodity postings. [ENUM-REF-CANDIDATE: KWH|MWH|MCF|THERM|MW|KW|M3|GAL|BBL|EA|HR — 11 candidates stripped; promote to reference product]',
    `value_date` DATE COMMENT 'The value date (VALUT) for this line item, representing the date on which the financial transaction takes economic effect for cash management and liquidity planning purposes. Relevant for energy trading settlements and Power Purchase Agreement (PPA) payments.',
    CONSTRAINT pk_journal_entry_line PRIMARY KEY(`journal_entry_line_id`)
) COMMENT 'Individual debit and credit line items within a SAP FI journal entry, each specifying the GL account, cost center, profit center, WBS element, amount in transaction and local currency, tax code, and assignment field. Provides the atomic-level audit trail for all financial postings required for FERC Form 1 and regulatory cost-of-service studies.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`finance`.`finance_capex_project` (
    `finance_capex_project_id` BIGINT COMMENT 'Unique surrogate identifier for the capital expenditure project record in the finance lakehouse. Primary key for this entity.',
    `asset_capex_project_id` BIGINT COMMENT 'Foreign key reference to the parent project definition entity, linking this CAPEX project record to its master project record in the project hierarchy.',
    `cost_center_id` BIGINT COMMENT 'Foreign key reference to the responsible cost center that owns and is accountable for this capital projects expenditures, used for cost allocation and reporting.',
    `parcel_id` BIGINT COMMENT 'Foreign key linking to property.parcel. Business justification: Capital projects (e.g., substation build) must be linked to the land parcel they occupy for regulatory reporting and project budgeting.',
    `tech_project_id` BIGINT COMMENT 'Foreign key linking to technology.tech_project. Business justification: Capital project financial tracking must be linked to the corresponding technology project for integrated reporting and project governance.',
    `wbs_element_id` BIGINT COMMENT 'Foreign key reference to the specific Work Breakdown Structure element within the project hierarchy that this cost record is associated with, enabling granular cost tracking by scope of work.',
    `actual_end_date` DATE COMMENT 'Actual date on which all project work was completed. Null until project is physically complete. Used for schedule variance analysis and triggers the capitalization/in-service process.',
    `actual_spend_amount` DECIMAL(18,2) COMMENT 'Cumulative actual costs incurred and posted to the project to date, in USD. Sourced from SAP PS actual cost postings (COSP). Used for budget variance analysis and FERC Form 1 CWIP reporting.',
    `actual_start_date` DATE COMMENT 'Actual date on which construction or project execution activities commenced. Used for schedule variance analysis and AFUDC accrual start. Null until project activities begin.',
    `afudc_accrual_amount` DECIMAL(18,2) COMMENT 'Cumulative Allowance for Funds Used During Construction (AFUDC) accrued on this project to date, in USD. AFUDC capitalizes the cost of debt and equity financing during the construction period, increasing the projects capitalized cost and rate base. Governed by FERC regulations and FASB ASC 980-835.',
    `afudc_rate` DECIMAL(18,2) COMMENT 'The AFUDC capitalization rate applied to this project, expressed as a decimal (e.g., 0.075000 = 7.5%). Set annually by the utilitys regulatory accounting team per FERC guidelines and approved in rate cases. Used to calculate AFUDC accruals on CWIP balances.',
    `approved_budget_amount` DECIMAL(18,2) COMMENT 'Total authorized CAPEX budget for the project as approved by the capital budgeting committee, in USD. Represents the spending ceiling for the project. Corresponds to SAP IM Appropriation Request approved budget value.',
    `asset_class` STRING COMMENT 'FERC/regulatory asset class to which the completed project will be capitalized upon in-service (e.g., Electric Plant in Service, Gas Plant in Service, Intangible Plant, Construction Work in Progress). Drives depreciation rates and rate base inclusion. [ENUM-REF-CANDIDATE: electric_plant_in_service|gas_plant_in_service|intangible_plant|cwip|general_plant|other — promote to reference product]',
    `authorization_date` DATE COMMENT 'Date on which the capital project received formal management or board authorization to proceed. Marks the transition from proposed to authorized status and enables CAPEX commitment in SAP IM.',
    `authorization_number` STRING COMMENT 'Formal capital authorization or Appropriation Request (AR) number issued by the capital budgeting committee or board upon project approval. Required for CAPEX commitment and spend initiation in SAP IM.',
    `budget_fiscal_year` STRING COMMENT 'The primary fiscal year in which this capital projects budget was authorized and is being tracked. Multi-year projects may span multiple fiscal years; this field identifies the originating or primary budget year for capital planning and annual reporting.',
    `capitalization_date` DATE COMMENT 'Date on which project costs were settled from the SAP PS project to fixed assets in SAP Asset Accounting (AA), creating the asset under construction (AuC) or final asset records. May differ from in_service_date due to accounting close cycles.',
    `capitalized_cost_amount` DECIMAL(18,2) COMMENT 'Total cost amount settled and capitalized to fixed assets upon project completion, in USD. Includes all direct project costs plus AFUDC accruals. Represents the initial carrying value of the resulting fixed assets on the balance sheet.',
    `committed_amount` DECIMAL(18,2) COMMENT 'Total value of open purchase orders and contracts committed against this project but not yet invoiced or posted as actual costs, in USD. Sourced from SAP MM commitment management. Committed + Actual = Total Exposure.',
    `cpcn_number` STRING COMMENT 'Regulatory certificate number issued by the State Public Utility Commission (PUC) authorizing construction of major utility infrastructure. Required for large capital projects above regulatory thresholds. Null if project does not require CPCN.',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when this capital project record was first created in the system, in ISO 8601 format (yyyy-MM-ddTHH:mm:ss.SSSXXX). Sourced from SAP PS project creation date/time. Supports audit trail and data lineage requirements.',
    `currency_code` STRING COMMENT 'ISO 4217 three-letter currency code for all monetary amounts on this project record (e.g., USD). Power and Utilities operates primarily in USD; this field supports multi-currency reporting for international projects or PPAs.. Valid values are `^[A-Z]{3}$`',
    `estimated_useful_life_years` STRING COMMENT 'Estimated useful life of the resulting capital assets in years, used to determine depreciation rates and rate base amortization schedules. Set per FERC depreciation study and state PUC-approved depreciation rates.',
    `ferc_account_code` STRING COMMENT 'FERC Uniform System of Accounts account code to which the completed project assets will be classified upon capitalization (e.g., 353 for Station Equipment, 376 for Distribution Mains). Required for FERC Form 1 reporting and rate base determination.',
    `geographic_region` STRING COMMENT 'Geographic service territory or region where the capital project is physically located or will deliver service (e.g., Northeast District, Western Transmission Zone). Used for regional capital planning and regulatory jurisdiction assignment.',
    `in_service_date` DATE COMMENT 'Date on which the completed capital project assets were formally placed in service and transferred from Construction Work in Progress (CWIP) to Plant in Service on the balance sheet. Triggers depreciation commencement and rate base inclusion. Critical for FERC Form 1 and rate case filings.',
    `irp_program_code` STRING COMMENT 'Code linking this capital project to the Integrated Resource Plan (IRP) capital investment program or portfolio under which it was authorized. Enables IRP-level capital tracking and regulatory reporting.',
    `is_afudc_eligible` BOOLEAN COMMENT 'Indicates whether this project qualifies for AFUDC accrual (True) or not (False). Projects must meet FERC and FASB ASC 980-835 criteria for AFUDC eligibility, typically requiring a construction period exceeding one year and costs above a materiality threshold.',
    `is_cwip_in_rate_base` BOOLEAN COMMENT 'Indicates whether Construction Work in Progress (CWIP) balances for this project are currently included in the utilitys rate base for rate recovery prior to in-service (True) or not (False). CWIP rate base treatment is jurisdiction-specific and requires PUC approval.',
    `is_rate_base_eligible` BOOLEAN COMMENT 'Indicates whether the completed project assets are eligible for inclusion in the Regulatory Asset Base (RAB) for rate recovery purposes (True) or not (False). Non-eligible projects include those disallowed by regulators or used for non-regulated activities.',
    `last_updated_timestamp` TIMESTAMP COMMENT 'Timestamp when this capital project record was most recently modified in the source system, in ISO 8601 format (yyyy-MM-ddTHH:mm:ss.SSSXXX). Used for incremental data loading, change detection, and audit trail maintenance.',
    `planned_end_date` DATE COMMENT 'Planned date on which all project work is scheduled to be completed and the asset placed in service. Drives AFUDC accrual period and capitalization timeline. Corresponds to SAP PS Basic Finish Date.',
    `planned_start_date` DATE COMMENT 'Planned date on which construction or project execution activities are scheduled to begin. Used for capital planning, resource scheduling, and AFUDC accrual start determination. Corresponds to SAP PS Basic Start Date.',
    `ppa_reference_number` STRING COMMENT 'Reference number of the associated Power Purchase Agreement (PPA) if this capital project is related to a renewable energy or generation procurement contract. Null for projects not associated with a PPA. Links capital investment to contracted energy supply.',
    `priority_level` STRING COMMENT 'Business priority classification of the capital project used in IRP capital planning and portfolio management. Critical projects are typically regulatory-mandated or safety-driven; high are strategic; medium are operational improvements; low are discretionary.. Valid values are `critical|high|medium|low`',
    `project_description` STRING COMMENT 'Detailed narrative description of the capital project scope, objectives, and justification. Supports CPCN filings, IRP documentation, and rate case cost-of-service studies.',
    `project_manager` STRING COMMENT 'Name of the employee designated as the responsible project manager for this capital project. Accountable for schedule, budget, and scope delivery. Sourced from SAP PS Responsible Person field.',
    `project_name` STRING COMMENT 'Descriptive human-readable name of the capital project (e.g., Substation 47 Transformer Upgrade, AMI Phase 2 Deployment, Pipeline Segment 8 Replacement). Used in management reporting and regulatory filings.',
    `project_number` STRING COMMENT 'Externally-known alphanumeric project identifier assigned by SAP PS/IM at project creation. Used in CPCN filings, IRP capital planning documents, and cross-system references. Corresponds to the SAP Project Definition number (PROJ-PSPNR).. Valid values are `^[A-Z0-9-]{4,20}$`',
    `project_sponsor` STRING COMMENT 'Name of the executive or senior manager sponsoring and accountable for the capital project at the business unit level. Responsible for project authorization and escalation decisions.',
    `project_status` STRING COMMENT 'Current lifecycle status of the capital project: proposed (under evaluation), authorized (board/management approved), active (construction/implementation in progress), on_hold (temporarily suspended), completed (work finished, pending capitalization), cancelled (project terminated), closed (fully capitalized and settled to fixed assets). [ENUM-REF-CANDIDATE: proposed|authorized|active|on_hold|completed|cancelled|closed — 7 candidates stripped; promote to reference product]',
    `project_type` STRING COMMENT 'Classification of the capital project by investment type: new_construction (greenfield infrastructure), replacement (like-for-like asset replacement), upgrade (capacity or capability enhancement), maintenance (major maintenance capitalized), compliance (regulatory-mandated investment), technology (IT/OT systems). [ENUM-REF-CANDIDATE: new_construction|replacement|upgrade|maintenance|compliance|technology — promote to reference product]. Valid values are `new_construction|replacement|upgrade|maintenance|compliance|technology`',
    `rec_program_code` STRING COMMENT 'Code identifying the Renewable Energy Certificate (REC) program associated with this capital project, applicable for renewable generation projects (solar, wind, hydro). Used for REC tracking, compliance reporting, and state renewable portfolio standard (RPS) obligations.',
    `regulatory_jurisdiction` STRING COMMENT 'Regulatory jurisdiction governing this capital project for rate recovery and reporting purposes: ferc (FERC-jurisdictional transmission), state_puc (state-regulated distribution/generation), both (dual jurisdiction), exempt (non-regulated or exempt project).. Valid values are `ferc|state_puc|both|exempt`',
    `revised_budget_amount` DECIMAL(18,2) COMMENT 'Most recent revised total CAPEX budget after approved budget amendments or scope changes, in USD. Null if no revisions have been made. Used to track budget overruns and variance analysis.',
    `utility_division` STRING COMMENT 'Utility business division responsible for this capital project, used for regulatory cost allocation between electric and gas operations and T&D functional separation in rate cases and FERC Form 1 reporting.. Valid values are `electric_generation|electric_transmission|electric_distribution|gas_distribution|gas_transmission|corporate`',
    `wbs_level` STRING COMMENT 'Numeric level of this record within the WBS hierarchy (e.g., 1 = project root, 2 = phase, 3 = work package, 4 = activity). Enables hierarchical cost roll-up and reporting from activity level to total project level.',
    CONSTRAINT pk_finance_capex_project PRIMARY KEY(`finance_capex_project_id`)
) COMMENT 'SAP PS/IM capital expenditure project master representing individual capital investment projects (e.g., substation upgrades, AMI deployment, pipeline replacement) including their hierarchical Work Breakdown Structure (WBS) elements for granular cost tracking. Tracks project authorization, CAPEX budget, actual spend by WBS element, AFUDC (Allowance for Funds Used During Construction) accruals, and in-service date for asset capitalization. WBS elements map to specific scopes of work and accumulate costs that settle to fixed assets upon project completion. Supports CPCN filings and IRP capital planning.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`finance`.`wbs_element` (
    `wbs_element_id` BIGINT COMMENT 'Unique surrogate identifier for the WBS element record in the Databricks Silver Layer. Primary key generated by the lakehouse ingestion pipeline from SAP PS.',
    `cost_center_id` BIGINT COMMENT 'Reference to the SAP CO cost center responsible for this WBS element. Drives cost allocation, budget ownership, and departmental CAPEX reporting.',
    `fixed_asset_id` BIGINT COMMENT 'Reference to the SAP FI-AA Asset Under Construction (AuC) record to which costs from this WBS element are periodically transferred during the construction phase. The AuC is the balance sheet representation of in-progress capital work.',
    `gl_account_id` BIGINT COMMENT 'Reference to the primary General Ledger account to which costs accumulated on this WBS element are posted. Aligns with the FERC Uniform System of Accounts for electric and gas plant.',
    `parent_wbs_element_id` BIGINT COMMENT 'Self-referencing identifier pointing to the immediate parent WBS element in the hierarchical project structure. Null for top-level (Level 1) WBS elements. Enables traversal of the full WBS hierarchy for roll-up cost reporting.',
    `employee_id` BIGINT COMMENT 'Reference to the employee (project manager or WBS element owner) accountable for cost control and delivery of this WBS element scope. Sourced from SAP HR.',
    `profit_center_id` BIGINT COMMENT 'FK to finance.profit_center',
    `account_assignment_element_flag` BOOLEAN COMMENT 'Indicates whether this WBS element can be used as an account assignment object on purchase orders, time confirmations, and journal entries in SAP. True = direct cost postings allowed; False = summary/header level only.',
    `actual_cost_amount` DECIMAL(18,2) COMMENT 'Total actual costs posted to this WBS element to date in US dollars, including labor, materials, equipment, and contractor charges. Sourced from SAP CO actual cost line items. Used for CAPEX spend tracking and budget variance reporting.',
    `actual_finish_date` DATE COMMENT 'The date on which work on this WBS element was actually completed. Triggers technical completion status and initiates the asset settlement process to fixed assets.',
    `actual_start_date` DATE COMMENT 'The date on which work on this WBS element actually commenced. Compared against planned start date for schedule variance analysis and project performance reporting.',
    `asset_class` STRING COMMENT 'SAP Asset Accounting asset class to which costs on this WBS element will be settled upon project completion (e.g., transmission_line, substation_equipment, distribution_transformer, gas_pipeline, metering_equipment, building). Determines depreciation rules and FERC plant account. [ENUM-REF-CANDIDATE: transmission_line|substation_equipment|distribution_transformer|gas_pipeline|metering_equipment|building|land|vehicle — promote to reference product]',
    `authorization_date` DATE COMMENT 'The date on which the capital expenditure for this WBS element was formally authorized by management per the companys Capital Authorization Policy (CAP). Required for CAPEX governance audit trails.',
    `billing_element_flag` BOOLEAN COMMENT 'Indicates whether this WBS element is designated as a billing element in SAP PS, enabling it to be used as a reference for customer billing (e.g., for developer-funded projects or contributed capital work orders). True = billing element; False = internal cost tracking only.',
    `budget_amount` DECIMAL(18,2) COMMENT 'Approved capital budget allocated to this WBS element in US dollars. Represents the authorized spending limit for this scope of work. Used for budget vs. actual variance analysis and CAPEX tracking.',
    `capitalization_date` DATE COMMENT 'The accounting date on which costs accumulated on this WBS element were capitalized and settled to a fixed asset record in SAP FI-AA. May differ from in-service date due to accounting close cycles.',
    `committed_cost_amount` DECIMAL(18,2) COMMENT 'Total value of open purchase orders and contracts committed against this WBS element but not yet invoiced or posted as actual costs. Represents financial obligations for cash flow forecasting and budget availability management.',
    `company_code` STRING COMMENT 'Four-character SAP FI company code identifying the legal entity responsible for this WBS element. Enables multi-entity financial reporting and intercompany cost allocation for utilities with multiple regulated subsidiaries.. Valid values are `^[A-Z0-9]{4}$`',
    `controlling_area_code` STRING COMMENT 'Four-character SAP CO controlling area code under which this WBS element is managed. Defines the organizational unit for internal cost accounting, budget management, and management reporting.. Valid values are `^[A-Z0-9]{4}$`',
    `cpcn_number` STRING COMMENT 'The regulatory permit number (Certificate of Public Convenience and Necessity) issued by the State PUC authorizing construction of the facility associated with this WBS element. Required for major transmission and generation projects. Null if no CPCN is required.',
    `created_timestamp` TIMESTAMP COMMENT 'The date and time when this WBS element record was first created in SAP PS. Provides the audit trail start point for the WBS element lifecycle. Format: yyyy-MM-ddTHH:mm:ss.SSSXXX.',
    `currency_code` STRING COMMENT 'Three-letter ISO 4217 currency code for all monetary amounts on this WBS element (e.g., USD). Power and Utilities operates primarily in USD; this field supports multi-currency project reporting for international procurement.. Valid values are `^[A-Z]{3}$`',
    `driver_category` STRING COMMENT 'Business driver justifying this capital investment at the WBS element level. Used for rate case cost-of-service studies to demonstrate prudency and necessity of capital expenditures to regulators. safety = OSHA/PHMSA compliance; reliability = SAIDI/SAIFI improvement; regulatory = FERC/NERC/PUC mandate. [ENUM-REF-CANDIDATE: safety|reliability|regulatory|growth|efficiency|environmental|customer_request — 7 candidates stripped; promote to reference product]',
    `ferc_account_code` STRING COMMENT 'FERC Uniform System of Accounts plant account code associated with this WBS element (e.g., 353 for Station Equipment, 365 for Transmission Lines, 374 for Distribution Plant). Required for FERC Form 1 reporting and rate base determination.. Valid values are `^[0-9]{3}(.{1}[0-9]{1,3})?$`',
    `forecast_cost_amount` DECIMAL(18,2) COMMENT 'Project managers current estimate of total cost at completion for this WBS element, incorporating actuals to date plus remaining work estimate. Used for EAC (Estimate at Completion) reporting and CAPEX forecast submissions to regulators.',
    `forecast_finish_date` DATE COMMENT 'Project managers current estimate of the completion date for this WBS element, updated periodically during project execution. Used for CAPEX in-service date forecasting submitted to regulators and for IRP planning.',
    `hierarchy_level` STRING COMMENT 'Numeric level of this WBS element within the project hierarchy (1 = top-level project summary, 2 = major deliverable, 3 = work package, 4+ = activity/task). Drives roll-up logic in CAPEX reporting.',
    `in_service_date` DATE COMMENT 'The date on which the asset constructed under this WBS element was placed in service and began depreciating. This is the FASB ASC 360 and FERC-defined date that triggers inclusion in the Regulatory Asset Base (RAB) and commencement of depreciation.',
    `last_changed_timestamp` TIMESTAMP COMMENT 'The date and time when this WBS element record was most recently modified in SAP PS. Used for change detection in incremental data loads and audit trail compliance. Format: yyyy-MM-ddTHH:mm:ss.SSSXXX.',
    `long_description` STRING COMMENT 'Extended narrative description of the WBS element scope, deliverables, and technical specifications. Supports detailed project documentation and regulatory cost-of-service study narratives.',
    `original_budget_amount` DECIMAL(18,2) COMMENT 'The initial approved budget for this WBS element at the time of project authorization, before any budget supplements or transfers. Enables tracking of budget changes over the project lifecycle for governance and audit purposes.',
    `planned_finish_date` DATE COMMENT 'The scheduled completion date for work on this WBS element as defined in the project plan. Drives CAPEX in-service date forecasting and depreciation commencement planning.',
    `planned_start_date` DATE COMMENT 'The scheduled start date for work on this WBS element as defined in the project plan. Used for project scheduling, resource planning, and CAPEX spend phasing in financial forecasts.',
    `planning_element_flag` BOOLEAN COMMENT 'Indicates whether this WBS element is designated as a planning element in SAP PS, allowing cost planning and budget assignment at this level. True = planning element; False = cost collection only without direct budget assignment.',
    `plant_type` STRING COMMENT 'Classification of the utility plant type for this WBS element per FERC Uniform System of Accounts. Drives rate base inclusion, depreciation rate assignment, and cost-of-service study allocation.. Valid values are `generation|transmission|distribution|general_plant|intangible`',
    `priority` STRING COMMENT 'Business priority assigned to this WBS element, reflecting urgency and strategic importance (e.g., safety-critical infrastructure, regulatory mandate, reliability improvement, growth). Drives capital allocation decisions during budget constrained periods.. Valid values are `critical|high|medium|low`',
    `project_id` BIGINT COMMENT 'Reference to the parent capital project (SAP PS Project Definition) under which this WBS element is organized. Every WBS element belongs to exactly one project.',
    `project_type` STRING COMMENT 'Classification of the capital project type associated with this WBS element. Drives CAPEX vs OPEX accounting treatment, regulatory rate base inclusion, and FERC account mapping. regulatory covers rate case and compliance-driven projects; environmental covers EPA/OSHA mandated remediation.. Valid values are `capex|opex|maintenance|regulatory|environmental|safety`',
    `settled_amount` DECIMAL(18,2) COMMENT 'Total costs that have been settled from this WBS element to fixed assets (AuC — Asset under Construction) or other receivers upon project completion. Represents the capitalized value transferred to the Regulatory Asset Base (RAB).',
    `settlement_rule` STRING COMMENT 'Defines how costs accumulated on this WBS element are to be settled to receivers (fixed assets, cost centers, or other WBS elements). full_settlement = 100% to one receiver; partial_settlement = split across multiple receivers; periodic_settlement = settled on a recurring schedule; no_settlement = costs remain on WBS (e.g., expensed OPEX).. Valid values are `full_settlement|partial_settlement|periodic_settlement|no_settlement`',
    `statistical_flag` BOOLEAN COMMENT 'Indicates whether this WBS element is statistical in SAP CO, meaning costs are posted for reporting purposes only and do not affect the primary cost object. Used for management reporting overlays without impacting financial accounting.',
    `user_status` STRING COMMENT 'Business-defined user status applied to the WBS element beyond the SAP system status (e.g., APPR = Approved, PEND = Pending Approval, HOLD = On Hold, CANC = Cancelled). Configured per company-specific status profiles in SAP PS. [ENUM-REF-CANDIDATE: approved|pending_approval|on_hold|cancelled|in_review|deferred — promote to reference product]',
    `utility_type` STRING COMMENT 'Identifies whether this WBS element relates to electric operations, natural gas operations, common/shared infrastructure, or other utility services. Critical for regulatory ring-fencing, rate case cost allocation, and FERC/PUC reporting separation.. Valid values are `electric|gas|common|other`',
    `wbs_element_code` STRING COMMENT 'The externally-known alphanumeric code assigned to the WBS element in SAP PS (e.g., PROJ-2024-001.1.2). This is the business-facing identifier used in project documentation, purchase orders, and cost reports. Conforms to the SAP WBS element coding convention.',
    `wbs_element_description` STRING COMMENT 'Short descriptive text explaining the scope of work represented by this WBS element (e.g., Substation 12kV Bus Replacement — Civil Works). Used in project status reports and CAPEX tracking dashboards.',
    `wbs_element_status` STRING COMMENT 'Current system status of the WBS element in SAP PS lifecycle. created = defined but not yet approved for spending; released = approved and open for cost postings; technically_complete = work done, pending financial close; closed = fully settled and closed; locked = temporarily blocked for postings; deleted = logically removed.. Valid values are `created|released|technically_complete|closed|locked|deleted`',
    `work_category` STRING COMMENT 'Functional category of work performed under this WBS element (e.g., new_construction, replacement, upgrade, relocation, decommission, study, land_acquisition). Used for asset capitalization classification and rate base analysis. [ENUM-REF-CANDIDATE: new_construction|replacement|upgrade|relocation|decommission|study|land_acquisition|emergency — promote to reference product]',
    CONSTRAINT pk_wbs_element PRIMARY KEY(`wbs_element_id`)
) COMMENT 'SAP PS Work Breakdown Structure element representing a hierarchical subdivision of a capital project used for granular cost tracking, budget control, and asset capitalization. Each WBS element maps to a specific scope of work within a CAPEX project and accumulates costs that are eventually settled to fixed assets upon project completion.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`finance`.`internal_order` (
    `internal_order_id` BIGINT COMMENT 'Unique surrogate identifier for the SAP CO internal order record in the Databricks Silver Layer. Primary key for this data product.',
    `fixed_asset_id` BIGINT COMMENT 'Surrogate reference to the primary fixed asset or infrastructure asset associated with this internal order. Used when the order collects maintenance or capital costs attributable to a specific T&D asset, generation unit, or facility tracked in the asset management system.',
    `registry_id` BIGINT COMMENT 'Surrogate reference to the primary fixed asset or infrastructure asset associated with this internal order. Used when the order collects maintenance or capital costs attributable to a specific T&D asset, generation unit, or facility tracked in the asset management system.',
    `cost_center_id` BIGINT COMMENT 'Surrogate reference to the SAP CO cost center responsible for this internal order. The responsible cost center is the organizational unit accountable for the costs collected on the order and is used for overhead allocation, budget ownership, and regulatory cost-of-service studies.',
    `gl_account_id` BIGINT COMMENT 'Surrogate reference to the primary General Ledger account associated with this internal order for cost posting and settlement. Supports chart of accounts alignment and FERC Uniform System of Accounts mapping for regulatory financial reporting.',
    `plant_id` BIGINT COMMENT 'Surrogate reference to the SAP plant (Werk) associated with this internal order, representing the operational facility, service territory, or generation site where the work is performed. Used for geographic cost allocation and asset-level regulatory reporting.',
    `wbs_element_id` BIGINT COMMENT 'Surrogate reference to the SAP PS Work Breakdown Structure (WBS) element to which this internal order is subordinate, when the order is used within a larger capital project structure. Applicable for CAPEX-adjacent overhead orders that support project cost collection.',
    `actual_total_cost` DECIMAL(18,2) COMMENT 'Total actual costs posted to this internal order to date, in the controlling area currency. Represents the sum of all cost postings (labor, materials, services, overhead) accumulated on the order. Used for OPEX tracking, regulatory cost recovery, and EBITDA reporting.',
    `budget_amount` DECIMAL(18,2) COMMENT 'Total approved budget amount allocated to this internal order for the planning period, in the controlling area currency. Represents the authorized spending limit for the work activity or cost pool. Used for budget availability control and variance analysis in SAP CO.',
    `budget_profile` STRING COMMENT 'SAP CO budget profile (Budgetprofil) assigned to this internal order, defining the rules for budget availability control including tolerance limits, warning thresholds, and error actions when actual or committed costs exceed the approved budget.',
    `business_area` STRING COMMENT 'SAP FI business area (Geschäftsbereich) associated with this internal order, representing a distinct segment of the utilitys operations (e.g., electric generation, electric distribution, gas distribution, corporate). Used for segment-level financial reporting and FERC jurisdictional cost separation.',
    `closed_date` DATE COMMENT 'The date on which the internal order was fully settled and closed in SAP CO, indicating all costs have been allocated to receivers and the order is archived. Used for financial period-end close management and audit trail.',
    `committed_cost` DECIMAL(18,2) COMMENT 'Total committed costs on this internal order representing purchase orders and contracts issued but not yet invoiced or posted as actual costs. Used for budget availability control and forecasting remaining spend in SAP CO.',
    `company_code` STRING COMMENT 'SAP FI company code (Buchungskreis) to which this internal order belongs, representing the legal entity or regulated utility subsidiary. Used to segregate costs by legal entity for FERC Form 1, state PUC rate case filings, and consolidated financial reporting.',
    `controlling_area` STRING COMMENT 'SAP CO controlling area (Kostenrechnungskreis) within which this internal order is defined. The controlling area establishes the organizational boundary for management accounting, cost allocation, and internal reporting. Typically maps to a regulated utility entity or holding company segment.',
    `created_timestamp` TIMESTAMP COMMENT 'The date and time when this internal order record was first created in SAP CO. Provides the audit trail creation timestamp for data lineage, SOX compliance, and financial record-keeping requirements.',
    `currency_code` STRING COMMENT 'ISO 4217 three-letter currency code for all monetary amounts on this internal order (budget, planned, actual, committed costs). Typically USD for US-based utility operations. Supports multi-currency controlling area configurations for utilities with international operations.. Valid values are `[A-Z]{3}`',
    `end_date` DATE COMMENT 'The planned or actual end date of the internal order, after which no further cost postings are expected. Used for work activity scheduling, budget period closure, and determining when the order should be technically completed and settled.',
    `ferc_account_code` STRING COMMENT 'FERC Uniform System of Accounts (USofA) account code associated with the primary cost type collected on this internal order. Enables direct mapping of internal order costs to FERC Form 1 reporting lines for electric and gas utility regulatory filings. Examples: 588 (Maintenance of Overhead Lines), 878 (Gas Transmission and Distribution).',
    `fiscal_year` STRING COMMENT 'The fiscal year in which this internal order is primarily active and its costs are planned and reported. Used for annual budget cycle management, period-end settlement, and year-over-year cost trend analysis in regulatory rate case filings.',
    `functional_area` STRING COMMENT 'SAP functional area (Funktionsbereich) assigned to the internal order, used to classify costs by business function for funds management and government/regulatory reporting. Common values in utilities include operations, maintenance, administration, and customer service.',
    `last_settled_date` DATE COMMENT 'The date of the most recent period-end settlement run that allocated costs from this internal order to its settlement receivers. Used to confirm that period-end close processes have been completed and to identify orders with outstanding unsettled costs.',
    `last_updated_timestamp` TIMESTAMP COMMENT 'The date and time when this internal order record was most recently modified in SAP CO or the Silver Layer. Used for incremental data pipeline processing, change tracking, and audit trail maintenance.',
    `long_description` STRING COMMENT 'Extended narrative description of the internal order providing full context for the work activity, maintenance job, storm event, or overhead pool. Supports regulatory cost justification in rate case filings and FERC Form 1 reporting.',
    `object_class` STRING COMMENT 'SAP CO object class (Objektklasse) of the internal order, which determines how costs are treated in profitability analysis and overhead accounting. overhead = indirect cost pool; investment = capital expenditure collection; profitability = revenue-bearing order; accrual = accrual accounting order.. Valid values are `overhead|investment|profitability|accrual`',
    `opex_capex_indicator` STRING COMMENT 'Indicates whether costs collected on this internal order are classified as Operating Expenditure (OPEX), Capital Expenditure (CAPEX), or a mixed allocation. Critical for regulatory cost-of-service studies, rate case filings, and FERC Form 1 reporting. OPEX orders are expensed in the period; CAPEX orders are capitalized to the Regulatory Asset Base (RAB).. Valid values are `opex|capex|mixed`',
    `order_category` STRING COMMENT 'SAP CO internal order category that determines the fundamental accounting treatment. overhead_order = collects overhead costs for allocation to cost centers; investment_order = collects CAPEX costs for capitalization to fixed assets; accrual_order = supports accrual postings; order_with_revenues = collects both costs and revenues for profitability analysis.. Valid values are `overhead_order|investment_order|accrual_order|order_with_revenues`',
    `order_number` STRING COMMENT 'The externally-known SAP CO internal order number (Auftragsnummer) assigned by the system at creation. Used as the primary business identifier when referencing the order in financial reports, rate case filings, and cross-system integrations. Typically a numeric string (e.g., 700012345).',
    `order_status` STRING COMMENT 'Current lifecycle status of the SAP CO internal order, reflecting its workflow state. created = order defined but not yet approved for cost collection; released = active and accepting cost postings; technically_complete = operational work done, no further postings allowed but order not yet settled; closed = fully settled and archived; deleted = logically removed.. Valid values are `created|released|technically_complete|closed|deleted`',
    `order_type` STRING COMMENT 'SAP CO order type (Auftragsart) that classifies the internal order by its business purpose and controls default parameters such as settlement profile, planning profile, and budget profile. Common utility examples include O&M maintenance orders, storm restoration orders, overhead cost orders, and environmental compliance orders. [ENUM-REF-CANDIDATE: om_maintenance|storm_restoration|overhead_allocation|environmental_compliance|capital_overhead|regulatory_study|safety_compliance — promote to reference product]',
    `overhead_order_flag` BOOLEAN COMMENT 'Indicates whether this internal order functions as an overhead cost pool for collecting and subsequently allocating indirect costs (e.g., fleet overhead, administrative overhead, safety program costs) to cost centers or other orders via SAP CO overhead allocation cycles.',
    `planned_total_cost` DECIMAL(18,2) COMMENT 'Total planned (estimated) cost for this internal order as entered in SAP CO cost planning. Represents the expected cost to complete the work activity or fill the overhead pool. Used for budget-to-actual variance analysis and rate case cost-of-service studies.',
    `planning_profile` STRING COMMENT 'SAP CO planning profile assigned to this internal order, controlling the cost planning methodology (e.g., overall planning, annual planning, detailed planning by cost element). Used to standardize cost estimation approaches across O&M and overhead orders.',
    `profit_center_code` BIGINT COMMENT 'Surrogate reference to the SAP CO profit center associated with this internal order. Enables profitability analysis by business segment (e.g., electric distribution, gas distribution, generation) and supports segment reporting under FASB ASC 280 and FERC jurisdictional cost separation.',
    `regulatory_recovery_flag` BOOLEAN COMMENT 'Indicates whether the costs collected on this internal order are eligible for regulatory cost recovery through rates approved by the PUC or FERC. True = costs are recoverable in rates (e.g., storm restoration, mandated compliance work); False = costs are not recoverable or are subject to disallowance review. Supports regulatory asset/liability accounting under FASB ASC 980.',
    `requesting_cost_center` STRING COMMENT 'SAP CO cost center code of the organizational unit that requested the creation of this internal order. Distinct from the responsible cost center; used to track which department initiated the work activity or cost collection requirement.',
    `responsible_person` STRING COMMENT 'Name or employee identifier of the person responsible for managing and monitoring this internal order, as recorded in SAP CO master data. Used for cost accountability, budget ownership, and audit trail purposes in financial and regulatory reporting.',
    `settlement_receiver_type` STRING COMMENT 'Type of SAP CO settlement receiver to which costs accumulated on this internal order are settled at period-end. Determines the downstream accounting treatment: cost_center = OPEX allocation; fixed_asset = CAPEX capitalization; gl_account = direct G/L posting; wbs_element = project cost roll-up.. Valid values are `cost_center|gl_account|fixed_asset|order|wbs_element|profitability_segment`',
    `settlement_rule_profile` STRING COMMENT 'SAP CO settlement profile (Abrechnungsprofil) assigned to the internal order, defining the rules for how accumulated costs are settled (allocated) to receivers such as cost centers, G/L accounts, fixed assets, or other orders at period-end. Critical for OPEX vs. CAPEX cost classification and regulatory asset capitalization.',
    `short_description` STRING COMMENT 'Brief human-readable description of the internal orders business purpose, as entered in SAP CO (Kurztext field, up to 40 characters). Used in financial reports, cost center allocations, and regulatory filings to identify the nature of the work or cost pool being tracked.',
    `source_system_code` STRING COMMENT 'Identifier of the operational source system from which this internal order record was extracted (e.g., SAP_CO_PRD for the SAP CO production client). Supports data lineage tracking and multi-source reconciliation in the Databricks Silver Layer.',
    `start_date` DATE COMMENT 'The date on which the internal order becomes effective and cost postings are permitted to begin. Represents the planned or actual start of the work activity, maintenance job, or overhead collection period. Used for scheduling, budget period alignment, and regulatory cost period attribution.',
    `statistical_order_flag` BOOLEAN COMMENT 'Indicates whether this internal order is a statistical order in SAP CO. True = statistical order used for reporting and analysis purposes only; costs are posted in parallel to a real cost object (cost center or WBS element) and do not affect actual cost flows. False = real order that carries actual costs for settlement.',
    `storm_event_flag` BOOLEAN COMMENT 'Indicates whether this internal order was created specifically to capture costs associated with a storm restoration event. True = storm restoration order eligible for separate regulatory cost recovery tracking and potential extraordinary cost treatment. Supports SAIDI/SAIFI reporting and storm cost deferral accounting.',
    `technically_complete_date` DATE COMMENT 'The date on which the internal order was set to Technically Complete status in SAP CO, indicating that the operational work is finished and no further cost postings should occur. Triggers the settlement process and is used for regulatory cost period cut-off in rate case filings.',
    `work_order_reference` STRING COMMENT 'Reference number linking this SAP CO internal order to a corresponding Maximo Enterprise Asset Management (EAM) work order or SAP PM maintenance order. Enables cross-system traceability between financial cost collection and physical asset maintenance activities.',
    CONSTRAINT pk_internal_order PRIMARY KEY(`internal_order_id`)
) COMMENT 'SAP CO internal order used to collect and monitor costs for short-term operational activities, maintenance jobs, and overhead cost pools that do not warrant a full project structure. Supports OPEX tracking for O&M activities, storm restoration cost capture for regulatory recovery, and overhead allocation to cost centers.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`finance`.`budget` (
    `budget_id` BIGINT COMMENT 'Unique surrogate identifier for each budget record in the Databricks Silver Layer. Serves as the primary key for the budget data product.',
    `approver_employee_id` BIGINT COMMENT 'Employee identifier of the individual who approved this budget version. Supports governance audit trails, segregation of duties controls, and regulatory compliance documentation.',
    `cost_center_id` BIGINT COMMENT 'SAP CO cost center identifier to which this budget line is assigned (e.g., CC-TRANS-001 for Transmission Operations). Enables cost allocation by organizational unit for OPEX tracking and rate case cost-of-service studies.',
    `employee_id` BIGINT COMMENT 'Employee identifier of the budget owner or cost center manager responsible for this budget line. Supports accountability reporting, approval workflow routing, and variance investigation assignment.',
    `gl_account_id` BIGINT COMMENT 'FK to finance.gl_account',
    `cycle_id` BIGINT COMMENT 'Reference to the IRP planning cycle this budget is associated with. Supports long-range financial planning for generation, transmission, and distribution capital programs as required by state PUC IRP filings.',
    `profit_center_id` BIGINT COMMENT 'Foreign key linking to finance.profit_center. Business justification: Budget header should reference the authoritative Cost Center, Profit Center and WBS Element tables rather than storing duplicate codes.',
    `rate_case_id` BIGINT COMMENT 'Reference to the General Rate Case (GRC) proceeding this budget supports. Links budget data to the regulatory cost-of-service study for PUC rate case filings. Null if not associated with an active rate case.',
    `wbs_element_id` BIGINT COMMENT 'Foreign key linking to finance.wbs_element. Business justification: Budget header should reference the authoritative Cost Center, Profit Center and WBS Element tables rather than storing duplicate codes.',
    `approval_date` DATE COMMENT 'The calendar date on which this budget version received final authorization. Null if not yet approved. Used for governance reporting and establishing the effective date of authorized spending limits.',
    `approval_status` STRING COMMENT 'Current workflow state of the budget record in the approval lifecycle: draft (in preparation), submitted (sent for review), under_review (being evaluated), approved (authorized), rejected (not approved), or withdrawn (recalled). Drives governance controls and rate case readiness.. Valid values are `draft|submitted|under_review|approved|rejected|withdrawn`',
    `asset_class` STRING COMMENT 'For CAPEX budget lines, the ISO 55000 asset class of the capital investment (e.g., Substation Equipment, Transmission Lines, Distribution Transformers, Gas Mains, Generation Plant). Supports RAB valuation, depreciation scheduling, and FERC plant-in-service reporting. Null for OPEX lines.',
    `budget_category` STRING COMMENT 'Classifies the budget line as either Operating Expenditure (OPEX) — recurring operational costs — or Capital Expenditure (CAPEX) — investment in long-lived assets. Critical for RAB valuation, depreciation scheduling, and FERC Form 1 plant-in-service reporting.. Valid values are `OPEX|CAPEX`',
    `budget_number` STRING COMMENT 'Externally-known alphanumeric identifier assigned to the budget in SAP FI/CO (e.g., BUDG-2025-001). Used for cross-system reference and audit trail in rate case filings and FERC Form 1 reporting.',
    `budget_type` STRING COMMENT 'Further classifies the budget by accounting treatment: operating (standard O&M), capital (plant investment), regulatory_asset (deferred cost per FASB ASC 980), or regulatory_liability (deferred revenue/obligation per FASB ASC 980). Supports rate case cost-of-service studies.. Valid values are `operating|capital|regulatory_asset|regulatory_liability`',
    `business_area` STRING COMMENT 'SAP FI business area representing an independent accounting unit within the utility (e.g., Electric, Gas, Corporate). Enables segment reporting and regulatory ring-fencing between electric and gas operations.',
    `capex_program_code` STRING COMMENT 'Identifies the capital investment program or portfolio this CAPEX budget line belongs to (e.g., Grid Modernization, AMI Deployment, Gas Main Replacement). Supports capital program-level reporting and CPCN regulatory filings. Null for OPEX lines.',
    `created_timestamp` TIMESTAMP COMMENT 'The timestamp when this budget record was first created in the system (yyyy-MM-ddTHH:mm:ss.SSSXXX). Provides the audit trail creation anchor for governance, compliance, and data lineage purposes.',
    `currency_code` STRING COMMENT 'ISO 4217 three-letter currency code for the planned amount (e.g., USD). Supports multi-currency reporting for utilities with cross-border operations or foreign-denominated PPAs and energy trading contracts.. Valid values are `^[A-Z]{3}$`',
    `department_code` STRING COMMENT 'Organizational department code responsible for this budget line (e.g., DEPT-TRANS, DEPT-DIST, DEPT-GEN). Supports departmental budget ownership, accountability reporting, and workforce cost allocation.',
    `depreciation_rate` DECIMAL(18,2) COMMENT 'Annual depreciation rate (as a decimal, e.g., 0.0333 for 3.33%) applied to CAPEX budget lines for RAB valuation and FASB ASC 980 regulatory accounting. Null for OPEX lines. Sourced from the utilitys FERC-approved depreciation study.',
    `effective_from` DATE COMMENT 'The date from which this budget version becomes the active, binding financial plan. Supports version-controlled budget management and ensures the correct version is used for variance analysis in each period.',
    `effective_until` DATE COMMENT 'The date on which this budget version is superseded or expires. Null for the currently active version. Enables point-in-time budget reconstruction for audit and regulatory review.',
    `energy_domain` STRING COMMENT 'The utility operational domain to which this budget line belongs: generation (fossil/nuclear/renewable), transmission (bulk electric), distribution (last-mile electric), gas (natural gas procurement and distribution), customer_service, or corporate. Supports FERC functional classification and regulatory ring-fencing.. Valid values are `generation|transmission|distribution|gas|corporate|customer_service`',
    `ferc_account_code` STRING COMMENT 'FERC Uniform System of Accounts code mapped to this budget line (e.g., Account 353 for Station Equipment, Account 878 for Meter Expenses). Required for FERC Form 1 annual report filing and regulatory cost-of-service studies.',
    `fiscal_period` STRING COMMENT 'The fiscal period (month number 1–12) within the fiscal year to which this budget line applies. Enables period-level variance analysis between budgeted and actual costs in SAP FI/CO.',
    `fiscal_year` STRING COMMENT 'The four-digit fiscal year to which this budget applies (e.g., 2025). Aligns with the utilitys regulatory fiscal calendar and supports multi-year IRP financial planning and GRC rate case cost-of-service studies.',
    `functional_area` STRING COMMENT 'SAP FI/CO functional area code classifying the budget by business function (e.g., Generation, Transmission, Distribution, Customer Service, Corporate). Supports FERC Form 1 functional classification and rate case cost allocation.',
    `fund_code` STRING COMMENT 'Identifies the funding source or appropriation fund for this budget line (e.g., general fund, capital improvement fund, rate case recovery fund). Supports regulatory fund accounting and restricted-use tracking.',
    `notes` STRING COMMENT 'Free-text field for budget analysts to document assumptions, drivers, scope changes, or regulatory conditions associated with this budget line. Supports audit trail and rate case documentation.',
    `planned_amount` DECIMAL(18,2) COMMENT 'The budgeted monetary amount for this line item in USD. Represents the authorized spending plan for the GL account, cost center, or WBS element for the specified fiscal period. Core field for variance analysis against actual costs.',
    `planning_horizon_end` DATE COMMENT 'The end date of the planning horizon covered by this budget record (e.g., 2029-12-31). Enables multi-year budget windows for capital programs, IRP cycles, and long-term rate case planning.',
    `planning_horizon_start` DATE COMMENT 'The start date of the planning horizon covered by this budget record (e.g., 2025-01-01). Supports multi-year IRP financial planning and long-range capital investment scheduling.',
    `regulatory_asset_flag` BOOLEAN COMMENT 'Indicates whether this budget line relates to a FASB ASC 980 regulatory asset — a cost deferred for future recovery through rates. True = regulatory asset treatment applies. Supports rate base calculation and PUC rate case filings.',
    `regulatory_liability_flag` BOOLEAN COMMENT 'Indicates whether this budget line relates to a FASB ASC 980 regulatory liability — an obligation to refund amounts to customers through future rate reductions. True = regulatory liability treatment applies.',
    `source_system` STRING COMMENT 'Identifies the originating system from which this budget record was sourced (e.g., SAP_FICO for SAP FI/CO module, MANUAL for analyst-entered records, SPREADSHEET for offline planning tools). Supports data lineage and Silver Layer provenance tracking.. Valid values are `SAP_FICO|MANUAL|SPREADSHEET|ERP_INTERFACE`',
    `submission_date` DATE COMMENT 'The calendar date on which this budget version was formally submitted for review and approval. Supports governance audit trails and regulatory filing deadline tracking for GRC and FERC Form 1.',
    `updated_timestamp` TIMESTAMP COMMENT 'The timestamp of the most recent modification to this budget record (yyyy-MM-ddTHH:mm:ss.SSSXXX). Supports change tracking, audit compliance, and Silver Layer incremental load processing.',
    `variance_threshold_pct` DECIMAL(18,2) COMMENT 'The allowable percentage variance between budgeted and actual costs before a management escalation or re-forecast is triggered (e.g., 10.00 for 10%). Supports automated variance monitoring and financial control governance.',
    `version_number` STRING COMMENT 'Sequential integer version counter within a given version_type, allowing multiple revisions of the same type (e.g., revised_forecast v1, v2). Supports audit trail and change management.',
    `version_type` STRING COMMENT 'Indicates the planning iteration of this budget record: initial_plan (original submission), revised_forecast (mid-year revision), final_approved (board/PUC-approved version), or supplemental (out-of-cycle amendment). Supports version-controlled budget management in SAP FI/CO.. Valid values are `initial_plan|revised_forecast|final_approved|supplemental`',
    CONSTRAINT pk_budget PRIMARY KEY(`budget_id`)
) COMMENT 'Annual and multi-year financial budget records including header-level plan metadata and granular line items for cost centers, profit centers, and capital projects covering both OPEX and CAPEX. Header stores budget version (initial plan, revised forecast, final approved), approval status, and planning horizon. Line items specify GL account, cost center or WBS element, fiscal period, budget category (OPEX/CAPEX), and planned amount. Supports GRC rate case cost-of-service studies, IRP financial planning, and variance analysis between budgeted and actual costs at the account and cost object level.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`finance`.`budget_line` (
    `budget_line_id` BIGINT COMMENT 'Unique surrogate identifier for each budget line item within the enterprise data lakehouse. Primary key for the budget_line product.',
    `budget_id` BIGINT COMMENT 'Reference to the parent budget plan or budget version that this line item belongs to. Links the granular line to its overarching planning document.',
    `budget_plan_budget_id` BIGINT COMMENT 'Reference to the parent budget plan or budget version that this line item belongs to. Links the granular line to its overarching planning document.',
    `ci_account_id` BIGINT COMMENT 'Foreign key linking to engagement.ci_account. Business justification: DETAILED BUDGET LINE reports break down allocations by individual key accounts to monitor performance.',
    `cost_center_id` BIGINT COMMENT 'Reference to the SAP CO cost center responsible for this budget line. Used for departmental cost allocation and management reporting.',
    `facility_id` BIGINT COMMENT 'Foreign key linking to property.facility. Business justification: Budget allocations are often broken out by facility to manage capital and OPEX planning.',
    `fund_id` BIGINT COMMENT 'Reference to the funding source or fund associated with this budget line, such as a regulatory rider fund, capital fund, or operating fund.',
    `gl_account_id` BIGINT COMMENT 'Reference to the General Ledger (GL) account in the chart of accounts to which this budget line is assigned. Drives financial reporting and FERC Form 1 account mapping.',
    `parcel_id` BIGINT COMMENT 'Foreign key linking to property.parcel. Business justification: Budget lines are allocated per parcel to support rate‑case analysis and asset‑level cost tracking.',
    `portfolio_id` BIGINT COMMENT 'Foreign key linking to trading.trading_portfolio. Business justification: Needed for Annual Budget Allocation process to assign budget lines to specific trading portfolios for performance tracking.',
    `profit_center_id` BIGINT COMMENT 'Reference to the SAP CO profit center associated with this budget line. Enables profitability analysis by business segment (e.g., electric distribution, gas distribution).',
    `wbs_element_id` BIGINT COMMENT 'Reference to the SAP PS Work Breakdown Structure (WBS) element for capital project budget lines. Applicable when the budget line is associated with a CAPEX project rather than a cost center.',
    `actual_amount` DECIMAL(18,2) COMMENT 'Actual expenditure or revenue posted to the GL account and cost object for the fiscal period. Sourced from SAP FI actual postings. Used for budget-to-actual variance analysis.',
    `allocation_method` STRING COMMENT 'Method used to allocate shared or indirect costs to this budget line (e.g., Direct, Proportional, Equal Split, Usage-Based, Headcount). Required for cost-of-service studies in rate case filings.. Valid values are `DIRECT|PROPORTIONAL|EQUAL|USAGE_BASED|HEADCOUNT`',
    `approval_status` STRING COMMENT 'Approval workflow status for this budget line, tracking whether it has been reviewed and authorized by the appropriate budget authority. Distinct from overall line status.. Valid values are `PENDING|APPROVED|REJECTED|ESCALATED`',
    `approved_by` STRING COMMENT 'Name or employee identifier of the budget authority who approved this budget line. Required for audit trail and delegation of authority compliance.',
    `approved_date` DATE COMMENT 'Date on which this budget line was formally approved by the designated budget authority.',
    `asset_class_code` STRING COMMENT 'SAP AM asset class code for CAPEX budget lines, indicating the type of fixed asset to be created (e.g., transmission lines, distribution transformers, meters). Drives depreciation rules and RAB classification.',
    `budget_category` STRING COMMENT 'Classifies the budget line as Capital Expenditure (CAPEX) or Operating Expenditure (OPEX). Critical for regulatory asset base (RAB) valuation, rate case filings, and FASB ASC 980 accounting treatment.. Valid values are `CAPEX|OPEX`',
    `budget_control_active` BOOLEAN COMMENT 'Indicates whether SAP CO budget availability control is active for this budget line, preventing expenditures from exceeding the approved budget amount.',
    `budget_line_status` STRING COMMENT 'Current workflow status of the budget line item. Controls editability and approval routing within the budget planning process.. Valid values are `DRAFT|SUBMITTED|APPROVED|REJECTED|LOCKED|CLOSED`',
    `budget_type` STRING COMMENT 'Indicates whether this line represents the original approved budget, a revised budget, a rolling forecast, or a supplemental budget request. Supports variance analysis across budget versions.. Valid values are `ORIGINAL|REVISED|FORECAST|SUPPLEMENTAL`',
    `business_unit_code` STRING COMMENT 'Code identifying the business unit or operating division responsible for this budget line (e.g., Electric Generation, Electric Distribution, Gas Distribution, Corporate). Supports segment reporting.',
    `committed_amount` DECIMAL(18,2) COMMENT 'Amount committed against this budget line through purchase orders, contracts, or work orders that have been approved but not yet invoiced. Derived from SAP MM/PM commitment management.',
    `cost_type` STRING COMMENT 'Distinguishes between direct costs attributable to a specific activity, indirect costs, allocated overhead, or shared service charges. Used in cost-of-service studies for rate case filings.. Valid values are `DIRECT|INDIRECT|ALLOCATED|OVERHEAD`',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when this budget line record was first created in the system. Supports audit trail and data lineage requirements.',
    `currency_code` STRING COMMENT 'ISO 4217 three-letter currency code for all monetary amounts on this budget line (e.g., USD). Supports multi-currency reporting for international operations or hedging activities.. Valid values are `^[A-Z]{3}$`',
    `depreciation_amount` DECIMAL(18,2) COMMENT 'Planned depreciation expense budgeted for this line item in the fiscal period. Applicable to CAPEX lines where asset depreciation is being planned. Supports EBITDA reporting and RAB calculations.',
    `effective_end_date` DATE COMMENT 'The date on which this budget line expires and no further expenditures may be charged against it. Typically aligns with fiscal period or fiscal year end.',
    `effective_start_date` DATE COMMENT 'The date from which this budget line becomes effective and expenditures may be incurred against it. Aligns with the fiscal period start.',
    `expenditure_type` STRING COMMENT 'Detailed classification of the expenditure nature (e.g., Labor, Materials, Contractor Services, Depreciation, Fuel, Transmission Charges). Supports O&M cost categorization for regulatory reporting. [ENUM-REF-CANDIDATE: Labor|Materials|Contractor Services|Depreciation|Fuel|Transmission Charges|Other — promote to reference product]',
    `ferc_account_code` STRING COMMENT 'FERC Uniform System of Accounts code mapped to this budget line. Required for FERC Form 1 annual report filing and regulatory cost allocation.. Valid values are `^[0-9]{3,6}$`',
    `fiscal_period` STRING COMMENT 'The fiscal period (month 1–12 or 13 for year-end adjustments) within the fiscal year to which this budget line applies. Enables monthly budget-to-actual variance analysis.',
    `fiscal_quarter` STRING COMMENT 'The fiscal quarter (1–4) within the fiscal year. Supports quarterly financial reporting and regulatory filing schedules.',
    `fiscal_year` STRING COMMENT 'The fiscal year to which this budget line applies. Aligns with the utilitys regulatory and financial reporting calendar year.',
    `functional_area_code` STRING COMMENT 'SAP CO functional area code classifying the budget line by business function (e.g., Generation, Transmission, Distribution, Customer Service, Administration). Used for functional cost reporting.',
    `internal_order_number` STRING COMMENT 'SAP CO internal order number used for temporary cost collection on specific projects or activities not managed as WBS elements. Supports granular cost tracking for O&M activities.',
    `last_updated_timestamp` TIMESTAMP COMMENT 'Timestamp when this budget line record was most recently modified. Used for incremental data loading, change tracking, and audit compliance.',
    `line_description` STRING COMMENT 'Free-text description of the budget line item, explaining the nature of the planned expenditure or revenue. Used in rate case cost-of-service studies and management reporting.',
    `line_number` STRING COMMENT 'Sequential line number within the parent budget plan, used for ordering and referencing individual line items in budget documents and reports.',
    `notes` STRING COMMENT 'Free-text notes or justification comments entered by the budget owner or approver. Captures business rationale for the budget line, particularly for rate case cost justification.',
    `planned_amount` DECIMAL(18,2) COMMENT 'The approved planned budget amount for this line item in the functional currency (USD). Represents the authorized spending or revenue target for the specified GL account, cost object, and fiscal period.',
    `program_code` STRING COMMENT 'Internal program or initiative code associated with this budget line (e.g., Grid Modernization, AMI Deployment, Demand Response Program). Enables cross-functional program cost tracking.',
    `project_number` STRING COMMENT 'The SAP PS or Maximo project number associated with this CAPEX budget line. Links the budget line to the capital project for CAPEX tracking and RAB valuation.',
    `rate_case_flag` BOOLEAN COMMENT 'Indicates whether this budget line is included in a General Rate Case (GRC) or rate case cost-of-service study filing. True when the cost is subject to regulatory review for rate recovery.',
    `rate_case_reference` STRING COMMENT 'The docket number or reference identifier of the regulatory rate case (GRC) to which this budget line is associated. Enables traceability from budget to regulatory filing.',
    `regulatory_asset_flag` BOOLEAN COMMENT 'Indicates whether this budget line relates to a regulatory asset or liability as defined under FASB ASC 980 Regulated Operations. True when the cost is expected to be recovered through future rates.',
    `revised_amount` DECIMAL(18,2) COMMENT 'The revised or adjusted budget amount following a formal budget amendment or reforecast. Null if no revision has been made. Supports variance analysis between original and revised budgets.',
    `source_system_key` STRING COMMENT 'The natural key or document number from the originating SAP FI/CO system (e.g., SAP budget document number) that uniquely identifies this record in the source system. Supports data lineage and reconciliation.',
    `variance_threshold_pct` DECIMAL(18,2) COMMENT 'The allowable percentage variance between planned and actual amounts before a budget exception alert is triggered. Used in management reporting and budget control processes.',
    CONSTRAINT pk_budget_line PRIMARY KEY(`budget_line_id`)
) COMMENT 'Granular budget line items within a budget plan, specifying the GL account, cost center or WBS element, fiscal period, budget category (OPEX/CAPEX), and planned amount. Enables variance analysis between budgeted and actual costs at the account and cost object level for management reporting and regulatory cost justification.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`finance`.`fixed_asset` (
    `fixed_asset_id` BIGINT COMMENT 'Unique surrogate identifier for each fixed asset record in the utility plant accounting system. Primary key for the fixed_asset data product.',
    `cost_center_id` BIGINT COMMENT 'Foreign key linking to finance.cost_center. Business justification: Fixed Asset must be linked to Cost Center, WBS Element, and GL Account for cost tracking and depreciation.',
    `facility_id` BIGINT COMMENT 'Foreign key linking to property.facility. Business justification: Fixed assets are installed at specific facilities; linking supports depreciation schedules and regulatory asset registers.',
    `gl_account_id` BIGINT COMMENT 'Foreign key linking to finance.gl_account. Business justification: Fixed Asset must be linked to GL Account for financial reporting.',
    `parcel_id` BIGINT COMMENT 'Foreign key linking to property.parcel. Business justification: Fixed assets (transformers, meters) are physically located on parcels; linking enables asset‑location compliance and depreciation reporting.',
    `accumulated_depreciation` DECIMAL(18,2) COMMENT 'Total depreciation charged against the asset from in-service date through the current reporting period for book (GAAP) purposes. Used to compute net book value and reported on FERC Form 1 Schedule of Accumulated Depreciation. Expressed in USD.',
    `acquisition_date` DATE COMMENT 'Date the asset was acquired or purchased, which may differ from the in-service date for assets requiring installation or construction. Used for asset age analysis and procurement tracking.',
    `asset_category` STRING COMMENT 'High-level functional category of the utility plant asset used for financial reporting segmentation and regulatory rate base grouping. Aligns with FERC functional classification of utility plant. [ENUM-REF-CANDIDATE: generation|transmission|distribution|gas_pipeline|nuclear|renewable|land_rights|building|general_plant|intangible|right_of_use — 11 candidates stripped; promote to reference product]',
    `asset_class` STRING COMMENT 'SAP FI-AA asset class grouping assets by type for depreciation key assignment and balance sheet presentation (e.g., ELEC-GEN, ELEC-TRANS, ELEC-DIST, GAS-TRANS, GAS-DIST, NUCLEAR, RENEWABLE, LAND, BUILDING, VEHICLE, IT-EQUIP). Drives default depreciation parameters. [ENUM-REF-CANDIDATE: ELEC-GEN|ELEC-TRANS|ELEC-DIST|GAS-TRANS|GAS-DIST|NUCLEAR|RENEWABLE|LAND|BUILDING|VEHICLE|IT-EQUIP|OTHER — promote to reference product]',
    `asset_description` STRING COMMENT 'Short descriptive name of the fixed asset as recorded in the asset master (e.g., 138kV Transmission Line Segment, Gas Distribution Main 4-inch PE, 500MW Steam Turbine Unit 3). Used in financial reports and rate case exhibits.',
    `asset_long_description` STRING COMMENT 'Extended narrative description of the fixed asset providing additional technical and location context beyond the short description. Supports regulatory filings and depreciation study documentation.',
    `asset_number` STRING COMMENT 'Externally-known unique asset identifier assigned by SAP Asset Accounting (FI-AA) or Maximo EAM. Serves as the cross-system business key used in rate case filings, FERC Form 1 schedules, and work order references. Corresponds to the SAP Asset Master Asset Number field.',
    `asset_retirement_obligation` DECIMAL(18,2) COMMENT 'Present value of the legal obligation to retire the asset at end of useful life (e.g., nuclear decommissioning, PCB-contaminated equipment disposal, gas pipeline abandonment). Recorded as a liability under FASB ASC 410-20. Expressed in USD.',
    `asset_status` STRING COMMENT 'Current lifecycle status of the fixed asset. in_service indicates the asset is placed in service and subject to depreciation. under_construction indicates construction work in progress (CWIP) not yet capitalized. retired indicates the asset has been removed from service. Critical for RAB inclusion determination and depreciation run eligibility. [ENUM-REF-CANDIDATE: in_service|under_construction|retired|disposed|held_for_sale|impaired|transferred — 7 candidates stripped; promote to reference product]',
    `asset_subnumber` STRING COMMENT 'SAP FI-AA sub-number that identifies a component or sub-asset under the main asset number, enabling component-level depreciation tracking (e.g., turbine blades vs. turbine frame). Null for assets without sub-components.',
    `asset_type` STRING COMMENT 'Accounting classification distinguishing tangible utility plant, intangible plant (e.g., software, franchises), right-of-use assets under ASC 842 operating leases, and finance lease assets. Determines balance sheet presentation and applicable accounting standard.. Valid values are `tangible|intangible|right_of_use|finance_lease`',
    `bonus_depreciation_taken` BOOLEAN COMMENT 'Indicates whether federal bonus depreciation (100% first-year expensing under Tax Cuts and Jobs Act or prior bonus depreciation provisions) was claimed for this asset. Affects deferred tax calculations and normalization requirements under FASB ASC 980-740 for regulated utilities.',
    `book_depreciation_method` STRING COMMENT 'Depreciation method applied for GAAP (book) financial reporting purposes. Regulated utilities predominantly use straight-line or group straight-line methods as approved by the PUC in depreciation studies. Corresponds to SAP FI-AA depreciation key for depreciation area 01.. Valid values are `straight_line|declining_balance|sum_of_years_digits|units_of_production|group_straight_line`',
    `book_depreciation_rate` DECIMAL(18,2) COMMENT 'Annual depreciation rate applied for GAAP book purposes, expressed as a decimal (e.g., 0.025000 = 2.5% per year). Derived from useful life and net salvage percentage. Used to compute annual book depreciation expense.',
    `business_area` STRING COMMENT 'SAP FI business area representing the utility segment (electric vs. gas) or functional division. Used for segment reporting, separate electric and gas rate case filings, and FERC Form 1 functional classification.',
    `capitalized_interest` DECIMAL(18,2) COMMENT 'Allowance for Funds Used During Construction (AFUDC) or capitalized interest included in the original cost of the asset. For regulated utilities, AFUDC represents the cost of financing construction and is capitalized per FASB ASC 980-835 and FERC regulations. Expressed in USD.',
    `company_code` STRING COMMENT 'SAP FI company code identifying the legal entity that owns the asset. For multi-state utilities, different company codes may represent different regulated operating companies with separate rate cases and FERC filings.',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when the fixed asset record was first created in the source system (SAP FI-AA). Used for audit trail, data lineage, and record age analysis.',
    `current_period_depreciation` DECIMAL(18,2) COMMENT 'Depreciation expense charged for the current accounting period (month or year) for book purposes. Represents the periodic allocation of the depreciable base over the assets useful life. Expressed in USD.',
    `depreciable_base` DECIMAL(18,2) COMMENT 'The amount subject to depreciation, calculated as original cost minus net salvage value (salvage value minus removal cost estimate). This is the base used to compute periodic depreciation expense. Expressed in USD.',
    `depreciation_area_01_amount` DECIMAL(18,2) COMMENT 'Accumulated depreciation in SAP FI-AA Depreciation Area 01, representing the GAAP book depreciation basis. This is the primary depreciation area used for financial statement reporting and FERC Form 1. Expressed in USD.',
    `depreciation_area_15_amount` DECIMAL(18,2) COMMENT 'Accumulated depreciation in SAP FI-AA Depreciation Area 15, representing the federal income tax (MACRS) depreciation basis. The difference between Area 15 and Area 01 drives the deferred income tax liability calculation under FASB ASC 740. Expressed in USD.',
    `depreciation_area_30_amount` DECIMAL(18,2) COMMENT 'Accumulated depreciation in SAP FI-AA Depreciation Area 30, representing the PUC-approved regulatory depreciation basis. Differences from Area 01 create regulatory assets or liabilities under FASB ASC 980. Expressed in USD.',
    `depreciation_start_date` DATE COMMENT 'Date from which depreciation began being calculated for this asset. Typically equals the in-service date but may differ for assets with deferred depreciation start (e.g., regulatory lag assets or assets with PUC-approved deferred depreciation treatment under FASB ASC 980).',
    `disposal_proceeds` DECIMAL(18,2) COMMENT 'Actual proceeds received from the sale or salvage of the retired asset. Used to compute gain or loss on retirement and to update depreciation reserve accounts. Compared against salvage value estimate for depreciation study calibration. Expressed in USD.',
    `ferc_jurisdictional` BOOLEAN COMMENT 'Indicates whether the asset is subject to FERC jurisdiction (True) for transmission assets under FERCs Open Access Transmission Tariff (OATT) or wholesale rate regulation, versus state PUC jurisdiction only (False). Determines applicable regulatory accounting requirements and rate case venue.',
    `ferc_plant_account` STRING COMMENT 'FERC Uniform System of Accounts plant account number classifying the asset (e.g., Account 311 - Steam Production Land, Account 353 - Station Equipment, Account 376 - Distribution Mains, Account 376.1 - Gas Transmission Lines). Mandatory for FERC Form 1 reporting and rate case cost-of-service studies.',
    `gis_feature_reference` STRING COMMENT 'Cross-reference identifier linking this fixed asset to its spatial feature record in Esri ArcGIS. Enables geographic rate base analysis, storm damage assessment, and regulatory reporting by geographic area.',
    `impairment_loss` DECIMAL(18,2) COMMENT 'Cumulative impairment loss recognized on the asset when its carrying amount exceeds its recoverable amount. For regulated utilities, impairment may be deferred as a regulatory asset if recovery through future rates is probable under FASB ASC 980. Expressed in USD.',
    `in_service_date` DATE COMMENT 'Date the asset was placed in service and depreciation commenced. This is the capitalization date used for depreciation calculation start, rate base inclusion, and FERC Form 1 reporting. Corresponds to SAP FI-AA Capitalization Date.',
    `last_depreciation_run_date` DATE COMMENT 'Date of the most recent depreciation calculation run executed in SAP FI-AA for this asset. Used to verify depreciation currency and identify assets that may have missed a depreciation posting period.',
    `last_modified_timestamp` TIMESTAMP COMMENT 'Timestamp of the most recent modification to the fixed asset master record in the source system. Used for change detection in ETL processes and audit trail compliance.',
    `macrs_property_class` STRING COMMENT 'IRS MACRS property class determining the tax depreciation recovery period (e.g., 5-year, 7-year, 15-year, 20-year). Utility transmission and distribution assets typically fall in the 15-year or 20-year MACRS class. Drives deferred income tax calculations under FASB ASC 740.. Valid values are `5yr|7yr|10yr|15yr|20yr|27.5yr|39yr|ads`',
    `maximo_asset_reference` STRING COMMENT 'Cross-reference identifier linking this financial fixed asset record to the corresponding physical asset record in Maximo Enterprise Asset Management (EAM). Enables reconciliation between financial accounting (SAP FI-AA) and physical asset management (Maximo) for O&M cost allocation and maintenance history.',
    `net_book_value` DECIMAL(18,2) COMMENT 'Current net book value of the asset computed as original cost minus accumulated depreciation (book basis). Represents the carrying amount on the balance sheet and is a key input to rate base (RAB) valuation. Expressed in USD.',
    `original_cost` DECIMAL(18,2) COMMENT 'Original cost of the asset at the time of acquisition or construction completion, representing the gross plant investment recorded in the utility plant accounts. Basis for FERC Form 1 gross plant reporting, rate base (RAB) calculation, and depreciation base. Expressed in USD.',
    `plant_location` STRING COMMENT 'Physical location or facility where the asset is installed or operated (e.g., Riverside Generating Station, Substation 47 - North District, Gas Compressor Station 12). Used for geographic rate base allocation and GIS integration with Esri ArcGIS.',
    `purchase_order_number` STRING COMMENT 'SAP MM purchase order number associated with the procurement of this asset. Provides traceability from the capitalized asset back to the original procurement transaction for audit and CAPEX tracking purposes.',
    `rab_exclusion_reason` STRING COMMENT 'Reason code explaining why the asset is excluded from the Regulatory Asset Base (RAB) when rab_included is False. Used in rate case testimony and PUC filings to document plant disallowances or exclusions.. Valid values are `not_used_and_useful|excess_capacity|puc_disallowance|abandoned_plant|regulatory_lag|other`',
    `rab_included` BOOLEAN COMMENT 'Indicates whether this asset is included in the Regulatory Asset Base (RAB) for rate case cost-of-service studies. Assets excluded from RAB (e.g., assets not used and useful, excess capacity, or disallowed plant) do not earn a return in rates. Critical for rate case preparation and PUC filings.',
    `regulatory_accumulated_depreciation` DECIMAL(18,2) COMMENT 'Total depreciation accumulated using the PUC-approved regulatory depreciation rate from in-service date through current period. Differences between regulatory and book accumulated depreciation create regulatory assets or liabilities under FASB ASC 980. Expressed in USD.',
    `regulatory_depreciation_method` STRING COMMENT 'Depreciation method approved by the state PUC or FERC for regulatory ratemaking purposes. May differ from book depreciation method, creating regulatory assets or liabilities under FASB ASC 980. Used in rate case cost-of-service studies and FERC Form 1 regulatory depreciation schedules.. Valid values are `straight_line|group_straight_line|remaining_life|equal_life_group`',
    `regulatory_depreciation_rate` DECIMAL(18,2) COMMENT 'Annual depreciation rate approved by the state PUC or FERC for ratemaking purposes, expressed as a decimal. May differ from book depreciation rate, creating regulatory timing differences. Filed in rate case depreciation studies and FERC Form 1.',
    `remaining_useful_life_years` DECIMAL(18,2) COMMENT 'Estimated remaining service life of the asset in years as of the last depreciation study or reporting period. Used in remaining-life depreciation method calculations and impairment assessments. Key input for rate case depreciation expense projections.',
    `removal_cost_estimate` DECIMAL(18,2) COMMENT 'Estimated cost of removing or retiring the asset at end of useful life (cost of removal). For regulated utilities, net salvage (salvage value minus removal cost) is used in depreciation rate calculations filed with the PUC. Expressed in USD.',
    `retirement_cost` DECIMAL(18,2) COMMENT 'Actual cost incurred to retire and remove the asset from service, including demolition, dismantling, and site remediation costs. Compared against the removal cost estimate for depreciation study accuracy assessment. Expressed in USD.',
    `retirement_date` DATE COMMENT 'Date the asset was retired or removed from service. Triggers cessation of depreciation and initiates retirement accounting entries including removal of original cost and accumulated depreciation from plant accounts. Null for active assets.',
    `retirement_type` STRING COMMENT 'Classification of the asset retirement event. Normal retirements occur at end of useful life; abnormal retirements occur prematurely due to storm damage, obsolescence, or regulatory disallowance. Abandonment may trigger regulatory asset treatment under FASB ASC 980.. Valid values are `normal_retirement|abnormal_retirement|sale|transfer|abandonment|condemnation`',
    `salvage_value` DECIMAL(18,2) COMMENT 'Estimated residual or salvage value of the asset at the end of its useful life, used to determine the depreciable base (original cost minus salvage value). Established through depreciation studies filed with state PUCs. Expressed in USD.',
    `state_jurisdiction` STRING COMMENT 'Two-letter US state code identifying the regulatory jurisdiction under which this asset is rate-based. Determines which state PUC has authority over the assets inclusion in rates. Critical for multi-state utilities performing jurisdictional cost allocation.',
    `tax_accumulated_depreciation` DECIMAL(18,2) COMMENT 'Total depreciation accumulated for federal income tax purposes (MACRS basis) from in-service date through current period. The difference between tax and book accumulated depreciation represents the temporary timing difference driving deferred income tax balances under FASB ASC 740 and ASC 980. Expressed in USD.',
    `tax_depreciation_method` STRING COMMENT 'Depreciation method applied for federal income tax purposes. Most utility assets use Modified Accelerated Cost Recovery System (MACRS) per IRS guidelines, creating timing differences between book and tax depreciation that generate deferred income tax liabilities tracked under FASB ASC 980. Corresponds to SAP FI-AA depreciation area 15.. Valid values are `macrs|ads_straight_line|bonus_depreciation|sum_of_years_digits|straight_line`',
    `useful_life_years` DECIMAL(18,2) COMMENT 'Estimated useful service life of the asset in years as established by the PUC-approved depreciation study. Drives the straight-line depreciation rate. For group depreciation, this represents the average service life of the asset group. Corresponds to SAP FI-AA Useful Life field.',
    `vendor_number` STRING COMMENT 'SAP MM vendor number identifying the supplier from whom the asset was procured. Used for procurement analytics, vendor performance tracking, and supply chain cost analysis for capital projects.',
    CONSTRAINT pk_fixed_asset PRIMARY KEY(`fixed_asset_id`)
) COMMENT 'Comprehensive fixed asset accounting record for all capitalized utility plant assets including generation equipment, transmission lines, distribution infrastructure, gas pipeline assets, and right-of-use assets from leases. Encompasses the asset master (original cost, in-service date, FERC plant account classification, RAB inclusion status), periodic depreciation calculations across all depreciation areas (book, tax, regulatory) with method and useful life parameters, accumulated depreciation, net book value, retirement/disposal tracking, and depreciation run history. Supports FASB ASC 980 regulatory depreciation studies, rate case depreciation expense justification, and FERC Form 1 accumulated depreciation reporting.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`finance`.`depreciation_run` (
    `depreciation_run_id` BIGINT COMMENT 'Unique surrogate identifier for each depreciation run record in the SAP FI-AA periodic depreciation calculation. Serves as the primary key for this data product.',
    `fixed_asset_id` BIGINT COMMENT 'Reference to the fixed asset record in SAP FI-AA for which depreciation is being calculated. Links to the asset master data including asset class, useful life, and acquisition value.',
    `registry_id` BIGINT COMMENT 'Reference to the fixed asset record in SAP FI-AA for which depreciation is being calculated. Links to the asset master data including asset class, useful life, and acquisition value.',
    `depreciation_area_id` BIGINT COMMENT 'Reference to the depreciation area definition record. SAP FI-AA supports multiple parallel depreciation areas (e.g., book/GAAP, tax, regulatory/FERC) for the same asset.',
    `employee_id` BIGINT COMMENT 'SAP user ID of the person who initiated and executed the depreciation run. Required for SOX internal controls, audit trail documentation, and segregation of duties compliance in the financial close process.',
    `accumulated_depreciation_amount` DECIMAL(18,2) COMMENT 'Total accumulated depreciation for the asset in the specified depreciation area as of the end of the fiscal period, including all prior period depreciation plus the current period posted amount. Key metric for FERC Form 1 balance sheet reporting and RAB valuation.',
    `acquisition_value_amount` DECIMAL(18,2) COMMENT 'Original acquisition cost (gross plant value) of the asset in the specified depreciation area as of the depreciation run date. Serves as the depreciable base for depreciation calculations and FERC Form 1 plant-in-service reporting.',
    `asset_class_code` STRING COMMENT 'SAP FI-AA asset class code grouping assets by type for depreciation policy application (e.g., transmission lines, distribution transformers, generation equipment, gas mains, meters). Drives default depreciation parameters and FERC plant account mapping.',
    `asset_number` STRING COMMENT 'The SAP FI-AA asset number (main asset number) identifying the specific fixed asset. Used as the externally visible business identifier for cross-referencing with Maximo EAM and FERC plant account schedules.',
    `asset_subnumber` STRING COMMENT 'SAP FI-AA asset sub-number identifying a component or sub-asset within the main asset record. Supports component-level depreciation tracking for complex utility infrastructure assets.',
    `company_code` STRING COMMENT 'SAP FI company code identifying the legal entity for which the depreciation run is executed. Aligns with the regulated utility legal entity structure for FERC and state PUC reporting purposes.',
    `cost_center_code` STRING COMMENT 'SAP CO cost center to which the depreciation expense is allocated. Supports CAPEX/OPEX tracking, rate case cost-of-service studies, and departmental financial reporting.',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when this depreciation run record was first created in the source system (SAP FI-AA). Used for audit trail and data lineage tracking.',
    `currency_code` STRING COMMENT 'ISO 4217 three-letter currency code for all monetary amounts in this depreciation run record (e.g., USD). Power and Utilities operates primarily in USD; this field supports multi-currency consolidation for holding company structures.. Valid values are `[A-Z]{3}`',
    `deferred_tax_amount` DECIMAL(18,2) COMMENT 'Deferred income tax amount arising from the temporary difference between book depreciation and tax depreciation for the period. Calculated as the difference between tax and book depreciation multiplied by the applicable tax rate. Required for FASB ASC 740 and FERC Form 1 deferred tax reporting.',
    `depreciation_area_code` STRING COMMENT 'SAP FI-AA depreciation area code identifying the valuation basis for this depreciation calculation. Common utility values include 01 (book/GAAP), 10 (federal tax/MACRS), 15 (state tax), 20 (regulatory/FERC), 30 (cost-of-service/rate case). [ENUM-REF-CANDIDATE: 01|10|15|20|30|31|40 — promote to reference product]',
    `depreciation_area_type` STRING COMMENT 'Business classification of the depreciation area indicating the accounting basis. book is GAAP/FASB basis; tax_federal is IRS MACRS basis; tax_state is state tax basis; regulatory is FERC/PUC regulatory basis per ASC 980; cost_of_service is rate case study basis.. Valid values are `book|tax_federal|tax_state|regulatory|cost_of_service`',
    `depreciation_end_date` DATE COMMENT 'The planned end date of depreciation for the asset, representing the date when the asset will be fully depreciated based on its useful life and depreciation start date. Used for asset retirement planning and long-range financial forecasting.',
    `depreciation_method_code` STRING COMMENT 'SAP FI-AA depreciation key/method code defining the calculation algorithm applied (e.g., LINA for straight-line, DEGD for declining balance, MACS for MACRS, REGU for regulatory straight-line). Determines how the depreciable base is allocated over the asset useful life.',
    `depreciation_method_name` STRING COMMENT 'Human-readable name of the depreciation method applied in this run (e.g., Straight-Line, Declining Balance, MACRS 5-Year, Regulatory Straight-Line, Sum-of-Years-Digits). Supports rate case documentation and FERC Form 1 narrative disclosures.',
    `depreciation_start_date` DATE COMMENT 'The date on which depreciation commenced for the asset in the specified depreciation area. Typically the asset capitalization date or in-service date. Critical for calculating elapsed depreciation and verifying compliance with FERC capitalization policies.',
    `document_number` STRING COMMENT 'SAP FI accounting document number generated when depreciation amounts are posted to the general ledger. Provides the audit trail link between the depreciation run and the corresponding journal entry in the financial ledger.',
    `error_message` STRING COMMENT 'System-generated error or warning message from SAP FI-AA when the depreciation run encounters processing issues. Populated only when run_status is error. Used for operational troubleshooting and period-close exception management.',
    `execution_timestamp` TIMESTAMP COMMENT 'The date and time when the depreciation run was initiated and executed in SAP FI-AA. This is the principal business event timestamp representing when the periodic depreciation calculation was performed.',
    `ferc_account_code` STRING COMMENT 'FERC Uniform System of Accounts plant account code associated with the asset (e.g., 311 for Steam Production, 353 for Transmission Lines, 364 for Distribution Poles, 374 for Gas Mains). Required for FERC Form 1 accumulated depreciation schedule reporting.',
    `fiscal_period` STRING COMMENT 'The fiscal period (accounting period, typically 1–12 for monthly) within the fiscal year for which depreciation is calculated and posted. Aligns with SAP FI posting period control.',
    `fiscal_year` STRING COMMENT 'The fiscal year in which the depreciation run is executed and posted. Used for annual FERC Form 1 reporting, FASB ASC 980 regulatory asset/liability reconciliation, and rate case cost-of-service studies.',
    `gl_account_code` STRING COMMENT 'SAP FI general ledger account code to which the depreciation expense is posted (e.g., depreciation expense account or accumulated depreciation contra-asset account). Links the depreciation run to the chart of accounts for financial reporting.',
    `is_catch_up_run` BOOLEAN COMMENT 'Indicates whether this run includes catch-up depreciation for prior periods that were not previously posted (True). Catch-up runs occur when assets are capitalized retroactively or when depreciation parameters are corrected, requiring prior-period adjustments per FASB ASC 250.',
    `is_test_run` BOOLEAN COMMENT 'Indicates whether this depreciation run was executed in simulation/test mode (True) without posting to the general ledger, or as a live posting run (False). Test runs are used for period-close validation and rate case depreciation projections.',
    `last_updated_timestamp` TIMESTAMP COMMENT 'Timestamp when this depreciation run record was last modified in the source system. Tracks status changes, reversals, or corrections applied after initial creation.',
    `net_book_value_amount` DECIMAL(18,2) COMMENT 'Net book value of the asset as of the end of the fiscal period, calculated as acquisition cost less accumulated depreciation in the specified depreciation area. Used for RAB valuation, rate case cost-of-service studies, and balance sheet reporting.',
    `period_end_date` DATE COMMENT 'The last calendar date of the fiscal period covered by this depreciation run. Defines the as-of date for accumulated depreciation balances and net book value calculations.',
    `period_start_date` DATE COMMENT 'The first calendar date of the fiscal period covered by this depreciation run. Used for period-over-period depreciation analysis and FERC Form 1 monthly reporting alignment.',
    `planned_depreciation_amount` DECIMAL(18,2) COMMENT 'The calculated planned depreciation amount for the asset in the specified fiscal period and depreciation area, expressed in the company currency. Represents the depreciation expense as computed by the SAP FI-AA depreciation engine before posting.',
    `posted_depreciation_amount` DECIMAL(18,2) COMMENT 'The actual depreciation amount posted to the general ledger for the asset in the fiscal period. May differ from planned amount due to manual adjustments, partial period calculations, or catch-up depreciation. Core field for FERC Form 1 accumulated depreciation reporting.',
    `posting_date` DATE COMMENT 'The date on which the depreciation amounts were posted to the SAP FI general ledger. May differ from the period end date in cases of late postings or period-close adjustments.',
    `regulatory_depreciation_rate` DECIMAL(18,2) COMMENT 'The PUC/FERC-approved annual depreciation rate applied to the asset for regulatory cost-of-service purposes, expressed as a decimal (e.g., 0.033333 for 3.33% straight-line over 30 years). Used in rate case depreciation expense justification and FERC Form 1 reporting.',
    `remaining_useful_life_years` DECIMAL(18,2) COMMENT 'Remaining useful life of the asset in years as of the depreciation run date, calculated as total useful life minus elapsed service life. Used in regulatory depreciation studies, IRP planning, and asset retirement obligation (ARO) calculations per FASB ASC 410.',
    `reversal_document_number` STRING COMMENT 'SAP FI accounting document number of the reversal entry if this depreciation run has been reversed. Populated only when run_status is reversed. Provides the audit trail for depreciation corrections and period-close adjustments.',
    `run_number` STRING COMMENT 'SAP FI-AA externally visible run identifier assigned by the system when the depreciation posting run is executed (e.g., DEPR-2024-001). Used as the business-facing reference number for audit trails and rate case documentation.',
    `run_status` STRING COMMENT 'Current lifecycle status of the depreciation run. planned indicates scheduled but not yet executed; test indicates a simulation run without posting; posted indicates depreciation amounts have been posted to the general ledger; reversed indicates the run has been reversed; error indicates the run failed during processing.. Valid values are `planned|test|posted|reversed|error`',
    `run_type` STRING COMMENT 'Classification of the depreciation run execution type as defined in SAP FI-AA. planned is the standard periodic run; unplanned covers out-of-cycle depreciation; repeat re-executes a prior period run; restart continues an interrupted run.. Valid values are `planned|unplanned|repeat|restart`',
    `salvage_value_amount` DECIMAL(18,2) COMMENT 'Estimated residual/salvage value of the asset at the end of its useful life, used to reduce the depreciable base. Relevant for regulatory depreciation studies and rate case justification of depreciation rates.',
    `tax_depreciation_method` STRING COMMENT 'IRS tax depreciation method applied in the federal tax depreciation area (e.g., MACRS for Modified Accelerated Cost Recovery System, ADS for Alternative Depreciation System, SL for Straight-Line). Drives deferred income tax calculations and FASB ASC 740 income tax accounting.. Valid values are `MACRS|ADS|SL|DB200|DB150|ACRS`',
    `unplanned_depreciation_amount` DECIMAL(18,2) COMMENT 'Additional unplanned (extraordinary) depreciation amount posted outside the standard periodic run, such as impairment write-downs, accelerated depreciation for regulatory purposes, or asset retirement adjustments per FASB ASC 410.',
    `useful_life_years` DECIMAL(18,2) COMMENT 'The total estimated useful life of the asset in years as configured in SAP FI-AA for this depreciation area. Drives the straight-line depreciation rate and is a key input to regulatory depreciation studies and rate case filings.',
    `wbs_element_code` STRING COMMENT 'SAP PS Work Breakdown Structure element code linking the depreciation to a capital project. Supports CAPEX tracking and project-level depreciation analysis for infrastructure investment programs.',
    CONSTRAINT pk_depreciation_run PRIMARY KEY(`depreciation_run_id`)
) COMMENT 'SAP FI-AA periodic depreciation calculation run records capturing planned and posted depreciation amounts by asset, depreciation area (book, tax, regulatory), fiscal period, and depreciation method. Supports FASB ASC 980 regulatory depreciation studies, rate case depreciation expense justification, and FERC Form 1 accumulated depreciation reporting.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`finance`.`regulatory_asset` (
    `regulatory_asset_id` BIGINT COMMENT 'Unique surrogate identifier for each regulatory asset or regulatory liability record in the FASB ASC 980 ledger. Primary key for this data product.',
    `cost_center_id` BIGINT COMMENT 'Foreign key linking to finance.cost_center. Business justification: Regulatory Asset needs direct link to Cost Center for allocation tracking.',
    `gl_account_id` BIGINT COMMENT 'Foreign key linking to finance.gl_account. Business justification: Regulatory Asset needs direct links to GL Account and Cost Center for regulatory reporting.',
    `finance_capex_project_id` BIGINT COMMENT 'Reference to the capital project in the capital project accounting system (SAP PS) that originated the costs deferred into this regulatory asset. Enables traceability from the regulatory asset balance back to the underlying CAPEX project for rate base and depreciation analysis.',
    `related_finance_capex_project_id` BIGINT COMMENT 'Reference to the capital project in the capital project accounting system (SAP PS) that originated the costs deferred into this regulatory asset. Enables traceability from the regulatory asset balance back to the underlying CAPEX project for rate base and depreciation analysis.',
    `accounting_period` STRING COMMENT 'The fiscal accounting period (YYYY-MM) to which the current balance and amortization figures apply. Used for period-end close reporting, FERC Form 1 annual filing, and SAP FI/CO period-end postings.. Valid values are `^[0-9]{4}-(0[1-9]|1[0-2])$`',
    `accrued_carrying_charges` DECIMAL(18,2) COMMENT 'The cumulative carrying charges (interest on the deferred balance) accrued on this regulatory asset or liability to date (in USD). Included in the total balance subject to recovery or refund through rates.',
    `amortization_method` STRING COMMENT 'The method prescribed by the authorizing rate order for amortizing this regulatory asset or liability. straight_line is most common; regulatory_prescribed indicates a custom schedule mandated by the regulator; units_of_production may apply to fuel-related deferrals.. Valid values are `straight_line|units_of_production|regulatory_prescribed|accelerated|other`',
    `annual_amortization_amount` DECIMAL(18,2) COMMENT 'The annual dollar amount authorized for amortization (recovery or refund) of this regulatory asset or liability through customer rates (in USD). Derived from the approved amortization schedule in the rate order. Used for budgeting and CAPEX/OPEX tracking.',
    `approved_by` STRING COMMENT 'Name or employee identifier of the finance officer or regulatory accounting manager who approved the creation or material modification of this regulatory asset record. Required for SOX Section 302/404 internal controls over financial reporting.',
    `asset_name` STRING COMMENT 'Descriptive human-readable name of the regulatory asset or liability (e.g., Deferred Storm Restoration Costs, Pension Regulatory Asset, Fuel Adjustment Clause Deferral). Used in financial statements and rate case testimony.',
    `asset_number` STRING COMMENT 'Externally-known alphanumeric identifier assigned by the finance or regulatory accounting team to uniquely reference this regulatory asset or liability in rate case filings, FERC Form 1 schedules, and SAP FI/CO postings. Serves as the business-facing key across systems.',
    `asset_type` STRING COMMENT 'Indicates whether this record represents a regulatory asset (costs deferred for future recovery from ratepayers) or a regulatory liability (obligations deferred for future refund to ratepayers) under FASB ASC 980.. Valid values are `regulatory_asset|regulatory_liability`',
    `authorization_date` DATE COMMENT 'The date on which the regulatory commission issued the rate order or decision authorizing the creation of this regulatory asset or liability. Establishes the FASB ASC 980 recognition date and the legal basis for deferral accounting.',
    `authorizing_jurisdiction` STRING COMMENT 'The regulatory jurisdiction that authorized this regulatory asset or liability — Federal Energy Regulatory Commission (FERC) for interstate transmission, state Public Utility Commission (PUC) or Public Service Commission (PSC) for distribution, or both for dual-jurisdiction items.. Valid values are `FERC|state_puc|state_psc|both`',
    `beginning_balance` DECIMAL(18,2) COMMENT 'The opening balance of the regulatory asset or liability at the start of the current accounting period (in USD). Used as the baseline for amortization calculations and period-over-period variance analysis in FERC Form 1 and rate case filings.',
    `capitalization_flag` BOOLEAN COMMENT 'Indicates whether this regulatory asset is classified as a capital expenditure (CAPEX) item on the balance sheet (True) or an operating expenditure (OPEX) deferral (False). Affects rate base inclusion, depreciation treatment, and EBITDA reporting under FASB ASC 980 and FASB ASC 360.',
    `carrying_charge_rate` DECIMAL(18,2) COMMENT 'The authorized carrying charge (interest) rate applied to the unamortized balance of this regulatory asset or liability between the deferral date and the recovery start date, expressed as a decimal (e.g., 0.060000 for 6.0%). Compensates the utility for the time value of money on deferred costs.',
    `created_timestamp` TIMESTAMP COMMENT 'The timestamp when this regulatory asset record was first created in the system (yyyy-MM-ddTHH:mm:ss.SSSXXX). Provides the audit trail creation event for SOX compliance and data lineage tracking.',
    `cumulative_amortization` DECIMAL(18,2) COMMENT 'Total amortization recognized to date against this regulatory asset or liability since its inception (in USD). Represents the portion already recovered from or refunded to ratepayers through rates. Used to reconcile the original authorized amount to the current balance.',
    `current_balance` DECIMAL(18,2) COMMENT 'The current outstanding balance of the regulatory asset or liability as of the most recent accounting period close (in USD). Represents the net unamortized amount remaining for future recovery or refund through rates. Core field for RAB valuation and EBITDA reporting.',
    `deferral_start_date` DATE COMMENT 'The date on which costs or obligations began to be deferred into this regulatory asset or liability account. May differ from the authorization date if the regulator authorized retroactive deferral. Used for amortization period calculations.',
    `disallowance_risk_flag` BOOLEAN COMMENT 'Indicates whether this regulatory asset carries a risk of partial or full disallowance by the regulator (True = at risk; False = recovery considered probable). Under FASB ASC 980, if recovery is no longer probable, the asset must be written off. Used for financial risk management and disclosure.',
    `ferc_account_number` STRING COMMENT 'The FERC Uniform System of Accounts account number to which this regulatory asset or liability is classified (e.g., Account 182.3 for Other Regulatory Assets, Account 254 for Other Regulatory Liabilities, Account 283 for Deferred Income Taxes). Required for FERC Form 1 reporting.',
    `ferc_form1_schedule` STRING COMMENT 'The specific FERC Form 1 schedule or page reference where this regulatory asset or liability is reported (e.g., Schedule 232 — Regulatory Assets, Schedule 278 — Regulatory Liabilities). Supports automated FERC Form 1 report generation.',
    `income_tax_effect` DECIMAL(18,2) COMMENT 'The deferred income tax amount associated with this regulatory asset or liability (in USD), arising from temporary differences between book and tax treatment of the deferred costs. Required for FASB ASC 740 and ASC 980 interaction disclosures and FERC Form 1 tax normalization schedules.',
    `last_regulatory_review_date` DATE COMMENT 'The date of the most recent regulatory commission review, audit, or order affecting this regulatory asset or liability. Used to track compliance with ongoing regulatory reporting obligations and to identify assets due for re-authorization.',
    `last_updated_timestamp` TIMESTAMP COMMENT 'The timestamp of the most recent modification to this regulatory asset record (yyyy-MM-ddTHH:mm:ss.SSSXXX). Used for change tracking, SOX audit compliance, and incremental data pipeline processing in the Databricks Silver Layer.',
    `next_regulatory_review_date` DATE COMMENT 'The scheduled date of the next regulatory commission review or rate case proceeding in which this regulatory asset or liability will be examined. Used for proactive regulatory compliance planning and rate case preparation.',
    `original_authorized_amount` DECIMAL(18,2) COMMENT 'The total dollar amount of costs or obligations originally authorized by the regulator for deferral and future recovery or refund (in USD). Establishes the ceiling for the regulatory asset or liability as approved in the rate order.',
    `originating_event_description` STRING COMMENT 'Narrative description of the business event or circumstance that gave rise to this regulatory asset or liability (e.g., Hurricane Ida storm restoration costs incurred Q3 2021, Pension obligation increase due to actuarial assumption change, Nuclear decommissioning cost deferral per Order No. 2023-14). Supports audit trails and rate case testimony.',
    `plant_function` STRING COMMENT 'The utility plant function to which this regulatory asset or liability is associated, used for jurisdictional allocation and rate class assignment in cost-of-service studies. Aligns with FERC functional classification for T&D separation.. Valid values are `generation|transmission|distribution|gas_distribution|general_plant|other`',
    `probability_of_recovery` STRING COMMENT 'Managements assessment of the probability that this regulatory asset will be recovered through future rates, using the FASB ASC 450 contingency framework. probable supports continued recognition; reasonably_possible or remote may trigger impairment or write-off under ASC 980.. Valid values are `probable|reasonably_possible|remote`',
    `puc_docket_number` STRING COMMENT 'The official docket or case number assigned by the state Public Utility Commission (PUC) or Public Service Commission (PSC) authorizing the deferral or recovery of this regulatory asset or liability. Essential for regulatory compliance tracking and rate case filings.',
    `rate_base_eligible` BOOLEAN COMMENT 'Indicates whether this regulatory asset is included in the Regulatory Asset Base (RAB) for rate-of-return calculations. True if the asset earns a return on investment in the rate base; False if it is a non-earning deferral. Critical for Return on Equity (ROE) and rate case calculations.',
    `rate_case_reference` STRING COMMENT 'Reference to the General Rate Case (GRC) or rate proceeding in which this regulatory asset or liability was established or most recently reviewed. Used to link financial records to the regulatory proceeding for cost-of-service study support and rate case testimony.',
    `rate_order_number` STRING COMMENT 'The specific rate order or commission order number issued by the PUC, PSC, or FERC that authorizes the creation, recovery, or refund of this regulatory asset or liability. Provides the legal basis for FASB ASC 980 recognition.',
    `recovery_end_date` DATE COMMENT 'The scheduled date on which full amortization (recovery or refund) of this regulatory asset or liability is expected to be completed. Defines the end of the authorized recovery period. Nullable for open-ended or indefinite-term regulatory assets.',
    `recovery_mechanism` STRING COMMENT 'The rate mechanism through which this regulatory asset is recovered from customers or the regulatory liability is refunded to customers. Examples include base rate inclusion, a specific rate rider, a surcharge, or a Fuel Adjustment Clause (FAC). Critical for revenue management and rate design.. Valid values are `base_rate|rider|surcharge|fuel_adjustment_clause|automatic_adjustment|other`',
    `recovery_period_years` DECIMAL(18,2) COMMENT 'The total authorized recovery or refund period in years as specified in the rate order. Used for straight-line amortization calculations and for projecting future rate impacts in Integrated Resource Plan (IRP) and rate case cost-of-service studies.',
    `recovery_start_date` DATE COMMENT 'The date on which amortization (recovery from customers or refund to customers) of this regulatory asset or liability commenced through rates. Marks the beginning of the authorized recovery period.',
    `regulatory_asset_category` STRING COMMENT 'Business classification grouping the regulatory asset into a standard category such as deferred fuel costs, storm damage costs, pension and OPEB, income taxes recoverable, environmental remediation, asset retirement obligations, or demand-side management program costs. [ENUM-REF-CANDIDATE: deferred_fuel_costs|storm_damage|pension_opeb|income_tax_recoverable|environmental_remediation|asset_retirement_obligation|demand_side_management|rate_case_costs|other — promote to reference product]',
    `regulatory_asset_status` STRING COMMENT 'Current lifecycle status of the regulatory asset or liability record. active indicates balance is being accumulated; amortizing indicates recovery or refund is in progress; fully_amortized indicates the balance has been fully recovered or refunded; pending_approval indicates awaiting regulatory authorization; suspended indicates recovery temporarily halted by order; written_off indicates disallowed by regulator.. Valid values are `active|amortizing|fully_amortized|pending_approval|suspended|written_off`',
    `return_on_equity_rate` DECIMAL(18,2) COMMENT 'The authorized Return on Equity (ROE) rate applied to this regulatory asset when it is included in the rate base. Expressed as a decimal (e.g., 0.095000 for 9.5%). Set by the authorizing rate order. Applicable only when rate_base_eligible is True.',
    `source_system` STRING COMMENT 'Identifies the operational system of record from which this regulatory asset record was sourced (e.g., SAP FI/CO for automated postings, manual_entry for regulatory accounting team adjustments). Supports data lineage and Silver Layer reconciliation.. Valid values are `SAP_FICO|manual_entry|legacy_system|other`',
    `utility_service_type` STRING COMMENT 'Identifies whether this regulatory asset or liability relates to the electric utility operations, natural gas utility operations, or both. Required for jurisdictional separation in rate case cost-of-service studies and FERC Form 1 vs. FERC Form 2 reporting.. Valid values are `electric|gas|both`',
    CONSTRAINT pk_regulatory_asset PRIMARY KEY(`regulatory_asset_id`)
) COMMENT 'FASB ASC 980 regulatory asset and regulatory liability records representing costs or obligations that regulators have authorized for future recovery or refund through rates. Tracks the regulatory asset/liability balance, amortization schedule, authorizing rate order, PUC docket reference, and recovery period. Essential for regulated utility financial reporting and rate base calculations.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`finance`.`rate_base` (
    `rate_base_id` BIGINT COMMENT 'Unique surrogate identifier for each rate base record in the regulatory asset base (RAB) calculation dataset. Primary key for the rate_base data product.',
    `regulatory_asset_id` BIGINT COMMENT 'Foreign key linking to finance.regulatory_asset. Business justification: Rate Base calculations depend on regulatory asset data; linking provides direct access.',
    `accumulated_depreciation_amt` DECIMAL(18,2) COMMENT 'Total accumulated depreciation on utility plant in service as of the test year end date. Subtracted from gross plant in service to arrive at net utility plant in the rate base calculation. Sourced from SAP FI/CO asset accounting module.',
    `adit_amt` DECIMAL(18,2) COMMENT 'Accumulated Deferred Income Taxes (ADIT) balance that reduces the rate base. ADIT represents the cumulative timing differences between book and tax depreciation, which are treated as a cost-free source of capital that offsets the rate base per IRS normalization rules and FERC/PUC requirements.',
    `afudc_rate` DECIMAL(18,2) COMMENT 'The Allowance for Funds Used During Construction (AFUDC) rate applied to Construction Work in Progress (CWIP) balances, expressed as a decimal. AFUDC represents the cost of financing capital projects during construction and is capitalized to the plant account per FERC Uniform System of Accounts.',
    `allowed_roe_rate` DECIMAL(18,2) COMMENT 'The authorized Return on Equity (ROE) rate approved by the regulatory commission for this rate case, expressed as a decimal (e.g., 0.0950 for 9.50%). Used to calculate the equity return component of the revenue requirement in cost-of-service studies.',
    `commission_approval_date` DATE COMMENT 'The date on which the regulatory commission issued its final order approving the rate base for tariff purposes. Nullable until the commission issues its decision following the rate case proceeding.',
    `cost_of_debt_rate` DECIMAL(18,2) COMMENT 'The embedded cost of long-term debt used in the capital structure for rate base return calculations, expressed as a decimal (e.g., 0.0450 for 4.50%). Calculated from the utilitys outstanding long-term debt instruments as filed with the regulatory commission.',
    `created_timestamp` TIMESTAMP COMMENT 'The timestamp when this rate base record was first created in the system, in ISO 8601 format (yyyy-MM-ddTHH:mm:ss.SSSXXX). Provides audit trail for record origination in the Databricks Silver Layer.',
    `currency_code` STRING COMMENT 'ISO 4217 three-letter currency code for all monetary amounts in this rate base record. Typically USD for U.S. utility operations. Supports multi-currency reporting for utilities with cross-border operations.. Valid values are `USD|CAD`',
    `customer_deposits_amt` DECIMAL(18,2) COMMENT 'Total customer deposit balances that reduce the rate base. Customer deposits are treated as a cost-free source of capital provided by customers, which offsets the utilitys rate base investment in cost-of-service studies.',
    `cwip_amt` DECIMAL(18,2) COMMENT 'Dollar value of capital projects currently under construction that are included in the rate base per regulatory authorization. CWIP inclusion in rate base is subject to PUC approval and AFUDC (Allowance for Funds Used During Construction) accounting treatment under FASB ASC 980.',
    `debt_ratio` DECIMAL(18,2) COMMENT 'The proportion of long-term debt in the approved or proposed capital structure used for rate base return calculations, expressed as a decimal (e.g., 0.5000 for 50%). Together with equity ratio, defines the capital structure for revenue requirement calculations.',
    `depreciation_rate` DECIMAL(18,2) COMMENT 'The composite depreciation rate applied to utility plant in service for rate base and revenue requirement calculations, expressed as a decimal. Established through a depreciation study approved by the regulatory commission.',
    `effective_date` DATE COMMENT 'The date on which the approved rate base becomes effective for tariff and rate-setting purposes. Established by commission order following a General Rate Case (GRC) proceeding.',
    `equity_ratio` DECIMAL(18,2) COMMENT 'The proportion of equity in the approved or proposed capital structure used for rate base return calculations, expressed as a decimal (e.g., 0.5000 for 50%). Determined by the regulatory commission in the rate case proceeding.',
    `expiration_date` DATE COMMENT 'The date on which the approved rate base record expires or is superseded by a new rate case determination. Nullable for open-ended rate base records that remain in effect until a new rate case is filed.',
    `ferc_account_code` STRING COMMENT 'The FERC Uniform System of Accounts code associated with the primary plant account category driving this rate base record. Used for FERC Form 1 reporting and regulatory cost allocation studies.',
    `filing_date` DATE COMMENT 'The date on which the rate base data was formally filed with the regulatory commission (PUC or FERC) as part of the rate case application. Establishes the official record date for regulatory proceedings.',
    `fuel_type_code` STRING COMMENT 'Identifies the fuel or energy source type associated with generation plant assets included in this rate base record. Used for Integrated Resource Plan (IRP) reporting, Renewable Energy Certificate (REC) tracking, and environmental compliance cost allocation.. Valid values are `fossil|nuclear|renewable|gas|hydro|other`',
    `gross_plant_in_service_amt` DECIMAL(18,2) COMMENT 'Total gross value of utility plant in service (before accumulated depreciation) included in the rate base calculation. Represents the original cost of all depreciable utility assets used and useful in providing regulated service, per FERC Uniform System of Accounts.',
    `is_cwip_included` BOOLEAN COMMENT 'Indicates whether Construction Work in Progress (CWIP) is included in the rate base (True) per regulatory authorization, or excluded (False) with AFUDC capitalized instead. CWIP inclusion requires specific PUC or FERC authorization.',
    `is_ferc_jurisdictional` BOOLEAN COMMENT 'Indicates whether this rate base record falls under FERC jurisdiction (True) for interstate transmission and wholesale power sales, or under state PUC jurisdiction (False) for retail distribution and local gas distribution. Determines applicable regulatory accounting and reporting requirements.',
    `jurisdiction_code` STRING COMMENT 'Code identifying the regulatory jurisdiction (state or federal) under which this rate base record is filed. Used to segregate rate base components by PUC or FERC jurisdiction for cost-of-service studies and rate case filings.',
    `net_utility_plant_amt` DECIMAL(18,2) COMMENT 'Net book value of utility plant in service, calculated as gross plant in service minus accumulated depreciation. Represents the primary component of the regulatory asset base (RAB) used in cost-of-service studies and Return on Equity (ROE) calculations.',
    `notes` STRING COMMENT 'Free-text field for regulatory analysts and financial planners to document material adjustments, commission-ordered modifications, stipulations, or other explanatory notes associated with this rate base record. Supports audit trail and regulatory proceeding documentation.',
    `plant_function_code` STRING COMMENT 'Functional classification of the utility plant included in this rate base record per FERC Uniform System of Accounts. Distinguishes between generation, transmission, distribution, general plant, and intangible plant for cost allocation and rate design purposes.. Valid values are `generation|transmission|distribution|general_plant|intangible`',
    `plant_in_service_date` DATE COMMENT 'The date as of which the utility plant in service balance is measured for inclusion in the rate base. Typically the last day of the test year or a specific date established by the regulatory commission for the cost-of-service study.',
    `rate_base_number` STRING COMMENT 'Externally-known business identifier for the rate base record, used in regulatory filings, cost-of-service studies, and rate case submissions to the Public Utility Commission (PUC). Typically formatted as a combination of jurisdiction code, rate class, and test year (e.g., CA-RES-2024).',
    `rate_base_status` STRING COMMENT 'Current lifecycle status of the rate base record within the regulatory filing process. Tracks progression from internal draft preparation through regulatory filing, commission approval, and potential supersession by a subsequent rate case.. Valid values are `draft|filed|approved|superseded|withdrawn`',
    `rate_case_docket_number` STRING COMMENT 'Official docket or case number assigned by the regulatory commission (PUC or FERC) to the rate case proceeding in which this rate base record is submitted. Used for regulatory tracking and cross-referencing with commission orders.',
    `rate_class_code` STRING COMMENT 'Code identifying the customer rate class (e.g., residential, commercial, industrial, agricultural) to which this rate base component is allocated. Supports cost-of-service allocation studies and rate design for General Rate Case (GRC) filings.',
    `regulatory_assets_amt` DECIMAL(18,2) COMMENT 'Total value of regulatory assets included in the rate base. Regulatory assets represent costs deferred for future recovery in rates as authorized by the PUC under FASB ASC 980, including deferred storm costs, deferred pension costs, and other commission-approved deferrals.',
    `regulatory_liabilities_amt` DECIMAL(18,2) COMMENT 'Total value of regulatory liabilities that reduce the rate base. Regulatory liabilities represent obligations to return amounts to customers in future rates, such as excess deferred income taxes from tax reform or over-collected revenues, as authorized under FASB ASC 980.',
    `return_on_rate_base_amt` DECIMAL(18,2) COMMENT 'The dollar amount of authorized return on the rate base, calculated as total rate base multiplied by the weighted average cost of capital (WACC). Represents the equity and debt return component of the revenue requirement.',
    `revenue_requirement_amt` DECIMAL(18,2) COMMENT 'The total annual revenue requirement associated with this rate base record, representing the amount the utility is authorized to collect from customers to recover its costs and earn a fair return. Calculated as return on rate base plus operating expenses plus depreciation plus taxes.',
    `sap_cost_center_code` STRING COMMENT 'The SAP FI/CO cost center code associated with this rate base record, enabling linkage to the SAP ERP general ledger for financial reconciliation and cost-of-service allocation. Sourced from SAP Controlling (CO) module.',
    `sap_wbs_element` STRING COMMENT 'The SAP Project System Work Breakdown Structure (WBS) element code associated with capital projects contributing to this rate base record. Used to track CAPEX project costs from SAP PS module through to rate base inclusion.',
    `service_territory_code` STRING COMMENT 'Code identifying the geographic service territory or operating division to which this rate base record applies. Used for multi-territory utilities to allocate rate base components by service area for cost-of-service studies.',
    `test_year` STRING COMMENT 'The calendar or fiscal year used as the basis for the rate case cost-of-service study. The test year establishes the period for which rate base, revenues, and expenses are measured to determine revenue requirements in a General Rate Case (GRC) filing.',
    `test_year_type` STRING COMMENT 'Indicates whether the test year is based on historical actuals, a projected future period, or a hybrid combination of both. Regulatory commissions may require different test year types depending on jurisdiction rules.. Valid values are `historical|projected|hybrid`',
    `total_rate_base_amt` DECIMAL(18,2) COMMENT 'Total regulatory asset base (RAB) amount, representing the net investment on which the utility is entitled to earn a return. Calculated as net utility plant plus CWIP plus working capital allowance plus regulatory assets minus regulatory liabilities minus ADIT minus customer deposits. Used as the basis for ROE and revenue requirement calculations in rate cases.',
    `updated_timestamp` TIMESTAMP COMMENT 'The timestamp when this rate base record was most recently modified, in ISO 8601 format (yyyy-MM-ddTHH:mm:ss.SSSXXX). Tracks the last update for data lineage, audit compliance, and change management in the Databricks Silver Layer.',
    `utility_type` STRING COMMENT 'Identifies whether the rate base record pertains to the electric utility operations, natural gas utility operations, or a combined electric and gas utility. Supports separate rate base tracking for electric and gas jurisdictions.. Valid values are `electric|gas|combined`',
    `weighted_avg_cost_of_capital_rate` DECIMAL(18,2) COMMENT 'The overall weighted average cost of capital (WACC) approved or proposed for this rate base, blending the cost of debt and equity weighted by their respective proportions in the capital structure. Used to calculate the total return on rate base in revenue requirement studies.',
    `working_capital_allowance_amt` DECIMAL(18,2) COMMENT 'Allowance for working capital included in the rate base, representing the utilitys investment in cash and materials needed to operate between billing cycles. Typically calculated using the lead-lag method or a fixed percentage of operating expenses as approved by the PUC.',
    CONSTRAINT pk_rate_base PRIMARY KEY(`rate_base_id`)
) COMMENT 'Regulatory rate base (RAB) calculation records supporting GRC and rate case filings. Captures the components of rate base including net utility plant, working capital allowance, regulatory assets/liabilities, accumulated deferred income taxes (ADIT), and customer deposits. Tracks rate base by jurisdiction, rate class, and test year for PUC cost-of-service studies and ROE calculations.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`finance`.`cost_allocation` (
    `cost_allocation_id` BIGINT COMMENT 'Unique surrogate identifier for each SAP CO cost allocation or assessment cycle record in the Silver Layer lakehouse. Primary key for this data product.',
    `portfolio_id` BIGINT COMMENT 'Foreign key linking to trading.trading_portfolio. Business justification: Enables Cost Allocation process to allocate costs directly to trading portfolios, required for portfolio profitability analysis.',
    `cost_center_id` BIGINT COMMENT 'Surrogate identifier referencing the cost center from which costs are being distributed (the sender/source in the SAP CO allocation). Typically represents corporate overhead, shared services, or common plant cost centers.',
    `allocated_amount` DECIMAL(18,2) COMMENT 'The gross monetary amount of cost allocated from the sender to the receiver in the company code currency. This is the primary financial fact of the allocation record, used in cost-of-service studies, CAPEX/OPEX tracking, and FERC Form 1 reporting.',
    `allocated_amount_usd` DECIMAL(18,2) COMMENT 'The allocated cost amount translated to US Dollars (USD) using the exchange rate applicable at the time of posting. Enables consistent cross-currency financial reporting and FERC Form 1 submissions which require USD denomination.',
    `allocation_basis_type` STRING COMMENT 'The method or driver used to determine the proportion of costs allocated to each receiver. Common bases include statistical key figures (e.g., kWh consumed), headcount, square footage, revenue, direct cost ratios, or fixed percentages. Critical for rate case cost-of-service justification. [ENUM-REF-CANDIDATE: statistical_key_figure|headcount|square_footage|revenue|direct_cost|fixed_percentage|machine_hours|mwh_generated — promote to reference product]. Valid values are `statistical_key_figure|headcount|square_footage|revenue|direct_cost|fixed_percentage`',
    `allocation_basis_value` DECIMAL(18,2) COMMENT 'The numeric value of the allocation driver/basis for this receiver (e.g., 1,500 kWh, 45 headcount, 2,000 square feet). Used to verify the proportional split of costs and to support rate case cost-of-service documentation.',
    `allocation_doc_number` STRING COMMENT 'The externally-known SAP CO document number uniquely identifying the allocation posting (e.g., assessment cycle run document). Serves as the business identifier traceable back to the source system.',
    `allocation_notes` STRING COMMENT 'Free-text notes or comments entered by the cost accountant or financial analyst describing the rationale for the allocation, any manual adjustments, or regulatory compliance notes. Supports audit and rate case documentation.',
    `allocation_percentage` DECIMAL(18,2) COMMENT 'The percentage of the sender cost centers total cost allocated to this specific receiver, expressed as a decimal (e.g., 0.125000 = 12.5%). Derived from the allocation basis but stored for audit and rate case transparency.',
    `allocation_run_timestamp` TIMESTAMP COMMENT 'The date and time when the SAP CO assessment or distribution cycle was executed to generate this allocation record. Distinguishes between multiple runs of the same cycle within a period (e.g., preliminary vs. final close runs).',
    `allocation_status` STRING COMMENT 'Current lifecycle status of the allocation record. posted indicates the allocation has been finalized in SAP CO; reversed indicates a reversal document exists; simulated indicates a test run not yet posted; blocked indicates held for review; error indicates a processing failure.. Valid values are `posted|reversed|simulated|blocked|error`',
    `allocation_type` STRING COMMENT 'Classification of the SAP CO allocation method used: assessment (allocates cost using statistical key figures), distribution (reallocates primary costs), indirect activity allocation, manual reposting, or settlement from internal orders/WBS elements.. Valid values are `assessment|distribution|indirect_activity|reposting|settlement`',
    `business_area_code` STRING COMMENT 'SAP FI business area code representing the organizational segment (e.g., Electric Distribution, Gas Transmission, Corporate) to which the allocated cost belongs. Supports multi-jurisdictional cost separation required by state PUC filings.',
    `capex_opex_indicator` STRING COMMENT 'Indicates whether the allocated cost is classified as Capital Expenditure (CAPEX) or Operating Expenditure (OPEX). Critical for regulatory asset base (RAB) valuation, rate case cost-of-service studies, and FERC Form 1 reporting under FASB ASC 980.. Valid values are `CAPEX|OPEX`',
    `company_code` STRING COMMENT 'SAP FI company code identifying the legal entity within which the allocation is posted. Essential for inter-company cost allocation in multi-jurisdictional utility holding structures and for FERC Form 1 entity-level reporting.',
    `controlling_area_code` STRING COMMENT 'SAP CO controlling area code that defines the organizational scope of cost management. A single controlling area may span multiple company codes in a utility holding company structure.',
    `cost_element_code` STRING COMMENT 'SAP CO cost element code representing the nature of the cost being allocated (e.g., labor, depreciation, overhead). Maps to the GL account in SAP FI and is used for cost-of-service studies in rate cases.',
    `cost_element_name` STRING COMMENT 'Human-readable description of the SAP CO cost element (e.g., Salaries and Wages, IT Infrastructure Depreciation, Fleet O&M). Supports self-service reporting without requiring a join.',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when this cost allocation record was first captured in the SAP CO system. Used for audit trail and data lineage in the Silver Layer lakehouse.',
    `currency_code` STRING COMMENT 'ISO 4217 three-letter currency code for the allocated_amount (e.g., USD). Supports multi-currency reporting for utilities operating across jurisdictions.. Valid values are `^[A-Z]{3}$`',
    `cycle_name` STRING COMMENT 'Human-readable name of the SAP CO assessment or distribution cycle (e.g., Corporate Overhead Allocation, Shared Services Assessment, Common Plant Distribution). Supports reporting and audit without requiring a join.',
    `document_date` DATE COMMENT 'The date of the originating allocation document as recorded in SAP CO. May differ from posting_date when allocations are backdated or adjusted for prior periods.',
    `fiscal_period` STRING COMMENT 'The accounting period (1–12 for monthly, or 13–16 for special periods) within the fiscal year in which this allocation was posted. Aligns with SAP FI/CO period-end close cycles.',
    `fiscal_year` STRING COMMENT 'The fiscal year (e.g., 2024) in which this cost allocation was executed. Used for period-end close, annual CAPEX/OPEX reporting, and FERC Form 1 filing alignment.',
    `functional_area_code` STRING COMMENT 'SAP CO functional area code classifying the nature of the cost (e.g., production, administration, sales, R&D). Used for income statement reporting by function and FERC Form 1 functional classification of utility costs.',
    `gl_account_code` STRING COMMENT 'The SAP FI general ledger account code to which the allocated cost is posted. Aligns with the FERC Uniform System of Accounts (e.g., Account 920 for administrative and general salaries, Account 921 for office supplies). Critical for FERC Form 1 reporting.',
    `intercompany_flag` BOOLEAN COMMENT 'Indicates whether this allocation crosses legal entity boundaries (True = inter-company allocation between affiliates in a utility holding company). Inter-company allocations require additional regulatory scrutiny under FERC affiliate transaction rules and state PUC standards.',
    `jurisdiction_code` STRING COMMENT 'Code identifying the regulatory jurisdiction (e.g., state abbreviation or FERC) to which the allocated cost is attributable. Critical for multi-jurisdictional utilities to separate costs for individual state PUC rate cases and FERC wholesale rate filings.',
    `last_updated_timestamp` TIMESTAMP COMMENT 'Timestamp of the most recent modification to this cost allocation record, including reversals, corrections, or status changes. Supports incremental data loading and change tracking in the lakehouse.',
    `posting_date` DATE COMMENT 'The date on which the cost allocation was posted to the SAP CO ledger. This is the principal business event date used for period assignment and financial reporting.',
    `rate_case_reference` STRING COMMENT 'Reference number of the General Rate Case (GRC) or FERC rate proceeding for which this allocation is being tracked. Enables direct linkage of cost allocation records to specific regulatory filings and cost-of-service studies.',
    `receiver_profit_center_code` STRING COMMENT 'SAP CO profit center code receiving the allocated costs when receiver_type is profit_center. Used for segment-level profitability reporting and inter-company allocations in multi-jurisdictional utility structures.',
    `receiver_type` STRING COMMENT 'Discriminator indicating the type of SAP CO object receiving the allocated costs: cost_center (another cost center), profit_center (a profit center for segment reporting), wbs_element (a capital project WBS element for CAPEX tracking), or internal_order.. Valid values are `cost_center|profit_center|wbs_element|internal_order`',
    `receiver_wbs_element_code` STRING COMMENT 'SAP PS Work Breakdown Structure (WBS) element code receiving allocated costs when receiver_type is wbs_element. Used for CAPEX project cost tracking, regulatory asset base (RAB) valuation, and CPCN project accounting.',
    `regulatory_asset_flag` BOOLEAN COMMENT 'Indicates whether the allocated cost contributes to a regulatory asset or liability as defined under FASB ASC 980 (Regulated Operations). True when the allocation feeds a deferred cost that is recoverable through future rates approved by the PUC or FERC.',
    `reversal_date` DATE COMMENT 'The date on which the reversal of this allocation was posted in SAP CO. Null when no reversal exists. Used for period-end close reconciliation and audit trail.',
    `reversal_doc_number` STRING COMMENT 'SAP CO document number of the reversal posting if this allocation has been reversed. Null when no reversal exists. Used for audit trail and period-end reconciliation.',
    `run_type` STRING COMMENT 'Indicates whether the allocation was executed against actual costs, planned/budget costs, or as a simulation. actual postings feed financial statements; plan allocations support budgeting and CAPEX/OPEX planning; simulation records are not posted to the ledger.. Valid values are `actual|plan|simulation`',
    `sender_total_cost` DECIMAL(18,2) COMMENT 'The total cost balance of the sender cost center prior to allocation for the fiscal period. Used to verify that the sum of all allocated_amount values equals the senders total cost, ensuring full cost recovery in the allocation cycle.',
    `utility_function` STRING COMMENT 'Classifies the allocated cost by utility function per FERC Uniform System of Accounts: generation, transmission, distribution, gas distribution, common (shared across functions), or corporate. Directly supports cost-of-service studies and rate case filings.. Valid values are `generation|transmission|distribution|gas_distribution|common|corporate`',
    CONSTRAINT pk_cost_allocation PRIMARY KEY(`cost_allocation_id`)
) COMMENT 'SAP CO cost allocation and assessment cycle records distributing shared costs (e.g., corporate overhead, shared services, common plant) from sender cost centers to receiver cost centers, profit centers, or WBS elements. Supports fully-allocated cost-of-service studies for rate cases and inter-company cost allocation for multi-jurisdictional utilities.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`finance`.`ap_invoice` (
    `ap_invoice_id` BIGINT COMMENT 'Unique surrogate identifier for the accounts payable invoice record in the Databricks Silver Layer. Primary key for this entity.',
    `bank_account_id` BIGINT COMMENT 'Reference to the company bank account from which payment was disbursed. Corresponds to the SAP house bank and account ID (HBKID/HKTID) used in the F110 payment run. Supports bank reconciliation and treasury cash position management.',
    `cost_center_id` BIGINT COMMENT 'Reference to the SAP CO cost center (KOSTL) to which the invoice expenditure is allocated. Enables OPEX tracking by organizational unit, department, or functional area for rate case cost-of-service studies and internal management reporting.',
    `facility_id` BIGINT COMMENT 'Foreign key linking to property.facility. Business justification: AP invoices for facility upgrades or maintenance need facility reference for cost allocation and audit.',
    `gl_account_id` BIGINT COMMENT 'Reference to the SAP FI general ledger account (HKONT/SAKNR) to which the invoice expense is posted. Determines FERC Uniform System of Accounts classification, CAPEX vs. OPEX treatment, and regulatory asset/liability designation under FASB ASC 980.',
    `goods_receipt_id` BIGINT COMMENT 'Reference to the SAP MM goods receipt document (MBLNR) confirming physical receipt of materials or services. Required for three-way match (PO/GR/IR) validation before invoice approval and payment release.',
    `parcel_id` BIGINT COMMENT 'Foreign key linking to property.parcel. Business justification: AP invoices for property improvements must be tied to the parcel receiving the work for cost tracking and audit.',
    `payment_run_id` BIGINT COMMENT 'Reference to the SAP F110 Automatic Payment Program batch run (identified by run date + run ID) that processed this invoice for payment. Links the invoice to the batch disbursement execution record for bank reconciliation and payment audit trail.',
    `purchase_order_id` BIGINT COMMENT 'Reference to the originating SAP MM purchase order (EBELN) against which this invoice is matched. Supports three-way match validation (PO / Goods Receipt / Invoice Receipt) for procurement controls and CAPEX/OPEX authorization.',
    `vendor_id` BIGINT COMMENT 'Reference to the vendor (supplier) master record who issued this invoice. Corresponds to the SAP vendor account (LIFNR). Covers fuel suppliers, materials vendors, contractors, equipment providers, and employee expense reimbursement accounts.',
    `wbs_element_id` BIGINT COMMENT 'Reference to the SAP PS Work Breakdown Structure element (POSID) for capital project cost assignment. Used for CAPEX tracking, regulatory asset base (RAB) valuation, and plant-in-service accounting under FERC Uniform System of Accounts.',
    `approval_status` STRING COMMENT 'Current status of the invoice in the approval workflow (SAP FI workflow or external approval system). Tracks whether the invoice has been reviewed and approved by the designated cost center owner or project manager before payment release. Supports SOX internal control compliance.. Valid values are `pending|approved|rejected|escalated`',
    `approval_timestamp` TIMESTAMP COMMENT 'The date and time when the invoice was approved for payment in the workflow system. Used for cycle time analysis (invoice receipt to approval), SLA monitoring, and SOX audit trail documentation.',
    `approved_by` STRING COMMENT 'The SAP user ID or employee identifier of the person who approved the invoice for payment. Provides audit trail for SOX compliance and internal control documentation. Null if invoice is pending approval or auto-approved within tolerance.',
    `check_ach_reference` STRING COMMENT 'The check number (for paper check payments) or ACH/EFT transaction reference number assigned by the bank or SAP payment program. Used for bank statement reconciliation, payment tracing, and stop-payment processing.',
    `company_code` STRING COMMENT 'The SAP FI company code (BUKRS) representing the legal entity or regulated utility subsidiary that owns this invoice. Supports multi-entity financial consolidation, separate regulatory filings per utility operating company, and FERC jurisdictional reporting.',
    `created_timestamp` TIMESTAMP COMMENT 'The timestamp when this AP invoice record was first created in the source system (SAP FI). Provides the audit trail creation marker for data lineage, SOX compliance, and Silver Layer ingestion tracking.',
    `currency_code` STRING COMMENT 'ISO 4217 three-letter currency code of the invoice (WAERS in SAP). Typically USD for domestic utility operations but may be foreign currency for international equipment purchases, PPA agreements with foreign counterparties, or LNG fuel procurement contracts.. Valid values are `^[A-Z]{3}$`',
    `discount_amount` DECIMAL(18,2) COMMENT 'The cash discount amount available if payment is made within the early payment discount period (SKFBT in SAP). Supports working capital optimization by identifying invoices eligible for early payment discounts (e.g., 2/10 net 30 terms).',
    `discount_due_date` DATE COMMENT 'The last date by which payment must be made to qualify for the early payment cash discount (SKFDT in SAP). Used by treasury to prioritize payments and capture available discounts for working capital optimization.',
    `due_date` DATE COMMENT 'The date by which payment must be made to the vendor to avoid late payment penalties (FAEDT in SAP). Calculated from the invoice date and payment terms. Critical for cash flow management, AP aging analysis, and avoiding late payment interest charges.',
    `exchange_rate` DECIMAL(18,2) COMMENT 'The exchange rate applied to convert the invoice currency to the companys functional currency (USD) at the time of posting (KURSF in SAP). Applicable for foreign currency invoices (e.g., international equipment, LNG procurement). Null for USD-denominated invoices.',
    `expenditure_category` STRING COMMENT 'Designates whether the invoice expenditure is capitalized (CAPEX — added to the regulatory asset base and plant-in-service) or expensed (OPEX — charged to the income statement in the current period). Critical for rate case cost-of-service studies, RAB valuation, and FERC Form 1 reporting.. Valid values are `capex|opex`',
    `ferc_account_code` STRING COMMENT 'The FERC Uniform System of Accounts (USOA) account code to which this invoice expenditure is classified (e.g., Account 501 for fuel, Account 920 for administrative salaries, Account 107 for construction work in progress). Mandatory for FERC Form 1 annual report filing and rate case cost-of-service studies.',
    `fiscal_period` STRING COMMENT 'The accounting period (MONAT, 1–16 including special periods) within the fiscal year in which the invoice is posted in SAP FI. Used for monthly close, period-end accruals, and regulatory reporting.',
    `fiscal_year` STRING COMMENT 'The fiscal year (GJAHR) in which this invoice is recorded in SAP FI. Used for annual financial reporting, FERC Form 1 submissions, rate case cost-of-service studies, and CAPEX/OPEX budget tracking.',
    `gross_amount` DECIMAL(18,2) COMMENT 'The total gross amount of the invoice before tax deductions or discounts, as stated on the vendors invoice (WRBTR in SAP). Represents the base amount for payment terms calculation, CAPEX/OPEX budget consumption, and cash flow planning.',
    `invoice_description` STRING COMMENT 'Free-text description of the goods or services invoiced, as entered in the SAP invoice header text (SGTXT). Provides context for the expenditure, supports spend analytics, and aids in dispute resolution and audit inquiries.',
    `invoice_number` STRING COMMENT 'The externally-assigned invoice document number as provided by the vendor or generated by SAP FI (BELNR field). Serves as the primary business identifier for cross-referencing with vendor remittance and payment advice documents.',
    `invoice_receipt_timestamp` TIMESTAMP COMMENT 'The date and time when the vendor invoice was received and entered into SAP (CPUDT/CPUTM in RBKP). Marks the start of the AP invoice lifecycle. Used for cycle time measurement (receipt to payment), early payment discount eligibility, and accrual management.',
    `invoice_status` STRING COMMENT 'Current workflow state of the AP invoice through its full lifecycle: received (entered into SAP), under_review (three-way match or approval in progress), approved (cleared for payment), blocked (payment block set — e.g., price variance, quantity discrepancy), paid (payment executed), cancelled (voided). Drives AP aging, cash flow forecasting, and audit trails.. Valid values are `received|under_review|approved|blocked|paid|cancelled`',
    `invoice_type` STRING COMMENT 'Classification of the invoice document type in SAP FI (BLART). Distinguishes standard vendor invoices, credit memos (vendor returns/adjustments), debit memos, recurring invoices (e.g., lease payments), prepayments, and employee expense reimbursements. Drives accounting treatment and payment processing logic.. Valid values are `standard|credit_memo|debit_memo|recurring|prepayment|expense_reimbursement`',
    `is_intercompany` BOOLEAN COMMENT 'Indicates whether this invoice represents a transaction between two legal entities within the same utility holding company group (e.g., shared services charges, intercompany fuel transfers, corporate allocations). True = intercompany invoice requiring elimination in consolidated financial statements.',
    `is_recurring` BOOLEAN COMMENT 'Indicates whether this invoice is part of a recurring payment schedule (e.g., monthly lease payments, standing purchase orders for O&M services, recurring software subscriptions). True = recurring invoice generated from an SAP recurring document template. Supports cash flow forecasting and accrual automation.',
    `last_updated_timestamp` TIMESTAMP COMMENT 'The timestamp of the most recent modification to this AP invoice record in the source system. Tracks changes such as payment block updates, approval status changes, or payment clearing. Used for incremental data pipeline processing and audit trail.',
    `net_amount` DECIMAL(18,2) COMMENT 'The net payable amount after tax and any applicable discounts (gross_amount minus discounts, plus tax where applicable). Represents the actual cash outflow obligation to the vendor. Used for payment execution, cash flow management, and bank reconciliation.',
    `payment_block_code` STRING COMMENT 'SAP payment block indicator (ZLSPR) that prevents the invoice from being selected in the automatic payment program run. Common block reasons: price variance exceeds tolerance, quantity discrepancy, missing goods receipt, manual hold pending approval, disputed invoice. Null if no block is set. [ENUM-REF-CANDIDATE: price_variance|quantity_discrepancy|missing_gr|manual_hold|disputed|duplicate_check — promote to reference product]',
    `payment_date` DATE COMMENT 'The date on which payment was executed and the invoice was cleared in SAP FI (AUGDT). Used for cash flow reporting, bank reconciliation, days payable outstanding (DPO) calculation, and FERC Form 1 cash disbursement reporting.',
    `payment_document_number` STRING COMMENT 'The SAP FI accounting document number generated upon payment execution (clearing document AUGBL). Used to link the open AP invoice item to its clearing payment entry in the general ledger for bank reconciliation and audit trail.',
    `payment_method` STRING COMMENT 'The method used to disburse payment to the vendor (ZLSCH in SAP Automatic Payment Program): ACH (Automated Clearing House electronic transfer), check (paper check), wire (domestic/international wire transfer), virtual_card (single-use virtual procurement card), eft (electronic funds transfer). Drives bank reconciliation and payment run configuration.. Valid values are `ach|check|wire|virtual_card|eft`',
    `payment_terms_code` STRING COMMENT 'The SAP payment terms key (ZTERM) defining the payment due date calculation, early payment discount periods, and installment schedules (e.g., NT30 = net 30 days, 2/10NT30 = 2% discount if paid within 10 days, net 30). Drives due date calculation and cash flow forecasting.',
    `posting_date` DATE COMMENT 'The date on which the invoice was posted to the SAP general ledger (BUDAT). Determines the fiscal period and year for CAPEX/OPEX recognition, regulatory asset accounting under FASB ASC 980, and FERC Form 1 period reporting.',
    `procurement_category` STRING COMMENT 'Business category of goods or services procured, aligned to the utilitys spend taxonomy: fuel procurement (coal, gas, nuclear fuel), T&D materials, contractor/construction services, equipment purchases, IT services, professional services, O&M supplies, etc. Supports spend analytics, supplier management, and regulatory cost allocation. [ENUM-REF-CANDIDATE: fuel|materials|contractor_services|equipment|it_services|professional_services|om_supplies|employee_expense — promote to reference product]',
    `sap_document_number` STRING COMMENT 'The internal SAP FI accounting document number (BELNR) assigned upon invoice posting in the general ledger. Used for reconciliation between the AP subledger and the general ledger in SAP FI/CO.',
    `tax_amount` DECIMAL(18,2) COMMENT 'The total tax amount (sales tax, use tax, VAT) calculated on the invoice (WMWST in SAP). Tracked separately for tax compliance reporting, recoverable vs. non-recoverable tax treatment, and regulatory cost allocation in rate cases.',
    `tax_code` STRING COMMENT 'The SAP tax code (MWSKZ) applied to the invoice for sales/use tax calculation. Determines the applicable tax rate, tax jurisdiction, and whether the tax is recoverable or non-recoverable. Relevant for state and local tax compliance in utility operations.',
    `three_way_match_status` STRING COMMENT 'Result of the three-way match validation between the Purchase Order (PO), Goods Receipt (GR), and Invoice Receipt (IR) in SAP MM/FI. Indicates whether the invoice quantity and price align within tolerance to the PO and GR. Drives automatic payment release or block assignment. not_applicable for non-PO invoices (e.g., utilities, rent, employee expenses).. Valid values are `matched|price_variance|quantity_variance|missing_gr|not_applicable`',
    `vendor_invoice_date` DATE COMMENT 'The date printed on the vendors invoice document (BLDAT in SAP). Represents the principal real-world business event date — when the vendor issued the invoice. Used for payment terms calculation and aging analysis.',
    CONSTRAINT pk_ap_invoice PRIMARY KEY(`ap_invoice_id`)
) COMMENT 'Accounts payable full lifecycle record covering vendor invoice receipt, validation (three-way match with PO/GR/IR), approval, payment execution, and batch payment run processing. Tracks invoice details (vendor, amount, tax, payment terms, due date), payment processing (payment method, payment date, bank account, check/ACH reference, batch payment run parameters), and settlement status. Covers fuel procurement, materials, contractor services, equipment purchases, and employee expense reimbursements. Includes automatic payment program run records for batch disbursement execution. Supports OPEX/CAPEX expenditure tracking, cash flow management, and bank reconciliation.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`finance`.`ar_transaction` (
    `ar_transaction_id` BIGINT COMMENT 'Unique surrogate identifier for each accounts receivable transaction record in the finance domain. Primary key for the ar_transaction data product.',
    `large_customer_contract_id` BIGINT COMMENT 'Reference to the underlying commercial contract, Power Purchase Agreement (PPA), transmission service agreement, or inter-company agreement that governs this AR transaction. Links to the contract master for terms and pricing validation.',
    `cost_center_id` BIGINT COMMENT 'Reference to the SAP CO cost center responsible for the revenue stream associated with this AR transaction. Used for internal cost-of-service allocation and rate case studies.',
    `counterparty_id` BIGINT COMMENT 'Reference to the counterparty (customer, wholesale buyer, inter-company entity, or transmission service customer) that owes the receivable. Maps to the SAP FI-AR customer account (KUNNR) for non-retail revenue streams including wholesale energy, REC sales, and FERC-jurisdictional wheeling charges.',
    `facility_id` BIGINT COMMENT 'Foreign key linking to property.facility. Business justification: Revenue from customers served by a specific facility is tracked per facility for performance reporting.',
    `gl_account_id` BIGINT COMMENT 'Reference to the general ledger account to which this AR transaction is posted. Determines the revenue or receivable classification in the chart of accounts for FERC Form 1 reporting and FASB ASC 980 regulatory accounting.',
    `parcel_id` BIGINT COMMENT 'Foreign key linking to property.parcel. Business justification: Revenue transactions are associated with service parcels to support revenue analysis and rate‑case filings.',
    `adjustment_amount` DECIMAL(18,2) COMMENT 'Net value of credits, discounts, or billing corrections applied to this AR transaction after initial invoicing. Negative values represent credits issued to the counterparty; positive values represent additional charges. Supports dispute resolution and revenue true-up processes.',
    `aging_bucket` STRING COMMENT 'Aging classification of the outstanding AR balance based on the number of days past the due date. Used for bad debt provisioning, collection prioritization, and AR aging reports required for FERC Form 1 and internal financial reporting.. Valid values are `current|1_30_days|31_60_days|61_90_days|91_120_days|over_120_days`',
    `business_unit_code` STRING COMMENT 'SAP organizational unit code identifying the business unit (e.g., Electric Transmission, Gas Distribution, Generation) responsible for the revenue stream associated with this AR transaction. Used for segment reporting and FERC Form 1 functional classification.',
    `clearing_document_number` STRING COMMENT 'SAP FI-AR clearing document number assigned when this AR transaction is fully or partially settled against an incoming payment. Enables reconciliation between the AR open item and the corresponding bank receipt or inter-company settlement.',
    `contract_reference_number` STRING COMMENT 'External contract or agreement reference number (e.g., PPA number, transmission service agreement number, FERC tariff rate schedule reference) associated with this AR transaction. Used for counterparty reconciliation without requiring a join to the contract master.',
    `counterparty_type` STRING COMMENT 'Classification of the counterparty category for this AR transaction. Distinguishes wholesale energy buyers, inter-company entities, RTO/ISO settlement parties, transmission service customers, REC buyers, and miscellaneous non-retail receivables. Drives reporting segmentation for FERC Form 1 and rate case cost-of-service studies.. Valid values are `wholesale_buyer|intercompany|rto_iso|transmission_customer|rec_buyer|miscellaneous`',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when this AR transaction record was first created in the system of record (SAP FI-AR). Used for audit trail and data lineage tracking.',
    `currency_code` STRING COMMENT 'ISO 4217 three-letter currency code for all monetary amounts on this AR transaction (e.g., USD for US Dollar). Supports multi-currency reporting for cross-border wholesale energy transactions and PPA settlements.. Valid values are `^[A-Z]{3}$`',
    `days_past_due` STRING COMMENT 'Number of calendar days elapsed since the payment due date for overdue AR transactions. Zero or negative values indicate the transaction is current. Used for collection escalation triggers and bad debt reserve calculations.',
    `dispute_flag` BOOLEAN COMMENT 'Indicates whether the counterparty has formally disputed this AR transaction. True = active dispute in progress; False = no dispute. Triggers dispute management workflow and suspends dunning activity in SAP FI-AR.',
    `dispute_reason` STRING COMMENT 'Categorized reason code for the counterparty dispute on this AR transaction. Used for dispute root cause analysis and resolution tracking. [ENUM-REF-CANDIDATE: billing_error|quantity_dispute|price_dispute|service_not_rendered|contract_terms|duplicate_invoice|other — promote to reference product]',
    `due_date` DATE COMMENT 'Contractual date by which the counterparty is required to remit payment for this AR transaction. Basis for aging bucket assignment, overdue status determination, and late payment interest calculations per contract terms.',
    `dunning_date` DATE COMMENT 'Date on which the most recent dunning (collection notice) was issued to the counterparty for this AR transaction. Used to enforce dunning intervals and track collection activity history.',
    `dunning_level` STRING COMMENT 'Current dunning (collection notice) level assigned to this AR transaction in SAP FI-AR, ranging from 0 (no dunning) to the maximum configured level. Higher levels indicate escalating collection actions. Used to track collection effort intensity.',
    `energy_volume_mwh` DECIMAL(18,2) COMMENT 'Quantity of electrical energy in Megawatt-Hours (MWh) associated with this AR transaction for wholesale energy sales, RTO/ISO settlements, or PPA deliveries. Null for non-energy revenue streams such as REC sales or inter-company charges.',
    `ferc_account_code` STRING COMMENT 'FERC Uniform System of Accounts code applicable to this AR transaction for regulatory financial reporting. Required for FERC Form 1 electric and gas revenue classification (e.g., Account 440 – Sales of Electricity, Account 456 – Other Electric Revenues).',
    `fiscal_period` STRING COMMENT 'Fiscal accounting period (1–12 for monthly, or 1–4 for quarterly) within the fiscal year in which this AR transaction is posted. Aligns with SAP FI posting period (MONAT) for period-end close and regulatory reporting.',
    `fiscal_year` STRING COMMENT 'Fiscal year in which this AR transaction is recognized for financial reporting purposes. Used for period-end close, FERC Form 1 annual reporting, and EBITDA analysis. Aligns with the SAP FI posting period (GJAHR).',
    `intercompany_flag` BOOLEAN COMMENT 'Indicates whether this AR transaction represents an inter-company charge between affiliated entities within the utility holding company structure. True = inter-company; False = third-party. Required for inter-company elimination in consolidated financial statements.',
    `invoice_amount` DECIMAL(18,2) COMMENT 'Gross billed amount on the AR invoice before any adjustments, credits, or taxes. Represents the total amount owed by the counterparty at the time of invoice issuance. Denominated in the currency specified by currency_code.',
    `invoice_number` STRING COMMENT 'Externally-known invoice document number assigned to this AR transaction, used for counterparty reconciliation and audit trail. Corresponds to the SAP FI-AR document number (BELNR) for non-retail receivables such as wholesale energy sales, FERC wheeling charges, and inter-company settlements.',
    `lmp_price` DECIMAL(18,2) COMMENT 'Locational Marginal Price (LMP) in $/MWh used to value wholesale energy transactions settled through the RTO/ISO Day-Ahead Market (DAM) or Real-Time Market (RTM). Sourced from the applicable RTO/ISO settlement statement.',
    `net_amount` DECIMAL(18,2) COMMENT 'Net receivable amount after applying all adjustments and taxes to the invoice amount (invoice_amount + tax_amount + adjustment_amount). Represents the actual amount expected to be collected from the counterparty. Used for aging analysis and collection reporting.',
    `outstanding_balance` DECIMAL(18,2) COMMENT 'Remaining unpaid balance on this AR transaction (net_amount minus paid_amount). Represents the current exposure for collection management and bad debt provisioning. Refreshed upon each payment or adjustment posting.',
    `paid_amount` DECIMAL(18,2) COMMENT 'Cumulative amount received from the counterparty against this AR transaction to date. Used to calculate the outstanding balance and determine partial payment status. Updated upon each payment posting in SAP FI-AR.',
    `payment_date` DATE COMMENT 'Date on which full or final payment was received and posted for this AR transaction. Null if the transaction remains open or partially paid. Used for cash flow reporting and days sales outstanding (DSO) analysis.',
    `payment_terms_code` STRING COMMENT 'SAP payment terms key (e.g., NT30, NT45, NT60) defining the contractual payment schedule, discount periods, and due date calculation rules for this AR transaction. Drives automated due date computation in SAP FI-AR.',
    `rate_case_reference` STRING COMMENT 'Reference to the applicable General Rate Case (GRC) or FERC rate case docket number under which the revenue rate for this AR transaction was authorized. Used for cost-of-service study support and regulatory compliance documentation.',
    `rec_quantity` DECIMAL(18,2) COMMENT 'Number of Renewable Energy Certificates (RECs) sold and invoiced in this AR transaction. One REC represents one MWh of electricity generated from a qualifying renewable source. Applicable only to REC sales revenue streams.',
    `regulatory_asset_flag` BOOLEAN COMMENT 'Indicates whether this AR transaction is associated with a FERC or state PUC-approved regulatory asset or deferred revenue mechanism under FASB ASC 980. True = subject to regulatory accounting treatment; False = standard commercial receivable.',
    `revenue_category` STRING COMMENT 'Business classification of the revenue type driving this AR transaction. Supports segmented revenue reporting for FERC Form 1, rate case cost-of-service studies, and EBITDA analysis. [ENUM-REF-CANDIDATE: wholesale_energy_sales|transmission_wheeling|rec_sales|intercompany_charge|ppa_settlement|ancillary_services|miscellaneous — promote to reference product]',
    `service_period_end` DATE COMMENT 'End date of the billing period or service delivery period covered by this AR transaction. Paired with service_period_start to define the revenue recognition window under FASB ASC 606.',
    `service_period_start` DATE COMMENT 'Start date of the billing period or service delivery period covered by this AR transaction. For wholesale energy sales, this is the start of the energy delivery interval. For transmission wheeling, it is the start of the reservation period. Required for revenue recognition under FASB ASC 606.',
    `tax_amount` DECIMAL(18,2) COMMENT 'Total tax charges applied to this AR transaction, including applicable state and federal taxes on wholesale energy sales or transmission services. Part of the monetary triplet supporting net amount calculation.',
    `transaction_date` DATE COMMENT 'The principal business event date on which the AR transaction was originated — i.e., the date the revenue was earned or the invoice was issued. Used as the basis for aging calculations and revenue recognition under FASB ASC 606.',
    `transaction_status` STRING COMMENT 'Current lifecycle state of the AR transaction indicating collection progress. Open = unpaid and within terms; partially_paid = partial payment received; paid = fully settled; overdue = past due date; disputed = counterparty has raised a formal dispute; written_off = deemed uncollectible and removed from active AR.. Valid values are `open|partially_paid|paid|overdue|disputed|written_off`',
    `transmission_zone` STRING COMMENT 'RTO/ISO transmission pricing zone or load zone associated with this AR transaction for wheeling charges and transmission service revenues. Used for FERC-jurisdictional revenue allocation and FERC Form 1 reporting.',
    `updated_timestamp` TIMESTAMP COMMENT 'Timestamp of the most recent modification to this AR transaction record, including status changes, payment postings, dispute updates, or write-off actions. Supports change data capture in the Databricks Silver layer.',
    `write_off_amount` DECIMAL(18,2) COMMENT 'Amount written off as uncollectible for this AR transaction. May be less than the full outstanding balance if a partial write-off was applied. Used for bad debt reserve reconciliation and FERC Form 1 reporting.',
    `write_off_date` DATE COMMENT 'Date on which this AR transaction was written off as uncollectible and the bad debt expense was recognized. Null if the transaction has not been written off. Required for FASB ASC 310 impairment disclosure.',
    `write_off_flag` BOOLEAN COMMENT 'Indicates whether this AR transaction has been written off as uncollectible. True = written off and removed from active AR; False = still active. Triggers bad debt expense recognition under FASB ASC 310-10.',
    CONSTRAINT pk_ar_transaction PRIMARY KEY(`ar_transaction_id`)
) COMMENT 'Accounts receivable transaction records for non-retail-billing receivables including inter-company charges, wholesale energy sales settlements, REC sales proceeds, transmission service revenues, FERC-jurisdictional wheeling charges, and miscellaneous revenue. Tracks counterparty, invoice amount, due date, collection status, aging bucket, and write-off history. Complements the billing domains customer AR for non-retail revenue streams.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`finance`.`payment_run` (
    `payment_run_id` BIGINT COMMENT 'Unique surrogate identifier for each SAP FI automatic payment program run record in the Silver Layer lakehouse. Primary key for this entity.',
    `approved_by_user_employee_id` BIGINT COMMENT 'SAP user ID of the supervisor or treasury manager who approved the payment proposal before posting. Enforces dual-control requirements for disbursements above threshold amounts per internal controls policy.',
    `bank_account_id` BIGINT COMMENT 'SAP FI bank account identifier (account ID within the house bank) from which disbursements are made. Identifies the specific checking or disbursement account used for this payment run. Classified confidential due to financial account sensitivity.',
    `cost_center_id` BIGINT COMMENT 'Reference to the primary SAP CO cost center associated with this payment run, used for OPEX allocation and cost-of-service studies. Relevant for payment runs covering operational expenditures such as fuel procurement, O&M vendor payments, and workforce expenses.',
    `employee_id` BIGINT COMMENT 'SAP user ID of the AP/treasury staff member who initiated (scheduled or executed) the payment run in SAP F110. Required for segregation-of-duties controls and SOX audit trail.',
    `gl_account_id` BIGINT COMMENT 'Reference to the primary GL clearing account used for this payment runs disbursements (e.g., bank clearing account, outgoing payment account). Supports general ledger reconciliation and FERC account mapping.',
    `house_bank_bank_account_id` BIGINT COMMENT 'SAP FI house bank identifier representing the utilitys internal bank master record from which payments are disbursed. Links to the specific bank account used for this payment run, supporting bank reconciliation and cash position reporting.. Valid values are `^[A-Z0-9]{1,5}$`',
    `portfolio_id` BIGINT COMMENT 'Foreign key linking to trading.trading_portfolio. Business justification: Supports Payment Run Settlement Report linking payments to the trading portfolio that generated the settlement obligations.',
    `reversed_run_payment_run_id` BIGINT COMMENT 'Reference to the original payment_run_id that this run reverses, if reversal_flag is True. Enables traceability between reversal runs and their originating payment runs for audit and reconciliation purposes.',
    `approval_timestamp` TIMESTAMP COMMENT 'Date and time when the payment proposal was approved by the authorized approver. Supports segregation-of-duties audit trail and turnaround time analysis for AP processing efficiency.',
    `bank_account_number_masked` STRING COMMENT 'Masked representation of the utilitys disbursement bank account number, showing only the last four digits for identification and reconciliation purposes without exposing the full account number. Used in audit reports and bank reconciliation statements.. Valid values are `^[X*]{4,12}[0-9]{4}$`',
    `bank_file_generated_flag` BOOLEAN COMMENT 'Indicates whether the payment medium file (e.g., ACH NACHA file, SWIFT MT103, check print file) was successfully generated and transmitted to the bank for this payment run. False indicates a file generation failure requiring investigation.',
    `bank_file_transmission_timestamp` TIMESTAMP COMMENT 'Date and time when the payment medium file was transmitted to the bank or payment processor. Used for bank reconciliation cutoff determination and exception investigation when payments are not reflected in bank statements.',
    `bank_routing_number` STRING COMMENT 'American Bankers Association (ABA) routing transit number of the utilitys disbursement bank. Required for ACH and wire payment file generation and bank reconciliation. Nine-digit numeric code.. Valid values are `^[0-9]{9}$`',
    `capex_opex_indicator` STRING COMMENT 'Indicates whether the disbursements in this payment run are classified as capital expenditures (CAPEX), operating expenditures (OPEX), or a mix of both. Critical for regulatory asset base (RAB) valuation, rate case cost-of-service studies, and FERC Form 1 plant account reporting.. Valid values are `CAPEX|OPEX|MIXED`',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when this payment run record was first captured in the Silver Layer lakehouse. Supports data lineage, audit trail, and record management.',
    `currency_code` STRING COMMENT 'ISO 4217 three-letter currency code for all monetary amounts in this payment run (e.g., USD). Utility operations are predominantly USD; this field supports multi-currency scenarios for cross-border energy trading settlements or foreign vendor payments.. Valid values are `^[A-Z]{3}$`',
    `discount_amount` DECIMAL(18,2) COMMENT 'Total cash discount amount captured across all payment documents in this run, representing early payment discounts (e.g., 2/10 net 30 terms) taken from vendor invoices. Reduces the net payment amount and is posted to a discount revenue GL account.',
    `docs_entered_up_to_date` DATE COMMENT 'SAP F110 parameter specifying the latest document entry date for invoices to be considered in this payment run. Ensures only invoices entered into SAP by this cutoff date are included, supporting period-close controls.',
    `document_count` STRING COMMENT 'Total number of individual payment documents (FI payment postings) generated by this payment run. Each document represents a payment to a single vendor or employee. Used for run validation, exception monitoring, and audit completeness checks.',
    `exception_count` STRING COMMENT 'Number of vendor invoices or payment items that were excluded from this payment run due to exceptions (e.g., payment block, missing bank details, duplicate invoice flag, credit hold). Drives AP exception resolution workflow.',
    `ferc_account_code` STRING COMMENT 'FERC Uniform System of Accounts code associated with the primary expenditure category of this payment run (e.g., Account 920 for administrative salaries, Account 151 for fuel stock). Supports FERC Form 1 regulatory reporting and rate case cost allocation.',
    `fiscal_period` STRING COMMENT 'SAP FI fiscal period (1–12 for monthly, or 1–13 for 13-period calendars) within the fiscal year in which this payment run is posted. Supports period-close cash disbursement reporting and budget-to-actual variance analysis.',
    `fiscal_year` STRING COMMENT 'SAP FI fiscal year in which this payment runs disbursements are recorded. Used for annual financial reporting, FERC Form 1 filing, and CAPEX/OPEX budget variance analysis.',
    `gross_payment_amount` DECIMAL(18,2) COMMENT 'Total gross disbursement amount for all payment documents included in this payment run before application of discounts or deductions. Represents the sum of all vendor invoice and expense reimbursement amounts selected for payment. Used for cash flow forecasting and bank reconciliation.',
    `invoice_count` STRING COMMENT 'Total number of vendor invoices and expense reimbursement line items cleared (paid) by this payment run. A single payment document may clear multiple invoices; this count reflects the total open items settled.',
    `last_updated_timestamp` TIMESTAMP COMMENT 'Timestamp of the most recent modification to this payment run record in the Silver Layer. Tracks status changes, corrections, and reversals for audit and data quality monitoring.',
    `net_payment_amount` DECIMAL(18,2) COMMENT 'Net total amount actually disbursed in this payment run after deducting cash discounts and other adjustments from the gross payment amount. This is the actual cash outflow recorded in the treasury cash position and bank statement.',
    `next_payment_date` DATE COMMENT 'The next payment date parameter used in the SAP F110 payment proposal to determine which open invoices are due for payment. Invoices with a due date on or before this date are selected for inclusion in the run.',
    `notes` STRING COMMENT 'Free-text notes entered by the AP/treasury team describing special circumstances, exceptions, or instructions for this payment run (e.g., Emergency payment for critical grid equipment supplier, Held pending PO approval). Supports operational communication and audit documentation.',
    `paying_company_code` STRING COMMENT 'SAP FI company code of the legal entity initiating the payment run. For a utility with multiple regulated subsidiaries (electric vs. gas), this identifies which legal entitys bank account and chart of accounts are used. Aligns with FERC jurisdictional entity reporting.. Valid values are `^[A-Z0-9]{4}$`',
    `payment_method_code` STRING COMMENT 'SAP FI payment method code indicating the instrument used to disburse funds (e.g., ACH for Automated Clearing House, CHECK for paper check, WIRE for wire transfer, EFT for electronic funds transfer). Drives bank file format generation and clearing account determination.. Valid values are `ACH|CHECK|WIRE|EFT|CARD|DRAFT`',
    `payment_posted_timestamp` TIMESTAMP COMMENT 'Date and time when the payment documents were posted in SAP FI, creating the actual accounting entries and clearing the open vendor items. This is the principal business event timestamp for the payment run lifecycle.',
    `payment_program_variant` STRING COMMENT 'SAP FI F110 program variant name that defines the selection parameters for this payment run (e.g., company codes, payment methods, next payment date, vendor selection criteria). Stored for audit traceability and run reproducibility.',
    `payment_run_category` STRING COMMENT 'Business category of the payables being settled in this run. Distinguishes vendor invoice payments (CAPEX/OPEX procurement), employee expense reimbursements, intercompany settlements, tax remittances, and regulatory fee payments (e.g., FERC filing fees, PUC assessments).. Valid values are `vendor_invoice|employee_expense|intercompany|tax_payment|regulatory_fee`',
    `payment_run_type` STRING COMMENT 'Classification of the payment run by its business purpose. regular denotes scheduled weekly/bi-weekly AP runs; off_cycle denotes ad-hoc runs outside the standard schedule; emergency denotes urgent disbursements; reversal denotes runs created to reverse prior payments.. Valid values are `regular|off_cycle|emergency|manual|reversal`',
    `posting_date` DATE COMMENT 'SAP FI accounting posting date for the payment documents generated by this run. Determines the fiscal period in which the cash disbursement is recorded in the general ledger. May differ from run_date for period-end processing.',
    `proposal_created_timestamp` TIMESTAMP COMMENT 'Date and time when the SAP F110 payment proposal was generated. The proposal lists all invoices selected for payment before final posting. Supports audit trail and approval workflow timing.',
    `reversal_flag` BOOLEAN COMMENT 'Indicates whether this payment run has been reversed (voided) in SAP FI. A reversal cancels the original payment postings and reopens the cleared vendor invoices. Critical for bank reconciliation and fraud detection.',
    `run_date` DATE COMMENT 'The calendar date on which the SAP FI automatic payment program (F110) was executed. This is the principal business event date used for treasury cash management, bank reconciliation, and period-close reporting.',
    `run_identification_key` STRING COMMENT 'SAP FI run identification key (Identification field in F110) that, together with run_date, uniquely identifies the payment run within SAP. Typically a short alphanumeric code assigned by the AP/treasury team (e.g., AP01, WIRE1).. Valid values are `^[A-Z0-9]{1,10}$`',
    `run_number` STRING COMMENT 'Externally-known SAP FI payment run identifier, typically composed of the run date and run identification key (e.g., 20240115-AP01). Used for cross-system reconciliation and audit trail references.',
    `run_status` STRING COMMENT 'Current lifecycle status of the payment run, tracking progression from scheduling through proposal creation, approval, posting, and completion. Supports treasury workflow monitoring and exception management. [ENUM-REF-CANDIDATE: scheduled|proposal_created|proposal_approved|payment_posted|payment_completed|cancelled|error — promote to reference product]',
    `utility_type` STRING COMMENT 'Identifies whether this payment run relates to the electric utility operations, gas utility operations, or combined operations. Supports jurisdictional cost separation required for separate electric and gas rate cases filed with state PUCs and FERC.. Valid values are `electric|gas|combined|other`',
    `value_date` DATE COMMENT 'Bank value date (settlement date) on which funds are expected to be debited from the utilitys bank account. Used for cash position management and bank reconciliation. For ACH, typically one business day after run_date; for wire, same day.',
    `vendor_count` STRING COMMENT 'Number of distinct vendors (and/or employees for expense reimbursements) included in this payment run. Used for payment run sizing analysis, bank file validation, and AP workload reporting.',
    CONSTRAINT pk_payment_run PRIMARY KEY(`payment_run_id`)
) COMMENT 'SAP FI automatic payment program run records capturing batch payment executions for vendor invoices and employee expense reimbursements. Tracks payment run date, payment method (ACH, check, wire), total payment amount, bank account, and individual payment documents generated. Supports treasury cash management and bank reconciliation.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`finance`.`financial_statement` (
    `financial_statement_id` BIGINT COMMENT 'Unique surrogate identifier for each financial statement record in the lakehouse silver layer. Primary key for this entity.',
    `approval_date` DATE COMMENT 'The date on which this financial statement was formally approved by management or the board of directors. Marks the transition from under_review to approved status and is required for SOX audit trail documentation.',
    `auditor_opinion_type` STRING COMMENT 'The type of independent auditor opinion issued on this financial statement: unqualified (clean opinion), qualified (with exceptions), adverse (materially misstated), disclaimer (auditor unable to form opinion), or not_yet_audited (interim statements). Required for SEC annual filings and FERC Form 1.. Valid values are `unqualified|qualified|adverse|disclaimer|not_yet_audited`',
    `capex_amt` DECIMAL(18,2) COMMENT 'Total capital expenditures for the reporting period as reported in the statement of cash flows (investing activities). Includes additions to utility plant in service, Construction Work in Progress (CWIP), and capital project spending. Critical for CAPEX tracking against approved capital budgets and rate case plant additions.',
    `comparative_period_flag` BOOLEAN COMMENT 'Indicates whether this statement record represents a comparative prior-period presentation (True) or the current reporting period (False). GAAP and FERC require prior-period comparatives in annual filings; this flag enables correct pairing of current and comparative records.',
    `consolidation_type` STRING COMMENT 'Indicates whether the statement presents consolidated financials (all subsidiaries included with intercompany eliminations), standalone entity financials, combined financials (multiple entities without full consolidation), or a business segment view. Critical for multi-entity utility holding company structures.. Valid values are `consolidated|standalone|combined|segment`',
    `created_timestamp` TIMESTAMP COMMENT 'The timestamp when this financial statement record was first created in the lakehouse silver layer. Supports audit trail, data lineage tracking, and SOX internal control documentation.',
    `currency_code` STRING COMMENT 'ISO 4217 three-letter currency code for all monetary amounts reported in this financial statement (e.g., USD). Supports multi-currency reporting for utilities with international operations or cross-border energy trading activities.. Valid values are `^[A-Z]{3}$`',
    `depreciation_amortization_amt` DECIMAL(18,2) COMMENT 'Total depreciation and amortization expense for the reporting period as reported on the income statement. Includes depreciation of utility plant in service and amortization of regulatory assets. Critical component of EBITDA calculation and rate case depreciation studies.',
    `ebitda_amt` DECIMAL(18,2) COMMENT 'Earnings Before Interest, Taxes, Depreciation, and Amortization (EBITDA) for the reporting period. Derived from operating income plus depreciation and amortization. Key performance metric for management reporting, board presentations, and credit rating agency analysis.',
    `ferc_form_number` STRING COMMENT 'Identifies the FERC annual report form associated with this financial statement filing: Form 1 (major electric utilities), Form 2 (major natural gas companies), Form 3 (non-major natural gas companies), Form 6 (oil pipeline companies), Form 60 (centralized service companies). Null for non-FERC filings.. Valid values are `Form 1|Form 2|Form 3|Form 6|Form 60`',
    `filing_date` DATE COMMENT 'The date on which this financial statement was filed with the applicable regulatory body (FERC, state PUC, or SEC). Used to confirm compliance with statutory filing deadlines (e.g., FERC Form 1 due April 18, SEC Form 10-K due 60/75/90 days after fiscal year end).',
    `fiscal_period` STRING COMMENT 'The fiscal period (month number 1–12) within the fiscal year for interim statements. Null for annual statements. Supports monthly and quarterly management reporting cycles.',
    `fiscal_quarter` STRING COMMENT 'The fiscal quarter (1–4) to which this statement pertains. Populated for quarterly filings (e.g., SEC Form 10-Q). Null for monthly or annual statements.',
    `fiscal_year` STRING COMMENT 'The fiscal year to which this financial statement pertains (e.g., 2024). For utilities, the fiscal year typically aligns with the calendar year per FERC reporting requirements.',
    `income_tax_expense_amt` DECIMAL(18,2) COMMENT 'Total income tax expense (current and deferred) for the reporting period. Includes Accumulated Deferred Income Taxes (ADIT) movements relevant to rate base calculations under FASB ASC 980 regulatory accounting.',
    `interest_expense_amt` DECIMAL(18,2) COMMENT 'Total interest and debt service expense for the reporting period, including interest on long-term debt, short-term borrowings, and Allowance for Funds Used During Construction (AFUDC) offsets. Used in EBITDA reconciliation and Weighted Average Cost of Capital (WACC) calculations.',
    `jurisdiction_code` STRING COMMENT 'Code identifying the regulatory jurisdiction under which this statement is filed (e.g., FERC for federal, or state abbreviation such as CA, TX, NY for state PUC filings). Enables jurisdiction-specific regulatory accounting treatment and rate case cost-of-service allocation.',
    `long_term_debt_amt` DECIMAL(18,2) COMMENT 'Total long-term debt outstanding as reported on the balance sheet, including first mortgage bonds, senior notes, and other long-term borrowings. Used in capital structure analysis for rate case WACC and debt ratio calculations.',
    `net_income_amt` DECIMAL(18,2) COMMENT 'Net income (loss) for the reporting period as reported on the income statement after all revenues, expenses, taxes, and non-operating items. Key metric for board reporting, SEC filings, and ROE calculations in rate case proceedings.',
    `operating_cash_flow_amt` DECIMAL(18,2) COMMENT 'Net cash provided by (used in) operating activities as reported on the statement of cash flows. Reflects the utilitys ability to generate cash from core operations to fund capital investment and debt service.',
    `period_end_date` DATE COMMENT 'The last calendar date of the reporting period covered by this financial statement (e.g., 2024-12-31 for an annual statement). For balance sheets, this is the as-of date for all reported balances.',
    `period_start_date` DATE COMMENT 'The first calendar date of the reporting period covered by this financial statement (e.g., 2024-01-01 for an annual statement). Used to define the precise time window for income statement and cash flow statement line items.',
    `period_type` STRING COMMENT 'Specifies the duration and aggregation type of the reporting period covered by this statement. Distinguishes between periodic snapshots (monthly, quarterly, annual) and cumulative views (year-to-date, trailing twelve months) used in management reporting.. Valid values are `monthly|quarterly|annual|year_to_date|trailing_twelve_months`',
    `prepared_by` STRING COMMENT 'Name or employee ID of the financial analyst or accountant who prepared this financial statement. Supports audit trail and SOX internal control documentation requirements.',
    `rate_case_docket_number` STRING COMMENT 'The regulatory docket or case number assigned by the PUC or FERC to the rate case proceeding for which this financial statement serves as supporting evidence. Links the financial statement to a specific General Rate Case (GRC) or rate case filing. Null if not associated with a rate case.',
    `regulatory_assets_amt` DECIMAL(18,2) COMMENT 'Total regulatory assets recognized on the balance sheet under FASB ASC 980 rate-regulated accounting. Represents costs deferred for future recovery in rates (e.g., deferred storm costs, pension regulatory assets, unamortized debt issuance costs). Key component of the Regulatory Asset Base (RAB).',
    `regulatory_liabilities_amt` DECIMAL(18,2) COMMENT 'Total regulatory liabilities recognized on the balance sheet under FASB ASC 980, representing amounts collected in rates that are owed back to customers (e.g., excess deferred income taxes from Tax Cuts and Jobs Act, over-collected fuel costs). Offsets rate base in regulatory proceedings.',
    `reporting_basis` STRING COMMENT 'Indicates the accounting basis under which the statement is prepared. GAAP = U.S. Generally Accepted Accounting Principles; regulatory = rate-regulated basis per FASB ASC 980 (includes regulatory assets/liabilities); IFRS = International Financial Reporting Standards; management = internal management reporting basis. Critical for distinguishing FERC regulatory filings from SEC GAAP filings.. Valid values are `GAAP|regulatory|IFRS|management`',
    `reporting_unit` STRING COMMENT 'Specifies the unit in which monetary amounts are expressed in this statement (e.g., dollars, thousands, millions). FERC Form 1 requires reporting in thousands of dollars; SEC filings may use millions. Prevents misinterpretation of reported figures.. Valid values are `dollars|thousands|millions|billions`',
    `restatement_flag` BOOLEAN COMMENT 'Indicates whether this financial statement is a restatement of a previously filed statement (True) due to a material error correction or accounting change. Triggers additional disclosure requirements under FASB ASC 250 and SEC restatement reporting rules.',
    `restatement_reason` STRING COMMENT 'Narrative description of the reason for restatement when restatement_flag is True (e.g., correction of regulatory asset classification error, change in depreciation method, prior period adjustment). Required for FASB ASC 250 disclosure and SEC restatement filings. Null when restatement_flag is False.',
    `reviewed_by` STRING COMMENT 'Name or employee ID of the controller, CFO, or designated reviewer who reviewed and approved this financial statement. Required for SOX Section 302 CEO/CFO certification and internal control documentation.',
    `sap_company_code` STRING COMMENT 'The SAP FI/CO company code corresponding to the legal entity for which this financial statement is prepared. Enables direct traceability from the lakehouse silver layer back to the SAP general ledger source system.',
    `statement_number` STRING COMMENT 'Externally-known business identifier for the financial statement, typically assigned by the financial reporting system (e.g., SAP FI document number or reporting package reference). Used for traceability across reporting cycles.',
    `statement_status` STRING COMMENT 'Current lifecycle state of the financial statement. Draft = in preparation; under_review = submitted for internal review; approved = signed off by management/board; filed = submitted to regulatory body (FERC, PUC, SEC); restated = previously filed statement that has been corrected; superseded = replaced by a newer version.. Valid values are `draft|under_review|approved|filed|restated|superseded`',
    `statement_type` STRING COMMENT 'Classifies the financial statement as one of the four primary financial statement types: balance sheet (statement of financial position), income statement (statement of operations), statement of cash flows, or statement of changes in equity. Drives downstream report formatting and validation rules.. Valid values are `balance_sheet|income_statement|cash_flow_statement|statement_of_equity`',
    `total_assets_amt` DECIMAL(18,2) COMMENT 'Total assets as reported on the balance sheet for this entity and period. Represents the sum of all utility plant (net), current assets, regulatory assets, and other assets. Key metric for Regulatory Asset Base (RAB) valuation and rate case filings.',
    `total_equity_amt` DECIMAL(18,2) COMMENT 'Total shareholders equity (common equity plus preferred equity) as reported on the balance sheet. Used in Return on Equity (ROE) calculations for rate case filings and board financial reporting.',
    `total_liabilities_amt` DECIMAL(18,2) COMMENT 'Total liabilities as reported on the balance sheet, including long-term debt, current liabilities, regulatory liabilities, deferred income taxes (ADIT), and other obligations. Used in capital structure analysis for rate case ROE and WACC calculations.',
    `total_opex_amt` DECIMAL(18,2) COMMENT 'Total operating and maintenance (O&M) expenses as reported on the income statement, including fuel costs, purchased power, transmission, distribution, customer service, and administrative expenses. Key input for OPEX tracking and rate case cost-of-service studies.',
    `total_revenue_amt` DECIMAL(18,2) COMMENT 'Total operating revenues as reported on the income statement, including electric revenues, gas revenues, and other operating revenues. Primary top-line metric for EBITDA reporting, rate case revenue requirement studies, and FERC Form 1 Schedule of Revenues.',
    `updated_timestamp` TIMESTAMP COMMENT 'The timestamp when this financial statement record was last modified in the lakehouse silver layer. Tracks revisions during the review and approval workflow and supports incremental data pipeline processing.',
    `utility_plant_net_amt` DECIMAL(18,2) COMMENT 'Net utility plant in service (gross plant less accumulated depreciation) as reported on the balance sheet. The largest asset category for a regulated utility and the primary driver of the Regulatory Asset Base (RAB) and rate base calculations.',
    `utility_type` STRING COMMENT 'Identifies the utility service type covered by this financial statement: electric, gas, combined electric and gas, or other. Supports FERC Form 1 (electric) vs. FERC Form 2 (gas) filing segregation and state PUC rate case cost-of-service studies by utility segment.. Valid values are `electric|gas|combined|other`',
    CONSTRAINT pk_financial_statement PRIMARY KEY(`financial_statement_id`)
) COMMENT 'Periodic financial statement records (balance sheet, income statement, statement of cash flows) prepared for internal management reporting, board reporting, SEC filings, and regulatory submissions including FERC Form 1 and state PUC annual reports. Captures statement type, reporting period, entity/segment, and GAAP vs. regulatory basis indicators.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`finance`.`tax_provision` (
    `tax_provision_id` BIGINT COMMENT 'Unique surrogate identifier for each income tax provision record in the lakehouse Silver layer. Primary key for the tax_provision data product.',
    `gl_account_id` BIGINT COMMENT 'Foreign key linking to finance.gl_account. Business justification: Tax Provision references GL Account for tax calculations; FK replaces code.',
    `adit_beginning_balance_amt` DECIMAL(18,2) COMMENT 'Opening balance of accumulated deferred income taxes (ADIT) for the period. ADIT is a regulatory liability/asset on the rate base that offsets the utilitys rate base per PUC orders. Critical for rate case revenue requirement and FERC Form 1 reporting.',
    `adit_ending_balance_amt` DECIMAL(18,2) COMMENT 'Closing balance of accumulated deferred income taxes (ADIT) for the period after current-period deferred tax expense/benefit and ARAM amortization. Used directly in rate base calculations as a rate base offset per PUC-ordered treatment.',
    `approved_by` STRING COMMENT 'Name or employee ID of the tax department manager or controller who approved this tax provision record. Required for SOX Section 404 internal control documentation and audit trail.',
    `approved_date` DATE COMMENT 'The date on which the tax provision record received final approval from the authorized approver. Part of the SOX-compliant review and approval workflow for income tax accounting.',
    `aram_amortization_amt` DECIMAL(18,2) COMMENT 'The period amortization of excess ADIT under the Average Rate Assumption Method (ARAM) as required by IRS normalization rules and FERC Order 849. Represents the amount of excess ADIT returned to customers through rate reductions in the current period.',
    `bonus_depreciation_amt` DECIMAL(18,2) COMMENT 'Additional first-year bonus depreciation claimed under IRC §168(k) for qualifying utility property placed in service during the period. Creates large temporary differences and accelerates ADIT accumulation. Subject to IRS normalization rules for regulated utilities.',
    `book_depreciation_amt` DECIMAL(18,2) COMMENT 'Total GAAP straight-line depreciation for the period as recorded in SAP FI/CO asset accounting. Compared against tax depreciation to compute the accelerated depreciation temporary difference driving the deferred tax liability.',
    `calculation_method` STRING COMMENT 'The accounting method used to compute the income tax provision: asset_liability (balance sheet approach per ASC 740), deferred (income statement approach, legacy), or flow_through (used for certain regulatory assets per ASC 980-740). Regulated utilities may use flow-through for specific items per PUC order.. Valid values are `asset_liability|deferred|flow_through`',
    `cost_center_code` STRING COMMENT 'SAP FI/CO cost center code to which the income tax expense is allocated. Used for segment-level tax expense reporting and rate case cost-of-service allocation by utility function (electric, gas, common).',
    `created_timestamp` TIMESTAMP COMMENT 'The timestamp when this tax provision record was first created in the system. Supports audit trail, data lineage, and SOX internal control requirements. Sourced from SAP FI/CO document creation timestamp.',
    `currency_code` STRING COMMENT 'Three-letter ISO 4217 currency code for all monetary amounts in this record (e.g., USD). Supports multi-currency consolidation for entities with foreign operations.. Valid values are `^[A-Z]{3}$`',
    `current_tax_expense_amt` DECIMAL(18,2) COMMENT 'The portion of total income tax expense attributable to taxes currently payable or refundable for the period. Represents the estimated tax liability on the current-year tax return before deferred items.',
    `deferred_tax_asset_amt` DECIMAL(18,2) COMMENT 'Gross deferred tax asset balance representing future tax benefits from deductible temporary differences (e.g., pension obligations, asset retirement obligations, regulatory liabilities). Before valuation allowance offset.',
    `deferred_tax_expense_amt` DECIMAL(18,2) COMMENT 'The portion of total income tax expense attributable to temporary differences between book and tax basis of assets and liabilities. Positive value indicates deferred tax expense; negative indicates deferred tax benefit.',
    `deferred_tax_liability_amt` DECIMAL(18,2) COMMENT 'Gross deferred tax liability balance representing future tax obligations from taxable temporary differences (e.g., accelerated MACRS depreciation on utility plant, AFUDC equity). Primary driver of ADIT balance for regulated utilities.',
    `effective_tax_rate` DECIMAL(18,2) COMMENT 'The ratio of total income tax expense to pre-tax book income, expressed as a decimal (e.g., 0.2100 for 21%). Used in rate case cost-of-service studies and investor reporting. Computed as total_tax_expense_amt / pretax_income_amt.',
    `excess_adit_amt` DECIMAL(18,2) COMMENT 'The excess ADIT balance arising from the reduction in the federal corporate tax rate under the Tax Cuts and Jobs Act (TCJA) of 2017. Subject to ARAM (Average Rate Assumption Method) amortization and must be returned to customers per IRS normalization rules and PUC orders.',
    `ferc_account_code` STRING COMMENT 'FERC Uniform System of Accounts code associated with this tax provision record (e.g., Account 190 for deferred income taxes — other, Account 281/282/283 for accumulated deferred income taxes). Required for FERC Form 1 annual report filing.',
    `fiscal_period` STRING COMMENT 'The accounting period (1–12 for monthly, or 1–4 for quarterly) within the fiscal year to which this provision record applies. Supports interim period tax accounting per FASB ASC 740-270.',
    `fiscal_year` STRING COMMENT 'The fiscal year (e.g., 2024) to which this tax provision record applies. Used for period-over-period comparison, rate case cost-of-service studies, and FERC Form 1 annual reporting.',
    `interest_on_utp_amt` DECIMAL(18,2) COMMENT 'Accrued interest expense on uncertain tax position reserves. Classified as income tax expense or interest expense per the entitys accounting policy election under ASC 740-10-45-25.',
    `investment_tax_credit_amt` DECIMAL(18,2) COMMENT 'Deferred investment tax credit balance for regulated utilities that defer and amortize ITC over the life of the related asset per the deferral method (FASB ASC 980-740). Distinct from current-period ITC flow-through. Tracked separately for normalization compliance.',
    `jurisdiction_code` STRING COMMENT 'Code identifying the taxing jurisdiction (e.g., US-FED for federal, US-CA for California, US-TX for Texas). Drives apportionment factor application and state/federal tax rate differentiation.',
    `jurisdiction_type` STRING COMMENT 'Classification of the taxing authority level: federal (IRS), state (state revenue department), local (municipal), or foreign. Determines applicable tax code, rate schedules, and regulatory reporting requirements.. Valid values are `federal|state|local|foreign`',
    `last_updated_timestamp` TIMESTAMP COMMENT 'The timestamp when this tax provision record was most recently modified. Tracks revisions to provision calculations, true-up adjustments, and amended filings. Essential for Silver layer incremental load processing and audit trail.',
    `legal_entity_code` STRING COMMENT 'Code identifying the legal entity (subsidiary or consolidated parent) for which the tax provision is computed. Aligns with SAP company code structure and FERC Form 1 respondent entity.',
    `net_operating_loss_carryforward_amt` DECIMAL(18,2) COMMENT 'Cumulative net operating loss carryforward balance available to offset future taxable income. Post-TCJA, federal NOLs are carried forward indefinitely but limited to 80% of taxable income. Generates a deferred tax asset subject to valuation allowance assessment.',
    `normalization_compliance_flag` BOOLEAN COMMENT 'Indicates whether this tax provision record is in compliance with IRS normalization requirements for regulated utilities (IRC §168(i)(9)). Non-compliance can result in loss of accelerated depreciation benefits. Monitored for FERC and PUC regulatory filings.',
    `penalties_on_utp_amt` DECIMAL(18,2) COMMENT 'Accrued tax penalties associated with uncertain tax positions. Classified as income tax expense per the entitys accounting policy election. Monitored for rate case disallowance risk.',
    `permanent_difference_amt` DECIMAL(18,2) COMMENT 'Net permanent differences between book income and taxable income that never reverse (e.g., tax-exempt interest, non-deductible penalties, AFUDC equity component). Key reconciling item in the effective tax rate reconciliation schedule.',
    `pretax_income_amt` DECIMAL(18,2) COMMENT 'Total book income (GAAP) before income tax expense for the period and jurisdiction. Starting point for the effective tax rate reconciliation and current/deferred tax expense computation. Sourced from SAP FI/CO profit center reporting.',
    `provision_date` DATE COMMENT 'The business date on which the income tax provision was calculated and recorded. Represents the principal business event date for this transaction record. Typically the last day of the fiscal period.',
    `provision_number` STRING COMMENT 'Externally-known business identifier for the tax provision record, typically sourced from SAP FI/CO tax calculation run (e.g., TP-2024-FED-Q4). Used for cross-system reconciliation and audit trail.',
    `provision_status` STRING COMMENT 'Current lifecycle state of the tax provision record: draft (initial calculation), under_review (tax department review), approved (CFO/controller sign-off), filed (included in tax return), amended (restated), or closed (finalized and archived).. Valid values are `draft|under_review|approved|filed|amended|closed`',
    `provision_type` STRING COMMENT 'Classifies the nature of the provision calculation: annual (year-end), interim quarterly or monthly (ASC 740-270 estimated annual effective tax rate), true-up (post-filing adjustment), or amended (restated provision). [ENUM-REF-CANDIDATE: annual|interim_quarterly|interim_monthly|true_up|amended — promote to reference product]. Valid values are `annual|interim_quarterly|interim_monthly|true_up|amended`',
    `rate_case_docket_number` STRING COMMENT 'The PUC or FERC docket number of the rate case in which this tax provision data is used as supporting evidence for the revenue requirement calculation. Links tax provision to the regulatory proceeding.',
    `regulatory_liability_tax_effect_amt` DECIMAL(18,2) COMMENT 'The income tax effect of regulatory liabilities (e.g., excess ADIT returned to customers, over-recovered revenues) recognized under FASB ASC 980. Represents the deferred tax component of regulatory liabilities on the balance sheet.',
    `state_apportionment_factor` DECIMAL(18,2) COMMENT 'The blended apportionment factor (sales/receipts, payroll, property — weighted per state formula) used to allocate multi-state income to a specific state jurisdiction. Expressed as a decimal (e.g., 0.4523 for 45.23%). Required for state income tax provision calculations.',
    `statutory_tax_rate` DECIMAL(18,2) COMMENT 'The enacted statutory income tax rate applicable to the legal entity for the jurisdiction and fiscal year (e.g., 0.2100 for 21% federal corporate rate post-TCJA). Used as the baseline for effective tax rate reconciliation.',
    `tax_credit_amt` DECIMAL(18,2) COMMENT 'Total income tax credits recognized in the period, including production tax credits (PTC) for wind/solar generation, investment tax credits (ITC) for renewable energy assets, and R&D credits. Reduces current tax expense dollar-for-dollar.',
    `tax_depreciation_amt` DECIMAL(18,2) COMMENT 'Total tax depreciation claimed for the period under IRS Modified Accelerated Cost Recovery System (MACRS). Typically exceeds book depreciation for utility plant, creating the primary taxable temporary difference and deferred tax liability for regulated utilities.',
    `tax_return_type` STRING COMMENT 'Indicates whether the provision is computed on a consolidated federal return, separate company basis, combined state return, or unitary state return. Critical for apportionment factor allocation and intercompany tax sharing agreement calculations.. Valid values are `consolidated|separate_company|combined|unitary`',
    `temporary_difference_amt` DECIMAL(18,2) COMMENT 'Net aggregate temporary difference between book and tax basis of assets and liabilities for the period and jurisdiction. Drives the deferred tax expense/benefit calculation. Includes accelerated depreciation, regulatory assets/liabilities, and pension timing differences.',
    `total_tax_expense_amt` DECIMAL(18,2) COMMENT 'Sum of current and deferred income tax expense for the period. Equals the total provision for income taxes reported on the GAAP income statement. Used in EBITDA reconciliation and rate case revenue requirement calculations.',
    `uncertain_tax_position_amt` DECIMAL(18,2) COMMENT 'Reserve for uncertain tax positions (UTPs) under the more-likely-than-not recognition threshold. Represents the cumulative liability for tax positions that may not be sustained upon IRS or state examination. Disclosed in financial statement footnotes.',
    `utility_service_type` STRING COMMENT 'The regulated utility service type to which this tax provision is attributed: electric, gas, common (shared), water, or steam. Required for functional separation in rate case cost-of-service studies and FERC Form 1 reporting.. Valid values are `electric|gas|common|water|steam`',
    `valuation_allowance_amt` DECIMAL(18,2) COMMENT 'Valuation allowance recorded against gross deferred tax assets when it is more likely than not that some portion will not be realized. Reduces net deferred tax asset on the balance sheet per ASC 740 realizability assessment.',
    CONSTRAINT pk_tax_provision PRIMARY KEY(`tax_provision_id`)
) COMMENT 'Income tax provision and deferred tax records capturing current tax expense, deferred tax expense, effective tax rate reconciliation, and accumulated deferred income taxes (ADIT) by jurisdiction and legal entity. Tracks IRS normalization requirements for regulated utilities, excess ADIT balances subject to ARAM (Average Rate Assumption Method) amortization per Tax Cuts and Jobs Act, state/federal tax apportionment factors, and PUC-ordered rate base ADIT offsets. Essential for rate case revenue requirement calculations and FERC Form 1 tax reporting.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`finance`.`intercompany_transaction` (
    `intercompany_transaction_id` BIGINT COMMENT 'System-generated unique identifier for the intercompany transaction record.',
    `finance_capex_project_id` BIGINT COMMENT 'Identifier of the capital or cost project associated with the transaction.',
    `journal_entry_id` BIGINT COMMENT 'Link to the corresponding journal entry in the general ledger.',
    `reversal_of_transaction_intercompany_transaction_id` BIGINT COMMENT 'Identifier of the original transaction that is being reversed.',
    `legal_entity_id` BIGINT COMMENT 'Unique identifier of the sending legal entity within the enterprise master data.',
    `reversal_intercompany_transaction_id` BIGINT COMMENT 'Self-referencing FK on intercompany_transaction (reversal_intercompany_transaction_id)',
    `accounting_period` STRING COMMENT 'Fiscal period identifier (e.g., FY2023Q1) for the transaction.',
    `approval_status` STRING COMMENT 'Current approval state of the transaction.. Valid values are `approved|rejected|pending`',
    `approved_by` STRING COMMENT 'Identifier of the employee who approved the transaction.',
    `approved_timestamp` TIMESTAMP COMMENT 'Timestamp when the transaction received approval.',
    `cost_center_code` STRING COMMENT 'Cost center to which the transaction cost is allocated.',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when the transaction record was first created in the system.',
    `currency_code` STRING COMMENT 'Three‑letter ISO 4217 code of the transaction currency.. Valid values are `^[A-Z]{3}$`',
    `elimination_flag` BOOLEAN COMMENT 'Indicates whether the transaction is an elimination entry for consolidation purposes.',
    `exchange_rate` DECIMAL(18,2) COMMENT 'Rate used to convert the transaction amount to the reporting currency, if applicable.',
    `ferc_account_code` STRING COMMENT 'Federal Energy Regulatory Commission account identifier linked to the transaction.',
    `gross_amount` DECIMAL(18,2) COMMENT 'Total monetary amount before taxes, fees, or adjustments.',
    `intercompany_transaction_description` STRING COMMENT 'Free‑text description of the purpose or nature of the intercompany transaction.',
    `intercompany_transaction_status` STRING COMMENT 'Current lifecycle state of the intercompany transaction.. Valid values are `draft|pending|posted|settled|cancelled|reversed`',
    `net_amount` DECIMAL(18,2) COMMENT 'Final amount after taxes, fees, and adjustments.',
    `posting_date` DATE COMMENT 'Accounting date on which the transaction is posted to the general ledger.',
    `rate_case_reference` STRING COMMENT 'Reference to the rate case docket or filing that governs the transaction.',
    `receiver_company_code` STRING COMMENT 'Code identifying the legal entity that receives the intercompany charge.. Valid values are `^[A-Z0-9]{1,10}$`',
    `receiver_legal_entity_code` BIGINT COMMENT 'Unique identifier of the receiving legal entity within the enterprise master data.',
    `reference_document_number` STRING COMMENT 'External document number (e.g., invoice, contract) linked to the transaction.',
    `regulatory_affiliate_flag` BOOLEAN COMMENT 'True if the transaction is subject to PUC affiliate transaction compliance.',
    `reversal_flag` BOOLEAN COMMENT 'True if this record represents a reversal of a prior transaction.',
    `sender_company_code` STRING COMMENT 'Code identifying the legal entity that originated the intercompany charge.. Valid values are `^[A-Z0-9]{1,10}$`',
    `settlement_date` DATE COMMENT 'Date on which cash settlement of the intercompany transaction occurs.',
    `source_system` STRING COMMENT 'Originating source system that created the transaction record.. Valid values are `SAP|Oracle|Custom|Other`',
    `tax_amount` DECIMAL(18,2) COMMENT 'Tax component associated with the intercompany transaction.',
    `tax_code` STRING COMMENT 'Tax code applied to the transaction for regulatory reporting.',
    `transaction_number` STRING COMMENT 'External business identifier assigned to the transaction (e.g., invoice or journal number).',
    `transaction_timestamp` TIMESTAMP COMMENT 'Date and time when the intercompany transaction was executed in the business process.',
    `transaction_type` STRING COMMENT 'Classification of the transaction (e.g., service charge, fuel transfer, capacity payment).. Valid values are `service_charge|fuel_transfer|capacity_payment|management_fee|allocation|elimination`',
    `updated_timestamp` TIMESTAMP COMMENT 'Timestamp of the most recent modification to the transaction record.',
    CONSTRAINT pk_intercompany_transaction PRIMARY KEY(`intercompany_transaction_id`)
) COMMENT 'Records of financial transactions between affiliated legal entities within the utility holding company structure, including shared service charges, fuel transfers, capacity payments, and management fees. Tracks sender/receiver company codes, elimination entries, and PUC affiliate transaction compliance. Supports consolidated financial statement preparation and state PUC affiliate transaction audit requirements.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`finance`.`bank_account` (
    `bank_account_id` BIGINT COMMENT 'Unique surrogate key for the bank account record.',
    `employee_id` BIGINT COMMENT 'Identifier of the primary authorized signer for the account.',
    `person_id` BIGINT COMMENT 'Identifier of the primary authorized signer for the account.',
    `sweep_target_account_id` BIGINT COMMENT 'Identifier of the target account for sweep transfers.',
    `sweep_target_bank_account_id` BIGINT COMMENT 'Self-referencing FK on bank_account (sweep_target_bank_account_id)',
    `account_name` STRING COMMENT 'Human‑readable name for the bank account (e.g., "Operating Account – NY").',
    `account_number` STRING COMMENT 'Primary identifier assigned by the bank; used for payments and reconciliations.',
    `account_owner_cost_center` STRING COMMENT 'Cost center code of the owning department.',
    `account_owner_department` STRING COMMENT 'Internal department responsible for the account.',
    `account_type` STRING COMMENT 'Classification of the account purpose within treasury operations.. Valid values are `operating|debt_service_reserve|nuclear_decommissioning|storm_reserve|escrow`',
    `authorized_signer_name` STRING COMMENT 'Full legal name of the authorized signer.',
    `balance` DECIMAL(18,2) COMMENT 'Current available balance in the account.',
    `bank_account_status` STRING COMMENT 'Current lifecycle status of the bank account.. Valid values are `active|inactive|suspended|closed`',
    `bank_branch_code` STRING COMMENT 'Identifier for the specific branch of the bank where the account is held.',
    `bank_name` STRING COMMENT 'Legal name of the banking institution holding the account.',
    `cash_positioning_flag` BOOLEAN COMMENT 'Indicates if the account is used for cash positioning activities.',
    `closing_date` DATE COMMENT 'Date the account was closed or terminated (nullable).',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when the account record was created in the system.',
    `currency_code` STRING COMMENT 'Three‑letter ISO currency code for the account.. Valid values are `^[A-Z]{3}$`',
    `daily_transaction_limit` DECIMAL(18,2) COMMENT 'Maximum total transaction amount allowed per day.',
    `debt_covenant_compliance_flag` BOOLEAN COMMENT 'Indicates if the account is monitored for debt covenant compliance.',
    `ferc_account_code` STRING COMMENT 'FERC accounting code associated with the account for regulatory reporting.',
    `iban` STRING COMMENT 'International Bank Account Number for cross‑border transactions.',
    `interest_rate` DECIMAL(18,2) COMMENT 'Annual interest rate applied to the account (e.g., 0.0250 for 2.5%).',
    `last_reconciled_timestamp` TIMESTAMP COMMENT 'Timestamp of the last successful reconciliation.',
    `notes` STRING COMMENT 'Free‑text notes regarding the account.',
    `opening_date` DATE COMMENT 'Date the account was opened with the bank.',
    `overdraft_limit` DECIMAL(18,2) COMMENT 'Maximum authorized overdraft amount.',
    `reconciliation_status` STRING COMMENT 'Status of the most recent bank reconciliation.. Valid values are `pending|completed|error`',
    `regulatory_flag` BOOLEAN COMMENT 'Indicates if the account is subject to regulatory reporting requirements.',
    `routing_number` STRING COMMENT 'Domestic routing number (e.g., ABA) used for ACH transactions.',
    `sap_cost_center_code` STRING COMMENT 'SAP cost center linked to the account for internal cost allocation.',
    `sap_wbs_element` STRING COMMENT 'SAP Work Breakdown Structure element associated with the account.',
    `sweep_arrangement_flag` BOOLEAN COMMENT 'Indicates whether the account participates in automatic sweep arrangements.',
    `swift_code` STRING COMMENT 'Bank Identifier Code used for international wire transfers.',
    `updated_timestamp` TIMESTAMP COMMENT 'Timestamp of the most recent update to the account record.',
    CONSTRAINT pk_bank_account PRIMARY KEY(`bank_account_id`)
) COMMENT 'Treasury master data for utility bank accounts including operating accounts, debt service reserve funds, nuclear decommissioning trust accounts, storm reserve funds, and escrow accounts. Tracks bank, account number, account type, authorized signers, balance positions, and sweep arrangements. Supports cash positioning, bank reconciliation, and debt covenant compliance monitoring.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`finance`.`finance_lease` (
    `finance_lease_id` BIGINT COMMENT 'Unique system-generated identifier for the lease record.',
    `fixed_asset_id` BIGINT COMMENT 'Identifier of the underlying asset that is being leased.',
    `registry_id` BIGINT COMMENT 'Identifier of the underlying asset that is being leased.',
    `document_id` BIGINT COMMENT 'Identifier of the electronic lease contract document stored in the DMS.',
    `finance_capex_project_id` BIGINT COMMENT 'Capital project associated with the lease, if any.',
    `modified_finance_lease_id` BIGINT COMMENT 'Self-referencing FK on finance_lease (modified_finance_lease_id)',
    `accounting_standard` STRING COMMENT 'Accounting framework governing lease treatment.. Valid values are `ASC842|IAS17`',
    `amortization_method` STRING COMMENT 'Method used to amortize the right‑of‑use asset over the lease term.. Valid values are `straight_line|sum_of_years_digits|units_of_production`',
    `amortization_period_years` STRING COMMENT 'Number of years over which the asset is amortized.',
    `asset_location` STRING COMMENT 'Physical location or site of the leased asset.',
    `asset_type` STRING COMMENT 'Category of the underlying asset (e.g., generation facility, vehicle, office space).',
    `classification` STRING COMMENT 'ASC 842 classification indicating whether the lease is operating or finance.. Valid values are `operating|finance`',
    `commencement_date` DATE COMMENT 'Date the lessee obtains the right to use the asset.',
    `contract_status_date` DATE COMMENT 'Date when the lease status last changed.',
    `cost_center_code` STRING COMMENT 'Cost center responsible for lease expense allocation.',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when the lease record was first created in the system.',
    `discount_rate` DECIMAL(18,2) COMMENT 'Rate used to discount future lease payments to present value.',
    `end_date` DATE COMMENT 'Date the lease terminates or expires, if known.',
    `ferc_form1_schedule` STRING COMMENT 'Schedule identifier for reporting lease obligations on FERC Form 1.',
    `finance_lease_status` STRING COMMENT 'Current lifecycle status of the lease.. Valid values are `draft|active|suspended|terminated|expired`',
    `last_reviewed_timestamp` TIMESTAMP COMMENT 'Timestamp of the last formal review of lease terms for compliance.',
    `lease_description` STRING COMMENT 'Narrative description of the lease purpose and key terms.',
    `lease_number` STRING COMMENT 'External lease agreement number assigned by the utility or lessor.',
    `lease_type` STRING COMMENT 'Classification of the lease based on its economic substance.. Valid values are `operating|finance|sale_and_leaseback`',
    `liability` DECIMAL(18,2) COMMENT 'Present value of lease payments owed at lease commencement.',
    `modification_date` DATE COMMENT 'Date of the most recent lease amendment.',
    `modification_flag` BOOLEAN COMMENT 'Indicates whether the lease has been modified after inception.',
    `payment_amount` DECIMAL(18,2) COMMENT 'Base amount due each payment period before taxes or fees.',
    `payment_currency` STRING COMMENT 'ISO 4217 currency code for lease payments (e.g., USD).',
    `payment_due_date` DATE COMMENT 'Standard calendar date on which each lease payment is due.',
    `payment_frequency` STRING COMMENT 'How often lease payments are scheduled.. Valid values are `monthly|quarterly|semi_annually|annually`',
    `payment_method` STRING COMMENT 'Method used to remit lease payments.. Valid values are `check|electronic|wire|direct_debit`',
    `payment_terms` STRING COMMENT 'Standard payment terms (e.g., Net 30, Net 45).',
    `purchase_option_flag` BOOLEAN COMMENT 'Indicates whether the lease provides a purchase option at termination.',
    `purchase_price` DECIMAL(18,2) COMMENT 'Fixed price to purchase the underlying asset if the purchase option is exercised.',
    `rate_case_reference` STRING COMMENT 'Reference to the rate case docket where the lease is evaluated.',
    `regulatory_jurisdiction` STRING COMMENT 'Regulatory body or jurisdiction governing the lease (e.g., FERC, NERC, State PUC).',
    `renewal_option_flag` BOOLEAN COMMENT 'Indicates whether the lease includes a renewal option.',
    `renewal_term_years` STRING COMMENT 'Length of the renewal period if the renewal option is exercised.',
    `residual_value` DECIMAL(18,2) COMMENT 'Estimated fair value of the asset at lease end, used for finance lease calculations.',
    `right_of_use_asset_value` DECIMAL(18,2) COMMENT 'Present value of the right‑of‑use asset at lease commencement.',
    `start_date` DATE COMMENT 'Date the lease becomes effective and the right‑of‑use asset is recognized.',
    `status_reason` STRING COMMENT 'Free‑text reason explaining the current lease status.',
    `term_months` STRING COMMENT 'Additional months beyond whole years in the lease term.',
    `term_years` STRING COMMENT 'Number of whole years in the lease term.',
    `termination_date` DATE COMMENT 'Date the lease is terminated, either by expiry or early termination.',
    `updated_timestamp` TIMESTAMP COMMENT 'Timestamp of the most recent update to the lease record.',
    CONSTRAINT pk_finance_lease PRIMARY KEY(`finance_lease_id`)
) COMMENT 'ASC 842 lease accounting records for operating and finance leases including generation facility PPAs classified as leases, fleet vehicle leases, office space leases, and equipment leases. Tracks right-of-use asset, lease liability, payment schedule, lease term, discount rate, and lease classification. Supports FERC Form 1 reporting of lease obligations and rate case treatment of lease expense vs. capital lease amortization.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`finance`.`profit_center` (
    `profit_center_id` BIGINT COMMENT 'Primary key for profit_center',
    `employee_id` BIGINT COMMENT 'Identifier of the employee who owns the profit center.',
    `legal_entity_id` BIGINT COMMENT 'Identifier of the legal organization to which the profit center belongs.',
    `parent_profit_center_id` BIGINT COMMENT 'Identifier of the immediate parent profit center in the hierarchy.',
    `profit_center_legal_entity_id` BIGINT COMMENT 'Identifier of the legal entity that owns the profit center.',
    `actual_profit` DECIMAL(18,2) COMMENT 'Realized profit for the profit center in the reporting period.',
    `budget_amount` DECIMAL(18,2) COMMENT 'Approved budget for the profit center for the fiscal period.',
    `cost_center_id` BIGINT COMMENT 'Link to the associated cost center for expense allocation.',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when the profit center record was first created.',
    `currency_code` STRING COMMENT 'Three‑letter ISO currency code for monetary values.',
    `effective_end_date` DATE COMMENT 'Date when the profit center ceased operation (null if still active).',
    `effective_start_date` DATE COMMENT 'Date when the profit center became operational.',
    `expense_target` DECIMAL(18,2) COMMENT 'Target expense amount for cost control.',
    `hierarchy_level` STRING COMMENT 'Numeric level of the profit center within the organizational hierarchy (1 = top).',
    `market_code` STRING COMMENT 'Code identifying the market segment served by the profit center.',
    `planned_profit` DECIMAL(18,2) COMMENT 'Profit forecasted for the upcoming period.',
    `profit_center_amortization_amount` DECIMAL(18,2) COMMENT 'Amortization expense allocated to the profit center.',
    `profit_center_approval_date` DATE COMMENT 'Date when the profit centers plan was approved.',
