    `profit_center_description` STRING COMMENT 'Detailed description of the profit centers purpose and scope.',
    `profit_center_external_reference` STRING COMMENT 'Identifier used in external systems (e.g., SAP) for the profit center.',
    `profit_center_fiscal_year` STRING COMMENT 'Fiscal year to which the profit centers financial data pertains.',
    `profit_center_last_review_date` DATE COMMENT 'Date of the most recent performance review of the profit center.',
    `profit_center_manager_email` STRING COMMENT 'Email address of the profit center manager.',
    `profit_center_manager_name` STRING COMMENT 'Full name of the manager responsible for the profit center.',
    `profit_center_manager_phone` STRING COMMENT 'Contact phone number of the profit center manager.',
    `profit_center_name` STRING COMMENT 'Human‑readable name of the profit center.',
    `profit_center_operating_expenditure` DECIMAL(18,2) COMMENT 'Operating expenditures incurred by the profit center.',
    `profit_center_owner_role` STRING COMMENT 'Job role of the profit center owner.',
    `profit_center_reporting_line` STRING COMMENT 'Organizational reporting line for the profit center.',
    `profit_center_review_frequency` STRING COMMENT 'How often the profit center is reviewed for performance.',
    `profit_center_risk_rating` STRING COMMENT 'Risk rating assigned to the profit center based on financial and operational risk.',
    `profit_center_status` STRING COMMENT 'Current lifecycle status of the profit center.',
    `profit_center_tax_identifier` STRING COMMENT 'Tax identification number associated with the profit center.',
    `profit_center_type` STRING COMMENT 'Category of the profit center indicating its functional area.',
    `profit_center_valuation_amount` DECIMAL(18,2) COMMENT 'Current valuation of the profit centers assets.',
    `profit_target` DECIMAL(18,2) COMMENT 'Target profit amount set for performance measurement.',
    `region_code` STRING COMMENT 'Three‑letter ISO code representing the geographic region of the profit center.',
    `revenue_target` DECIMAL(18,2) COMMENT 'Target revenue amount for the profit center.',
