CREATE OR REPLACE TABLE `power_and_utilities_v2`.`finance`.`fund` (
    `fund_id` BIGINT COMMENT 'Primary key for fund',
    `parent_fund_id` BIGINT COMMENT 'Self-referencing FK on fund (parent_fund_id)',
    `fund_annual_return` DECIMAL(18,2) COMMENT 'Percentage return of the fund over the most recent fiscal year.',
    `fund_aum` DECIMAL(18,2) COMMENT 'Total market value of assets managed by the fund.',
    `fund_balance` DECIMAL(18,2) COMMENT 'Current monetary balance of the fund.',
    `fund_category` STRING COMMENT 'Broad investment category of the fund.',
    `fund_code` STRING COMMENT 'External business code or ticker that uniquely identifies the fund in external systems.',
    `fund_creation_date` DATE COMMENT 'Date the fund record was first entered into the system.',
    `fund_currency` STRING COMMENT 'ISO 4217 currency code in which the fund is denominated.',
    `fund_description` STRING COMMENT 'Free‑text description of the funds purpose, strategy, and characteristics.',
    `fund_distribution_policy` STRING COMMENT 'Policy governing how income distributions are handled.',
    `fund_effective_date` DATE COMMENT 'Date the fund became effective for accounting purposes.',
    `fund_expense_ratio` DECIMAL(18,2) COMMENT 'Total annual operating expenses of the fund expressed as a percentage of average net assets.',
    `fund_expiration_date` DATE COMMENT 'Date the fund is scheduled to be retired or closed, if applicable.',
    `fund_fasb_asc_980_compliance` BOOLEAN COMMENT 'Indicates whether the fund complies with ASC 980 accounting requirements.',
    `fund_fasb_code` STRING COMMENT 'Code linking the fund to the relevant FASB ASC 980 accounting guidance.',
    `fund_fasb_section` STRING COMMENT 'Section of ASC 980 that applies to the fund.',
    `fund_fasb_subsection` STRING COMMENT 'Subsection of ASC 980 relevant to the fund.',
    `fund_fee_percentage` DECIMAL(18,2) COMMENT 'Annual management fee charged as a percentage of assets under management.',
    `fund_fiscal_year_end` DATE COMMENT 'Date that marks the end of the funds fiscal year.',
    `fund_inception_date` DATE COMMENT 'Date the fund was originally created or launched.',
    `fund_investment_focus` STRING COMMENT 'Primary sectors, regions, or asset classes the fund targets.',
    `fund_is_public` BOOLEAN COMMENT 'True if the fund is publicly offered; false if private.',
    `fund_last_updated_timestamp` TIMESTAMP COMMENT 'Timestamp of the most recent update to the fund record.',
    `fund_legal_entity` STRING COMMENT 'Legal entity under which the fund is organized.',
    `fund_manager_name` STRING COMMENT 'Name of the individual or entity responsible for managing the fund.',
    `fund_name` STRING COMMENT 'Human‑readable name of the fund.',
    `fund_nav` DECIMAL(18,2) COMMENT 'Net asset value per share/unit of the fund.',
    `fund_nav_date` DATE COMMENT 'Date for which the NAV is reported.',
    `fund_regulatory_status` STRING COMMENT 'Current compliance status of the fund with applicable regulations.',
    `fund_reporting_code` STRING COMMENT 'Internal code used for financial reporting and regulatory filings.',
    `fund_risk_rating` STRING COMMENT 'Qualitative risk rating assigned to the fund.',
    `fund_status` STRING COMMENT 'Current lifecycle status of the fund.',
    `fund_strategy` STRING COMMENT 'Detailed description of the funds investment strategy.',
    `fund_tax_status` STRING COMMENT 'Tax classification of the fund for reporting purposes.',
    `fund_total_assets` DECIMAL(18,2) COMMENT 'Aggregate value of all assets held by the fund.',
    `fund_total_liabilities` DECIMAL(18,2) COMMENT 'Aggregate value of all liabilities of the fund.',
    `fund_type` STRING COMMENT 'Classification of the fund by its investment structure.',
    `fund_valuation_method` STRING COMMENT 'Methodology used to value the funds holdings.',
    `fund_year_to_date_return` DECIMAL(18,2) COMMENT 'Percentage return of the fund from the start of the current fiscal year to date.',
    CONSTRAINT pk_fund PRIMARY KEY(`fund_id`)
) COMMENT 'Master reference table for fund. Referenced by fund_id.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`finance`.`depreciation_area` (
    `depreciation_area_id` BIGINT COMMENT 'Primary key for depreciation_area',
    `cost_center_id` BIGINT COMMENT 'FK to finance.cost_center',
