    `depreciation_area_description` STRING COMMENT 'Additional narrative information about the depreciation area.',
    `effective_end_date` DATE COMMENT 'Last date the depreciation area is valid; null if still active.',
    `effective_start_date` DATE COMMENT 'First date the depreciation area is valid for accounting purposes.',
