    `last_reviewed_date` DATE COMMENT 'Most recent date on which the depreciation area configuration was reviewed for accuracy.',
    `depreciation_area_name` STRING COMMENT 'Human‑readable name of the depreciation area (e.g., North Plant, West Service Area).',
    `depreciation_area_status` STRING COMMENT 'Operational status of the depreciation area.',
    `updated_timestamp` TIMESTAMP COMMENT 'Date‑time of the latest modification to the depreciation area record.',
    CONSTRAINT pk_depreciation_area PRIMARY KEY(`depreciation_area_id`)
) COMMENT 'Master reference table for depreciation_area. Referenced by depreciation_area_id.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`finance`.`legal_entity` (
    `legal_entity_id` BIGINT COMMENT 'Primary key for legal_entity',
    `parent_entity_id` BIGINT COMMENT 'Identifier of the parent legal entity in corporate hierarchy, if any.',
    `parent_legal_entity_id` BIGINT COMMENT 'Self-referencing FK on legal_entity (parent_legal_entity_id)',
    `address_line1` STRING COMMENT 'First line of the entitys primary mailing address.',
    `address_line2` STRING COMMENT 'Second line of the entitys primary mailing address (optional).',
    `asc_980_applicable_flag` BOOLEAN COMMENT 'True if the entity is subject to FASB ASC 980 utility accounting standards.',
    `city` STRING COMMENT 'City of the entitys primary address.',
    `cost_center_code` STRING COMMENT 'Internal cost center code associated with the entity.',
    `country_code` STRING COMMENT 'Three‑letter ISO country code for the entitys primary address.',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when the legal entity record was first created in the system.',
    `credit_rating` STRING COMMENT 'External credit rating assigned to the entity.',
    `dba_name` STRING COMMENT 'Alternate trade name under which the entity operates.',
    `dissolution_date` DATE COMMENT 'Date the entity was legally dissolved, if applicable.',
    `entity_type` STRING COMMENT 'Category of the legal entity based on its legal structure.',
    `ferc_form1_reporting_flag` BOOLEAN COMMENT 'True if the entity is required to report under FERC Form 1.',
    `financial_reporting_currency` STRING COMMENT 'ISO 4217 currency code used for the entitys financial reporting.',
    `fiscal_year_end_month` STRING COMMENT 'Month (1‑12) that marks the end of the entitys fiscal year.',
    `industry_code` STRING COMMENT 'Standard industry classification code for the entity.',
    `legal_name` STRING COMMENT 'Full legal name as registered with the jurisdiction.',
    `legal_entity_name` STRING COMMENT 'Primary display name of the legal entity (e.g., "Acme Energy Corp").',
    `postal_code` STRING COMMENT 'Postal or ZIP code of the entitys primary address.',
    `primary_contact_email` STRING COMMENT 'Email address of the primary contact.',
    `primary_contact_name` STRING COMMENT 'Name of the primary contact person for the entity.',
    `primary_contact_phone` STRING COMMENT 'Phone number of the primary contact.',
    `primary_contact_role` STRING COMMENT 'Job title or role of the primary contact within the entity.',
    `rating_agency` STRING COMMENT 'Agency that provided the credit rating (e.g., S&P, Moodys).',
    `registration_date` DATE COMMENT 'Date the entity was officially registered.',
    `state_of_incorporation` STRING COMMENT 'U.S. state where the entity was legally incorporated.',
    `state_province` STRING COMMENT 'State or province of the entitys primary address.',
    `legal_entity_status` STRING COMMENT 'Current operational status of the legal entity.',
    `tax_exempt_flag` BOOLEAN COMMENT 'Indicates whether the entity is exempt from certain taxes.',
    `tax_identifier` STRING COMMENT 'Federal tax identification number for the entity.',
    `updated_timestamp` TIMESTAMP COMMENT 'Timestamp of the most recent update to the legal entity record.',
    `website_url` STRING COMMENT 'Public website address of the legal entity.',
    CONSTRAINT pk_legal_entity PRIMARY KEY(`legal_entity_id`)
) COMMENT 'Master reference table for legal_entity. Referenced by sender_legal_entity_id.';

